window.EXTRA_MEALS = [{"id":"qm-steak-frites","name":"Steak frites","cat":"Beef","country":"France","instr":"Peel the potatoes and cut them into 1cm sticks. Rinse in cold water and dry well with a clean tea towel.\r\nHeat the oil to 160C and fry the chips in batches for 6 minutes until soft but not coloured. Drain on kitchen paper.\r\nTake the steaks out of the fridge 15 minutes before cooking. Season with salt and pepper.\r\nRaise the oil to 180C and fry the chips again for 3 minutes until golden and crisp. Drain and salt.\r\nHeat a heavy frying pan until very hot, add a knob of butter and cook the steaks for 2 to 3 minutes on each side for medium-rare. Rest for 3 minutes.\r\nMelt the rest of the butter in the pan with the finely chopped shallot and parsley, spoon over the steaks and serve with the chips.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Steak_frites.jpg/960px-Steak_frites.jpg","tags":["Classic","Meat"],"yt":"","src":"","ingr":[{"n":"Sirloin Steak","m":"720g"},{"n":"Floury Potatoes","m":"1kg"},{"n":"Sunflower Oil","m":"For frying"},{"n":"Butter","m":"30g"},{"n":"Shallots","m":"1"},{"n":"Parsley","m":"2 tbs chopped"},{"n":"Salt","m":"to taste"},{"n":"Black Pepper","m":"to taste"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Steak_frites.jpg","artist":"LWY","license":"CC BY 2.0"}},{"id":"qm-blanquette-de-veau","name":"Blanquette de veau","cat":"Beef","country":"France","instr":"Put the veal in a large pot, cover with cold water and bring to the boil. Skim off the foam.\r\nAdd the carrots cut in chunks, the onion studded with the cloves and the bouquet garni. Simmer gently for 1 hour 30 minutes.\r\nCook the rice. Fry the quartered mushrooms in a little butter for 5 minutes.\r\nLift out the meat and carrots and keep warm. Strain and keep 750ml of the cooking stock.\r\nMelt the butter in the pot, stir in the flour and cook for 1 minute, then whisk in the stock and simmer for 10 minutes until thickened.\r\nOff the heat, mix the crème fraîche with the egg yolk and lemon juice, stir into the sauce, add the meat, carrots and mushrooms and warm through without boiling. Serve with the rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Blanquette_de_veau_%C3%A0_l%27ancienne_04.jpg/960px-Blanquette_de_veau_%C3%A0_l%27ancienne_04.jpg","tags":["Classic","Stew"],"yt":"","src":"","ingr":[{"n":"Veal","m":"1kg"},{"n":"Carrots","m":"3"},{"n":"Onion","m":"1"},{"n":"Cloves","m":"2"},{"n":"Bouquet Garni","m":"1"},{"n":"Mushrooms","m":"200g"},{"n":"Butter","m":"40g"},{"n":"Plain Flour","m":"40g"},{"n":"Creme Fraiche","m":"200ml"},{"n":"Egg Yolks","m":"1"},{"n":"Lemon","m":"1/2"},{"n":"Rice","m":"300g"}],"time":120,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Blanquette_de_veau_%C3%A0_l%27ancienne_04.jpg","artist":"Arnaud 25","license":"CC BY-SA 4.0"}},{"id":"qm-hachis-parmentier","name":"Hachis parmentier","cat":"Beef","country":"France","instr":"Boil the peeled potatoes in salted water for 20 minutes until tender.\r\nMeanwhile fry the chopped onions in a little butter for 5 minutes, add the garlic and the minced beef and cook for 8 minutes, breaking it up. Stir in the tomato purée and season.\r\nMash the potatoes with the hot milk, the butter and the nutmeg. Season.\r\nHeat the oven to 200C. Spread the meat in a baking dish, cover with the mash and sprinkle with the grated cheese.\r\nBake for 20 minutes until golden.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Hachis_parmentier_01.jpg/960px-Hachis_parmentier_01.jpg","tags":["Classic","Bake"],"yt":"","src":"","ingr":[{"n":"Floury Potatoes","m":"1kg"},{"n":"Minced Beef","m":"600g"},{"n":"Onions","m":"2"},{"n":"Garlic","m":"2 cloves"},{"n":"Tomato Puree","m":"1 tbs"},{"n":"Milk","m":"200ml"},{"n":"Butter","m":"50g"},{"n":"Gruyère","m":"80g"},{"n":"Nutmeg","m":"1 pinch"},{"n":"Salt","m":"to taste"},{"n":"Black Pepper","m":"to taste"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Hachis_parmentier_01.jpg","artist":"Bycro","license":"CC BY-SA 4.0"}},{"id":"qm-quiche-lorraine","name":"Quiche lorraine","cat":"Pork","country":"France","instr":"Heat the oven to 200C. Line a tart tin with the pastry and prick the base with a fork.\r\nFry the lardons in a dry pan for 5 minutes and drain.\r\nWhisk the eggs with the cream, milk, nutmeg and pepper.\r\nScatter the lardons and grated cheese over the pastry and pour over the egg mixture.\r\nBake for 30 minutes until set and golden. Serve warm with a green salad dressed with vinaigrette.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/54._Quiche_lorraine.jpg/960px-54._Quiche_lorraine.jpg","tags":["Classic","Tart"],"yt":"","src":"","ingr":[{"n":"Shortcrust Pastry","m":"1 sheet"},{"n":"Bacon Lardon","m":"200g"},{"n":"Eggs","m":"3"},{"n":"Double Cream","m":"200ml"},{"n":"Milk","m":"100ml"},{"n":"Gruyère","m":"60g"},{"n":"Nutmeg","m":"1 pinch"},{"n":"Black Pepper","m":"to taste"},{"n":"Lettuce","m":"1"},{"n":"Vinaigrette Dressing","m":"3 tbs"}],"time":50,"photo":{"page":"https://commons.wikimedia.org/wiki/File:54._Quiche_lorraine.jpg","artist":"Claude Humbert","license":"CC BY-SA 4.0"}},{"id":"qm-croque-monsieur","name":"Croque-monsieur","cat":"Pork","country":"France","instr":"Make a quick béchamel: melt half the butter, stir in the flour, then whisk in the milk and cook for 3 minutes until thick. Season with nutmeg.\r\nHeat the oven grill. Butter the bread on one side.\r\nLay 4 slices buttered side down, spread with a little béchamel, add a slice of ham and some cheese, then close with the other slices, buttered side up.\r\nSpread the rest of the béchamel on top and cover with the remaining cheese.\r\nGrill for 8 minutes until bubbling and golden. Serve with a green salad.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/db/Sandwich-Mixto.jpg/960px-Sandwich-Mixto.jpg","tags":["Quick","Sandwich"],"yt":"","src":"","ingr":[{"n":"White Bread","m":"8 slices"},{"n":"Ham","m":"4 slices"},{"n":"Gruyère","m":"150g"},{"n":"Butter","m":"30g"},{"n":"Milk","m":"250ml"},{"n":"Plain Flour","m":"20g"},{"n":"Nutmeg","m":"1 pinch"},{"n":"Lettuce","m":"1"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Sandwich-Mixto.jpg","artist":"User:Tamorlan","license":"Public domain"}},{"id":"qm-roast-chicken-with-potatoes","name":"Roast chicken with potatoes","cat":"Chicken","country":"France","instr":"Heat the oven to 210C. Rub the chicken with the soft butter, salt and pepper and put the halved lemon and two thyme sprigs inside.\r\nCut the potatoes into chunks and toss with the olive oil, the unpeeled garlic cloves, thyme, salt and pepper.\r\nPut the chicken in a roasting tin with the potatoes around it.\r\nRoast for 1 hour 15 minutes, basting twice, until the juices run clear.\r\nRest the chicken for 10 minutes, then carve and serve with the potatoes and the cooking juices.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Max%27s_Roasted_Chicken_-_Evan_Swigart.jpg/960px-Max%27s_Roasted_Chicken_-_Evan_Swigart.jpg","tags":["Classic","Roast"],"yt":"","src":"","ingr":[{"n":"Chicken","m":"1.5kg"},{"n":"Potatoes","m":"1kg"},{"n":"Garlic","m":"6 cloves"},{"n":"Thyme","m":"4 sprigs"},{"n":"Butter","m":"30g"},{"n":"Olive Oil","m":"3 tbs"},{"n":"Lemon","m":"1"},{"n":"Salt","m":"to taste"},{"n":"Black Pepper","m":"to taste"}],"time":90,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Max%27s_Roasted_Chicken_-_Evan_Swigart.jpg","artist":"Evan Swigart from Chicago, USA","license":"CC BY 2.0"}},{"id":"qm-beef-and-carrot-stew","name":"Beef and carrot stew","cat":"Beef","country":"France","instr":"Brown the beef in the oil in a casserole in batches. Set aside.\r\nFry the lardons and sliced onions for 5 minutes, then return the beef, sprinkle with flour and stir for 1 minute.\r\nPour in the wine and stock, add the bouquet garni, cover and simmer gently for 1 hour.\r\nAdd the carrots cut into thick rounds and simmer for 1 hour more until the beef is very tender.\r\nBoil the potatoes for 20 minutes and serve with the stew.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/34/Sztufada_wo%C5%82owa.JPG/960px-Sztufada_wo%C5%82owa.JPG","tags":["Stew","Classic"],"yt":"","src":"","ingr":[{"n":"Beef","m":"1kg"},{"n":"Carrots","m":"1kg"},{"n":"Onions","m":"2"},{"n":"Bacon Lardon","m":"100g"},{"n":"Plain Flour","m":"1 tbs"},{"n":"Dry White Wine","m":"250ml"},{"n":"Beef Stock","m":"500ml"},{"n":"Bouquet Garni","m":"1"},{"n":"Olive Oil","m":"2 tbs"},{"n":"Potatoes","m":"600g"}],"time":150,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Sztufada_wo%C5%82owa.JPG","artist":"Gżdacz","license":"CC BY-SA 3.0"}},{"id":"qm-pot-au-feu","name":"Pot-au-feu","cat":"Beef","country":"France","instr":"Put the beef in a large pot, cover with 4 litres of cold water and bring slowly to the boil. Skim well.\r\nAdd the onion studded with cloves, the bouquet garni, peppercorns and salt. Simmer gently for 2 hours 30 minutes.\r\nAdd the carrots, leeks and turnips and simmer for 40 minutes more.\r\nCook the potatoes in a ladle of the broth for 25 minutes.\r\nServe the broth first, then the sliced meat and vegetables with mustard and coarse salt.","thumb":"https://upload.wikimedia.org/wikipedia/commons/5/51/Pot-au-feu2.jpg","tags":["Classic","Stew","Soup"],"yt":"","src":"","ingr":[{"n":"Beef Shin","m":"1.2kg"},{"n":"Carrots","m":"6"},{"n":"Leek","m":"2"},{"n":"Turnips","m":"4"},{"n":"Potatoes","m":"600g"},{"n":"Onion","m":"1"},{"n":"Cloves","m":"3"},{"n":"Bouquet Garni","m":"1"},{"n":"Peppercorns","m":"1 tsp"},{"n":"Coarse Salt","m":"1 tbs"},{"n":"Dijon Mustard","m":"to serve"}],"time":210,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pot-au-feu2.jpg","artist":"Andre","license":"CC BY-SA 3.0"}},{"id":"qm-tartiflette","name":"Tartiflette","cat":"Pork","country":"France","instr":"Boil the potatoes in their skins for 20 minutes, then peel and slice them.\r\nFry the lardons and sliced onions for 10 minutes until golden, then add the wine and let it bubble for 2 minutes.\r\nHeat the oven to 200C. Layer the potatoes with the onion mixture and the crème fraîche in a baking dish. Season with pepper.\r\nCut the cheese in half horizontally and lay it rind side up on top.\r\nBake for 25 minutes until bubbling. Serve with a green salad.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Tartiflette.jpg/960px-Tartiflette.jpg","tags":["Bake","Cheese"],"yt":"","src":"","ingr":[{"n":"Potatoes","m":"1.2kg"},{"n":"Bacon Lardon","m":"200g"},{"n":"Onions","m":"2"},{"n":"Dry White Wine","m":"100ml"},{"n":"Brie","m":"450g"},{"n":"Creme Fraiche","m":"100ml"},{"n":"Black Pepper","m":"to taste"},{"n":"Lettuce","m":"1"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Tartiflette.jpg","artist":"Chrisjt","license":"CC BY-SA 2.0 de"}},{"id":"qm-lamb-navarin","name":"Lamb navarin","cat":"Lamb","country":"France","instr":"Brown the lamb in the oil in batches. Add the chopped onions and garlic and cook for 3 minutes.\r\nSprinkle over the flour, stir in the tomato purée, then add the stock and bouquet garni. Cover and simmer for 1 hour.\r\nAdd the potatoes and carrots and cook for 30 minutes more.\r\nAdd the peas for the last 5 minutes. Season and serve.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Navarin_01.jpg/960px-Navarin_01.jpg","tags":["Stew","Classic"],"yt":"","src":"","ingr":[{"n":"Lamb Shoulder","m":"1kg"},{"n":"Onions","m":"2"},{"n":"Garlic","m":"2 cloves"},{"n":"Plain Flour","m":"1 tbs"},{"n":"Tomato Puree","m":"1 tbs"},{"n":"Chicken Stock","m":"600ml"},{"n":"Bouquet Garni","m":"1"},{"n":"New Potatoes","m":"600g"},{"n":"Carrots","m":"4"},{"n":"Frozen Peas","m":"200g"},{"n":"Olive Oil","m":"2 tbs"}],"time":120,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Navarin_01.jpg","artist":"Arnaud 25","license":"CC BY-SA 4.0"}},{"id":"qm-chicken-with-cider-and-cream","name":"Chicken with cider and cream","cat":"Chicken","country":"France","instr":"Brown the seasoned chicken in half the butter for 10 minutes. Add the chopped shallots and cook for 2 minutes.\r\nPour in the cider, cover and simmer for 25 minutes. Cook the rice.\r\nFry the sliced mushrooms and apple wedges in the remaining butter for 6 minutes.\r\nLift out the chicken, boil the sauce for 3 minutes, stir in the crème fraîche and simmer for 2 minutes.\r\nReturn the chicken with the mushrooms and apples and serve with the rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Poulet_vallee_d%27auge_cropped.png/960px-Poulet_vallee_d%27auge_cropped.png","tags":["Classic"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"8"},{"n":"Butter","m":"30g"},{"n":"Shallots","m":"3"},{"n":"Mushrooms","m":"250g"},{"n":"Cider","m":"300ml"},{"n":"Creme Fraiche","m":"200ml"},{"n":"Apples","m":"2"},{"n":"Rice","m":"300g"},{"n":"Salt","m":"to taste"}],"time":50,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Poulet_vallee_d%27auge_cropped.png","artist":"user:Popo le Chien / user:Ludo29","license":"CC BY-SA 3.0"}},{"id":"qm-salmon-en-papillote","name":"Salmon en papillote","cat":"Seafood","country":"France","instr":"Heat the oven to 200C and cook the rice.\r\nPut each salmon fillet on a large sheet of baking paper with a few lemon slices, halved cherry tomatoes and dill.\r\nDrizzle with olive oil, season and fold into sealed parcels.\r\nBake for 15 minutes. Open the parcels at the table and serve with the rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Papillotes_de_Lyon.JPG/960px-Papillotes_de_Lyon.JPG","tags":["Quick","Fish"],"yt":"","src":"","ingr":[{"n":"Salmon","m":"4 fillets"},{"n":"Lemon","m":"1"},{"n":"Cherry Tomatoes","m":"200g"},{"n":"Dill","m":"1 bunch"},{"n":"Olive Oil","m":"2 tbs"},{"n":"Rice","m":"300g"},{"n":"Salt","m":"to taste"},{"n":"Black Pepper","m":"to taste"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Papillotes_de_Lyon.JPG","artist":"Pierre Hansk","license":"CC BY-SA 3.0"}},{"id":"qm-cod-with-lemon-butter-and-crushed-potatoes","name":"Cod with lemon butter and crushed potatoes","cat":"Seafood","country":"France","instr":"Boil the potatoes for 18 minutes, adding the green beans for the last 6 minutes. Drain.\r\nRoughly crush the potatoes with a fork, the olive oil and half the parsley. Season.\r\nPat the cod dry, season and fry in a little butter for 3 to 4 minutes on each side.\r\nAdd the rest of the butter to the pan with the lemon juice and parsley and spoon over the fish.\r\nServe the cod with the crushed potatoes and beans.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Sous_vide_cod_2018.jpg/960px-Sous_vide_cod_2018.jpg","tags":["Fish"],"yt":"","src":"","ingr":[{"n":"Cod","m":"4 fillets"},{"n":"New Potatoes","m":"800g"},{"n":"Butter","m":"60g"},{"n":"Lemon","m":"1"},{"n":"Parsley","m":"3 tbs chopped"},{"n":"Olive Oil","m":"3 tbs"},{"n":"Green Beans","m":"300g"},{"n":"Salt","m":"to taste"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Sous_vide_cod_2018.jpg","artist":"https://sousvideguy.com/","license":"CC BY 2.0"}},{"id":"qm-ham-and-cheese-pasta-bake","name":"Ham and cheese pasta bake","cat":"Pasta","country":"France","instr":"Cook the pasta for 2 minutes less than the packet says. Drain.\r\nMake a béchamel: melt the butter, stir in the flour, whisk in the milk and simmer for 5 minutes. Season with nutmeg.\r\nHeat the oven to 200C. Mix the pasta with the sauce, the diced ham and half the cheese.\r\nPour into a baking dish, top with the rest of the cheese and bake for 20 minutes until golden.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Original_Mac_n_Cheese_.jpg/960px-Original_Mac_n_Cheese_.jpg","tags":["Bake","Family"],"yt":"","src":"","ingr":[{"n":"Macaroni","m":"400g"},{"n":"Ham","m":"200g"},{"n":"Milk","m":"500ml"},{"n":"Butter","m":"30g"},{"n":"Plain Flour","m":"30g"},{"n":"Gruyère","m":"150g"},{"n":"Nutmeg","m":"1 pinch"},{"n":"Salt","m":"to taste"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Original_Mac_n_Cheese_.jpg","artist":"Texasfoodgawker","license":"CC BY-SA 4.0"}},{"id":"qm-steak-au-poivre","name":"Steak au poivre","cat":"Beef","country":"France","instr":"Cut the potatoes into wedges, toss in the oil and roast at 220C for 30 minutes.\r\nCrush the peppercorns coarsely and press them on both sides of the steaks.\r\nFry the steaks in the butter for 3 minutes on each side. Keep warm.\r\nPour the brandy into the pan, then add the stock and cream. Bubble for 3 minutes until the sauce coats a spoon.\r\nPour the sauce over the steaks and serve with the potatoes.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/Steak_Au_Poivre.jpg/960px-Steak_Au_Poivre.jpg","tags":["Classic","Quick"],"yt":"","src":"","ingr":[{"n":"Fillet Of Steak","m":"640g"},{"n":"Peppercorns","m":"2 tbs"},{"n":"Butter","m":"20g"},{"n":"Brandy","m":"3 tbs"},{"n":"Double Cream","m":"150ml"},{"n":"Beef Stock","m":"100ml"},{"n":"Potatoes","m":"800g"},{"n":"Sunflower Oil","m":"2 tbs"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Steak_Au_Poivre.jpg","artist":"Mark Mitchell","license":"CC BY 2.0"}},{"id":"qm-turkey-escalopes-with-mushroom-cream-sauce","name":"Turkey escalopes with mushroom cream sauce","cat":"Chicken","country":"France","instr":"Cook the pasta following the packet instructions.\r\nSeason the turkey and fry in the butter for 4 minutes on each side. Set aside.\r\nIn the same pan cook the chopped shallots and sliced mushrooms for 5 minutes.\r\nStir in the crème fraîche, simmer for 2 minutes and return the turkey to warm through.\r\nServe with the pasta.","thumb":"https://upload.wikimedia.org/wikipedia/commons/e/e4/Creamy_Mushroom_Pasta.jpg","tags":["Quick"],"yt":"","src":"","ingr":[{"n":"Turkey","m":"4 escalopes"},{"n":"Mushrooms","m":"250g"},{"n":"Shallots","m":"2"},{"n":"Creme Fraiche","m":"200ml"},{"n":"Butter","m":"20g"},{"n":"Tagliatelle","m":"350g"},{"n":"Salt","m":"to taste"},{"n":"Black Pepper","m":"to taste"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Creamy_Mushroom_Pasta.jpg","artist":"Sharon Chen","license":"CC BY 3.0"}},{"id":"qm-homemade-chicken-cordon-bleu","name":"Homemade chicken cordon bleu","cat":"Chicken","country":"France","instr":"Boil the potatoes for 20 minutes and mash with the butter and hot milk.\r\nSlice each chicken breast horizontally to open it like a book and flatten slightly.\r\nFill with a slice of ham and a slice of cheese and close.\r\nCoat each one in flour, then beaten egg, then breadcrumbs.\r\nFry in the oil for 6 to 7 minutes on each side over medium heat until cooked through. Serve with the mash.","thumb":"https://upload.wikimedia.org/wikipedia/commons/c/cd/Cordon-bleu-2.jpg","tags":["Family"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"4"},{"n":"Ham","m":"4 slices"},{"n":"Emmentaler Cheese","m":"4 slices"},{"n":"Plain Flour","m":"50g"},{"n":"Eggs","m":"2"},{"n":"Breadcrumbs","m":"100g"},{"n":"Sunflower Oil","m":"4 tbs"},{"n":"Potatoes","m":"800g"},{"n":"Butter","m":"30g"},{"n":"Milk","m":"150ml"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Cordon-bleu-2.jpg","artist":"Rainer Zenz","license":"GPL"}},{"id":"qm-fish-fingers-with-mash-and-peas","name":"Fish fingers with mash and peas","cat":"Seafood","country":"France","instr":"Boil the potatoes for 20 minutes, then mash with the butter and hot milk.\r\nCut the fish into thick fingers, coat in flour, beaten egg and breadcrumbs.\r\nFry in the oil for 3 minutes on each side until golden.\r\nCook the peas in boiling water for 3 minutes.\r\nServe the fish with the mash, peas and lemon wedges.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/Fishfinger_classic_fried_2.jpg/960px-Fishfinger_classic_fried_2.jpg","tags":["Family"],"yt":"","src":"","ingr":[{"n":"White Fish Fillets","m":"600g"},{"n":"Plain Flour","m":"50g"},{"n":"Eggs","m":"2"},{"n":"Breadcrumbs","m":"120g"},{"n":"Sunflower Oil","m":"4 tbs"},{"n":"Floury Potatoes","m":"800g"},{"n":"Milk","m":"150ml"},{"n":"Butter","m":"30g"},{"n":"Frozen Peas","m":"300g"},{"n":"Lemon","m":"1"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Fishfinger_classic_fried_2.jpg","artist":"Superbass","license":"CC BY-SA 4.0"}},{"id":"qm-sausages-with-mashed-potatoes-and-onion-gravy","name":"Sausages with mashed potatoes and onion gravy","cat":"Pork","country":"France","instr":"Boil the potatoes for 20 minutes and mash with the milk and half the butter.\r\nFry the sausages over medium heat for 15 minutes, turning often.\r\nIn another pan soften the sliced onions in the rest of the butter for 10 minutes. Stir in the flour, then the stock and mustard, and simmer for 5 minutes.\r\nServe the sausages on the mash with the onion gravy.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Sausage_and_mash_with_peas.jpg/960px-Sausage_and_mash_with_peas.jpg","tags":["Family"],"yt":"","src":"","ingr":[{"n":"Sausages","m":"8"},{"n":"Floury Potatoes","m":"1kg"},{"n":"Milk","m":"150ml"},{"n":"Butter","m":"40g"},{"n":"Onions","m":"2"},{"n":"Beef Stock","m":"300ml"},{"n":"Plain Flour","m":"1 tbs"},{"n":"Wholegrain Mustard","m":"1 tbs"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Sausage_and_mash_with_peas.jpg","artist":"anokarina","license":"CC BY-SA 2.0"}},{"id":"qm-sausages-and-lentils","name":"Sausages and lentils","cat":"Pork","country":"France","instr":"Fry the lardons, chopped onion and diced carrots for 5 minutes.\r\nAdd the rinsed lentils, the stock and the bouquet garni. Simmer for 30 minutes.\r\nMeanwhile brown the sausages in a frying pan for 10 minutes, then add them to the lentils for the last 10 minutes.\r\nStir in the mustard and season before serving.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Petit_sal%C3%A9_02.jpg/960px-Petit_sal%C3%A9_02.jpg","tags":["Stew"],"yt":"","src":"","ingr":[{"n":"Sausages","m":"8"},{"n":"French Lentils","m":"300g"},{"n":"Carrots","m":"2"},{"n":"Onion","m":"1"},{"n":"Bacon Lardon","m":"100g"},{"n":"Bouquet Garni","m":"1"},{"n":"Chicken Stock","m":"900ml"},{"n":"Dijon Mustard","m":"1 tsp"}],"time":50,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Petit_sal%C3%A9_02.jpg","artist":"Arnaud 25","license":"CC BY-SA 4.0"}},{"id":"qm-duck-parmentier","name":"Duck parmentier","cat":"Chicken","country":"France","instr":"Boil the potatoes for 20 minutes and mash with the milk and butter.\r\nWarm the duck legs in a pan to melt the fat, then shred the meat, discarding the skin and bones.\r\nFry the chopped shallots in a spoon of duck fat for 3 minutes and mix with the duck and parsley.\r\nHeat the oven to 200C. Spread the duck in a dish, cover with the mash and sprinkle with breadcrumbs.\r\nBake for 25 minutes until golden.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Hachis_parmentier_01.jpg/960px-Hachis_parmentier_01.jpg","tags":["Bake"],"yt":"","src":"","ingr":[{"n":"Duck Legs","m":"4"},{"n":"Floury Potatoes","m":"1.2kg"},{"n":"Milk","m":"200ml"},{"n":"Butter","m":"30g"},{"n":"Shallots","m":"3"},{"n":"Parsley","m":"2 tbs chopped"},{"n":"Breadcrumbs","m":"3 tbs"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Hachis_parmentier_01.jpg","artist":"Bycro","license":"CC BY-SA 4.0"}},{"id":"qm-mussels-with-white-wine-and-fries","name":"Mussels with white wine and fries","cat":"Seafood","country":"France","instr":"Cut the potatoes into sticks and fry twice: 6 minutes at 160C, then 3 minutes at 180C. Drain and salt.\r\nScrub the mussels and throw away any that stay open when tapped.\r\nSoften the shallots and garlic in the butter in a large pot for 3 minutes. Add the wine and bring to the boil.\r\nAdd the mussels, cover and cook for 5 minutes, shaking the pot, until they open.\r\nSprinkle with parsley and serve with the fries.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Moules_marini%C3%A8res_01.jpg/960px-Moules_marini%C3%A8res_01.jpg","tags":["Classic","Shellfish"],"yt":"","src":"","ingr":[{"n":"Mussels","m":"2kg"},{"n":"Shallots","m":"3"},{"n":"Garlic","m":"2 cloves"},{"n":"Dry White Wine","m":"200ml"},{"n":"Butter","m":"30g"},{"n":"Parsley","m":"4 tbs chopped"},{"n":"Floury Potatoes","m":"1kg"},{"n":"Sunflower Oil","m":"For frying"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Moules_marini%C3%A8res_01.jpg","artist":"Arnaud 25","license":"CC BY-SA 4.0"}},{"id":"qm-pork-tenderloin-with-mustard-sauce","name":"Pork tenderloin with mustard sauce","cat":"Pork","country":"France","instr":"Boil the potatoes for 20 minutes. Steam the green beans for 8 minutes.\r\nBrown the pork in the butter on all sides for 5 minutes, then cover and cook gently for 15 minutes, turning twice.\r\nRemove the pork and rest it. Cook the chopped shallots in the pan for 2 minutes, add the wine and reduce by half.\r\nStir in both mustards and the crème fraîche and simmer for 2 minutes.\r\nSlice the pork and serve with the sauce, potatoes and beans.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Pork_tenderloin_with_onion_sauce.jpg/960px-Pork_tenderloin_with_onion_sauce.jpg","tags":["Classic"],"yt":"","src":"","ingr":[{"n":"Pork Tenderloin","m":"700g"},{"n":"Dijon Mustard","m":"2 tbs"},{"n":"Wholegrain Mustard","m":"1 tbs"},{"n":"Creme Fraiche","m":"200ml"},{"n":"Shallots","m":"2"},{"n":"Dry White Wine","m":"100ml"},{"n":"Butter","m":"20g"},{"n":"Green Beans","m":"400g"},{"n":"Potatoes","m":"600g"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pork_tenderloin_with_onion_sauce.jpg","artist":"chispita_666 from Seattle, USA","license":"CC BY 2.0"}},{"id":"qm-cauliflower-cheese-gratin","name":"Cauliflower cheese gratin","cat":"Vegetarian","country":"France","instr":"Cut the cauliflower into florets and boil for 6 minutes. Drain well.\r\nMelt the butter, stir in the flour, then whisk in the milk and simmer for 5 minutes. Stir in the mustard, nutmeg and two thirds of the cheese.\r\nHeat the oven to 200C. Put the cauliflower in a dish and pour over the sauce.\r\nTop with the rest of the cheese and the breadcrumbs and bake for 20 minutes. Serve with bread.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Cauliflower_cheese_side_dish.jpg/960px-Cauliflower_cheese_side_dish.jpg","tags":["Bake","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Cauliflower","m":"1 large"},{"n":"Milk","m":"600ml"},{"n":"Butter","m":"40g"},{"n":"Plain Flour","m":"40g"},{"n":"Cheddar Cheese","m":"150g"},{"n":"Dijon Mustard","m":"1 tsp"},{"n":"Nutmeg","m":"1 pinch"},{"n":"Breadcrumbs","m":"3 tbs"},{"n":"Crusty Bread","m":"1"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Cauliflower_cheese_side_dish.jpg","artist":"AnemoneProjectors - Peter O'Connor (talk; Flickr)","license":"CC BY-SA 2.0"}},{"id":"qm-tomato-and-mustard-tart","name":"Tomato and mustard tart","cat":"Vegetarian","country":"France","instr":"Heat the oven to 200C and line a tart tin with the pastry.\r\nSpread the mustard over the base and sprinkle with the grated cheese.\r\nSlice the tomatoes and arrange them in overlapping circles.\r\nSprinkle with thyme, drizzle with olive oil and season.\r\nBake for 35 minutes. Serve warm with a green salad.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/58/Pr%C3%A9paration_d%27une_tarte_%C3%A0_la_tomate_%2807%29_-_r%C3%A9sultat_%28gros_plan%29.jpg/960px-Pr%C3%A9paration_d%27une_tarte_%C3%A0_la_tomate_%2807%29_-_r%C3%A9sultat_%28gros_plan%29.jpg","tags":["Tart","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Shortcrust Pastry","m":"1 sheet"},{"n":"Dijon Mustard","m":"3 tbs"},{"n":"Tomatoes","m":"6"},{"n":"Gruyère","m":"80g"},{"n":"Thyme","m":"1 tsp"},{"n":"Olive Oil","m":"2 tbs"},{"n":"Lettuce","m":"1"}],"time":45,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pr%C3%A9paration_d%27une_tarte_%C3%A0_la_tomate_(07)_-_r%C3%A9sultat_(gros_plan).jpg","artist":"Benoît Prieur","license":"CC0"}},{"id":"qm-salmon-cream-pasta","name":"Salmon cream pasta","cat":"Pasta","country":"France","instr":"Cook the pasta following the packet instructions.\r\nCut the salmon into cubes and fry in the oil for 3 minutes.\r\nAdd the crème fraîche, lemon zest and a little juice and simmer for 2 minutes.\r\nDrain the pasta, keeping a little cooking water, and toss with the sauce and dill, loosening with the water if needed.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f8/Pasta_with_cold-smoked_salmon_and_peas_in_Loviisa.jpg/960px-Pasta_with_cold-smoked_salmon_and_peas_in_Loviisa.jpg","tags":["Quick","Fish"],"yt":"","src":"","ingr":[{"n":"Tagliatelle","m":"400g"},{"n":"Salmon","m":"400g"},{"n":"Creme Fraiche","m":"200ml"},{"n":"Lemon","m":"1"},{"n":"Dill","m":"2 tbs chopped"},{"n":"Olive Oil","m":"1 tbs"},{"n":"Salt","m":"to taste"},{"n":"Black Pepper","m":"to taste"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pasta_with_cold-smoked_salmon_and_peas_in_Loviisa.jpg","artist":"JIP","license":"CC BY-SA 4.0"}},{"id":"qm-salt-cod-brandade","name":"Salt cod brandade","cat":"Seafood","country":"France","instr":"Soak the salt cod in cold water for 24 hours, changing the water three times.\r\nPoach the cod in the milk with the garlic for 10 minutes. Boil the potatoes for 20 minutes.\r\nFlake the fish, removing skin and bones, and mash it with the potatoes, the garlic, the olive oil and enough of the milk to make it creamy.\r\nHeat the oven to 200C, spread in a dish, sprinkle with breadcrumbs and bake for 15 minutes. Serve with a green salad.","thumb":"https://upload.wikimedia.org/wikipedia/commons/6/68/Brandade5.jpg","tags":["Bake","Fish"],"yt":"","src":"","ingr":[{"n":"Salt Cod","m":"500g"},{"n":"Floury Potatoes","m":"600g"},{"n":"Garlic","m":"3 cloves"},{"n":"Milk","m":"300ml"},{"n":"Olive Oil","m":"100ml"},{"n":"Breadcrumbs","m":"3 tbs"},{"n":"Lettuce","m":"1"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Brandade5.jpg","artist":"","license":"CC BY-SA 3.0"}},{"id":"qm-provencal-beef-daube","name":"Provençal beef daube","cat":"Beef","country":"France","instr":"Put the beef in a bowl with the wine, sliced onions and carrots, garlic, orange zest and bouquet garni. Marinate overnight.\r\nFry the lardons in a casserole. Drain the meat, keeping the wine, and brown it with the lardons.\r\nAdd the vegetables and wine, cover and simmer very gently for 2 hours 30 minutes.\r\nAdd the olives for the last 15 minutes. Serve with the pasta.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Daube_proven%C3%A7ale_03.jpg/960px-Daube_proven%C3%A7ale_03.jpg","tags":["Stew","Classic"],"yt":"","src":"","ingr":[{"n":"Beef","m":"1.2kg"},{"n":"Red Wine","m":"750ml"},{"n":"Onions","m":"2"},{"n":"Carrots","m":"3"},{"n":"Garlic","m":"3 cloves"},{"n":"Orange Zest","m":"1 strip"},{"n":"Bouquet Garni","m":"1"},{"n":"Bacon Lardon","m":"150g"},{"n":"Black Olives","m":"100g"},{"n":"Tagliatelle","m":"400g"}],"time":180,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Daube_proven%C3%A7ale_03.jpg","artist":"Arnaud 25","license":"CC BY-SA 4.0"}},{"id":"qm-choucroute-garnie","name":"Choucroute garnie","cat":"Pork","country":"France","instr":"Rinse the sauerkraut in cold water and squeeze it dry.\r\nSoften the sliced onion in the goose fat, add the sauerkraut, juniper berries and wine. Cover and cook gently for 45 minutes.\r\nAdd the ham, lardons and sliced kielbasa and cook for 20 minutes more.\r\nBoil the potatoes for 20 minutes and warm the sausages in simmering water for 10 minutes.\r\nServe the sauerkraut topped with the meats and potatoes, with mustard.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Choucroute_d%27Alsace_004.jpg/960px-Choucroute_d%27Alsace_004.jpg","tags":["Classic","Alsace"],"yt":"","src":"","ingr":[{"n":"Sauerkraut","m":"1.2kg"},{"n":"Smoked Ham","m":"400g"},{"n":"Sausages","m":"4"},{"n":"Kielbasa","m":"1"},{"n":"Bacon Lardon","m":"200g"},{"n":"Onion","m":"1"},{"n":"Juniper Berries","m":"8"},{"n":"Dry White Wine","m":"300ml"},{"n":"Potatoes","m":"800g"},{"n":"Goose Fat","m":"2 tbs"}],"time":90,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Choucroute_d%27Alsace_004.jpg","artist":"Arnaud 25","license":"CC BY-SA 4.0"}},{"id":"qm-tarte-flambee","name":"Tarte flambée","cat":"Pork","country":"France","instr":"Mix the flour with the water, the oil and a pinch of salt and knead for 5 minutes. Rest for 10 minutes.\r\nHeat the oven to its maximum (250C) with a baking tray inside.\r\nRoll out the dough very thinly into two rectangles.\r\nMix the crème fraîche, fromage frais and nutmeg and spread on the dough. Top with very thinly sliced onions and the lardons.\r\nBake for 8 to 10 minutes until the edges are crisp.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/Tarte_flamb%C3%A9e_alsacienne_514471722.jpg/960px-Tarte_flamb%C3%A9e_alsacienne_514471722.jpg","tags":["Quick","Alsace"],"yt":"","src":"","ingr":[{"n":"Bread Flour","m":"250g"},{"n":"Water","m":"150ml"},{"n":"Olive Oil","m":"2 tbs"},{"n":"Creme Fraiche","m":"200ml"},{"n":"Fromage Frais","m":"100g"},{"n":"Onions","m":"2"},{"n":"Bacon Lardon","m":"200g"},{"n":"Nutmeg","m":"1 pinch"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Tarte_flamb%C3%A9e_alsacienne_514471722.jpg","artist":"Lulu Durand","license":"CC BY 2.0"}},{"id":"qm-rougail-sausage","name":"Rougail sausage","cat":"Pork","country":"France","instr":"Prick the sausages, cover with water and boil for 10 minutes to remove some fat. Slice them.\r\nBrown the sausage slices in a casserole for 5 minutes. Add the chopped onions and cook for 5 minutes.\r\nAdd the garlic, ginger, turmeric, chilli and thyme, then the chopped tomatoes. Cover and simmer for 25 minutes.\r\nCook the rice and warm the beans. Serve together.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Carri-poulet.jpg/960px-Carri-poulet.jpg","tags":["Spicy","Stew"],"yt":"","src":"","ingr":[{"n":"Sausages","m":"8"},{"n":"Onions","m":"2"},{"n":"Tomatoes","m":"6"},{"n":"Garlic","m":"3 cloves"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Turmeric","m":"1 tsp"},{"n":"Red Chilli","m":"1"},{"n":"Thyme","m":"2 sprigs"},{"n":"Rice","m":"300g"},{"n":"Kidney Beans","m":"400g"}],"time":50,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Carri-poulet.jpg","artist":"ADIKT gameboy from Paris, France","license":"CC BY 2.0"}},{"id":"qm-chicken-colombo","name":"Chicken colombo","cat":"Chicken","country":"France","instr":"Rub the chicken with the curry powder, lime juice, garlic and salt. Leave for 15 minutes.\r\nBrown the chicken in a casserole with a little oil, then add the chopped onions.\r\nAdd the cubed potatoes, thyme, coconut milk and 200ml water. Cover and simmer for 25 minutes.\r\nAdd the courgette in chunks and simmer for 10 minutes more. Serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Carri-poulet.jpg/960px-Carri-poulet.jpg","tags":["Curry","Spicy"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"8"},{"n":"Curry Powder","m":"2 tbs"},{"n":"Onions","m":"2"},{"n":"Garlic","m":"3 cloves"},{"n":"Potatoes","m":"500g"},{"n":"Courgettes","m":"1"},{"n":"Coconut Milk","m":"200ml"},{"n":"Lime","m":"1"},{"n":"Thyme","m":"2 sprigs"},{"n":"Rice","m":"300g"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Carri-poulet.jpg","artist":"ADIKT gameboy from Paris, France","license":"CC BY 2.0"}},{"id":"qm-lentil-salad-with-eggs","name":"Lentil salad with eggs","cat":"Vegetarian","country":"France","instr":"Cook the lentils with the diced carrots in unsalted water for 25 minutes. Drain.\r\nBoil the eggs for 9 minutes, cool and halve.\r\nWhisk the mustard, vinegar and oil with salt and pepper.\r\nToss the warm lentils with the dressing, chopped shallots and parsley. Top with the eggs.","thumb":"https://upload.wikimedia.org/wikipedia/commons/2/2b/Lentil_salad_%287668557930%29.jpg","tags":["Salad","Vegetarian"],"yt":"","src":"","ingr":[{"n":"French Lentils","m":"300g"},{"n":"Eggs","m":"4"},{"n":"Shallots","m":"2"},{"n":"Carrots","m":"2"},{"n":"Parsley","m":"3 tbs chopped"},{"n":"Dijon Mustard","m":"1 tsp"},{"n":"Red Wine Vinegar","m":"2 tbs"},{"n":"Olive Oil","m":"5 tbs"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Lentil_salad_(7668557930).jpg","artist":"Lablascovegmenu from London","license":"CC BY 2.0"}},{"id":"qm-vegetarian-lentil-shepherd-s-pie","name":"Vegetarian lentil shepherd's pie","cat":"Vegetarian","country":"France","instr":"Boil the potatoes for 20 minutes and mash with the milk and butter.\r\nSoften the chopped onion, carrots and garlic in a little oil for 8 minutes.\r\nAdd the lentils, tomatoes, stock and thyme and simmer for 25 minutes until thick.\r\nHeat the oven to 200C. Spread the lentils in a dish, cover with the mash and the grated cheese and bake for 20 minutes.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Homerton_College_-_Shepherd%27s_pie_%28cropped%29.jpg/960px-Homerton_College_-_Shepherd%27s_pie_%28cropped%29.jpg","tags":["Bake","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Brown Lentils","m":"250g"},{"n":"Carrots","m":"2"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Vegetable Stock","m":"300ml"},{"n":"Thyme","m":"1 tsp"},{"n":"Floury Potatoes","m":"1kg"},{"n":"Milk","m":"150ml"},{"n":"Butter","m":"40g"},{"n":"Cheddar Cheese","m":"80g"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Homerton_College_-_Shepherd%27s_pie_(cropped).jpg","artist":"Oxfordian Kissuth","license":"CC BY-SA 3.0"}},{"id":"qm-tuna-pasta-bake","name":"Tuna pasta bake","cat":"Pasta","country":"France","instr":"Cook the pasta for 2 minutes less than the packet says.\r\nSoften the chopped onion in a little oil for 5 minutes, add the tomatoes and simmer for 10 minutes. Stir in the crème fraîche.\r\nHeat the oven to 200C. Mix the pasta with the sauce, the tuna and the sweetcorn.\r\nPut in a dish, top with the torn mozzarella and grated cheddar and bake for 15 minutes.","thumb":"https://upload.wikimedia.org/wikipedia/commons/f/fa/Tuna_Casserole2.jpg","tags":["Bake","Family"],"yt":"","src":"","ingr":[{"n":"Penne Rigate","m":"400g"},{"n":"Tuna","m":"300g"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Sweetcorn","m":"150g"},{"n":"Onion","m":"1"},{"n":"Creme Fraiche","m":"100ml"},{"n":"Mozzarella","m":"125g"},{"n":"Cheddar Cheese","m":"80g"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Tuna_Casserole2.jpg","artist":"B.D.'s world","license":"CC BY-SA 2.0"}},{"id":"qm-vichyssoise-style-leek-and-potato-soup","name":"Vichyssoise-style leek and potato soup","cat":"Vegetarian","country":"France","instr":"Soften the sliced leeks and onion in the butter for 10 minutes without colouring.\r\nAdd the diced potatoes and stock and simmer for 20 minutes.\r\nBlend until smooth, stir in the crème fraîche and season.\r\nSprinkle with chives and serve with crusty bread.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Vichyssoise.jpg/960px-Vichyssoise.jpg","tags":["Soup","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Leek","m":"3"},{"n":"Potatoes","m":"600g"},{"n":"Onion","m":"1"},{"n":"Butter","m":"30g"},{"n":"Vegetable Stock","m":"1.2 litres"},{"n":"Creme Fraiche","m":"100ml"},{"n":"Chives","m":"2 tbs chopped"},{"n":"Crusty Bread","m":"1"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Vichyssoise.jpg","artist":"BocaDorada","license":"CC BY-SA 2.0"}},{"id":"qm-buckwheat-galettes-with-ham-egg-and-cheese","name":"Buckwheat galettes with ham, egg and cheese","cat":"Pork","country":"France","instr":"Whisk the buckwheat flour with 1 egg, the water and a pinch of salt. Rest for 30 minutes.\r\nHeat a large frying pan, butter it and pour in a ladle of batter, swirling to cover the pan. Cook for 2 minutes.\r\nTurn the galette, sprinkle with cheese, add a slice of ham and crack an egg in the middle.\r\nCook for 3 minutes until the white is set, fold the edges over in a square and serve with salad.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Galette_de_sarrasin_compl%C3%A8te_bretonne.jpg/960px-Galette_de_sarrasin_compl%C3%A8te_bretonne.jpg","tags":["Brittany"],"yt":"","src":"","ingr":[{"n":"Buckwheat","m":"250g"},{"n":"Eggs","m":"5"},{"n":"Water","m":"500ml"},{"n":"Salted Butter","m":"50g"},{"n":"Ham","m":"4 slices"},{"n":"Emmentaler Cheese","m":"150g"},{"n":"Lettuce","m":"1"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Galette_de_sarrasin_compl%C3%A8te_bretonne.jpg","artist":"Arnaud 25","license":"CC BY-SA 4.0"}},{"id":"qm-courgette-and-goat-s-cheese-gratin","name":"Courgette and goat's cheese gratin","cat":"Vegetarian","country":"France","instr":"Heat the oven to 190C. Slice the courgettes and fry them with the garlic in a little oil for 8 minutes.\r\nBeat the eggs with the crème fraîche, thyme, salt and pepper.\r\nPut the courgettes in a dish, crumble over the goat's cheese and pour over the egg mixture.\r\nBake for 25 minutes. Serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Pr%C3%A9paration_gratin_de_courgettes-tomates_%28017%29_-_sortie_du_four.jpg/960px-Pr%C3%A9paration_gratin_de_courgettes-tomates_%28017%29_-_sortie_du_four.jpg","tags":["Bake","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Courgettes","m":"4"},{"n":"Goats Cheese","m":"150g"},{"n":"Eggs","m":"3"},{"n":"Creme Fraiche","m":"200ml"},{"n":"Garlic","m":"1 clove"},{"n":"Thyme","m":"1 tsp"},{"n":"Rice","m":"250g"}],"time":45,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pr%C3%A9paration_gratin_de_courgettes-tomates_(017)_-_sortie_du_four.jpg","artist":"Benoît Prieur","license":"CC0"}},{"id":"qm-chicken-and-leek-pie","name":"Chicken and leek pie","cat":"Chicken","country":"France","instr":"Cut the chicken into cubes and brown in the butter for 5 minutes. Add the sliced leeks and cook for 8 minutes.\r\nSprinkle with flour, stir, then add the stock and crème fraîche and simmer for 5 minutes. Season.\r\nHeat the oven to 200C. Pour into a pie dish and cover with the pastry, pressing the edges.\r\nBrush with beaten egg and bake for 25 minutes until golden. Serve with salad.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Chicken_%26_leek_pie_with_mushroom_-_The_Kew_Greenhouse_Cafe_2025-05-14.jpg/960px-Chicken_%26_leek_pie_with_mushroom_-_The_Kew_Greenhouse_Cafe_2025-05-14.jpg","tags":["Pie","Family"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"3"},{"n":"Leek","m":"3"},{"n":"Butter","m":"30g"},{"n":"Plain Flour","m":"2 tbs"},{"n":"Chicken Stock","m":"300ml"},{"n":"Creme Fraiche","m":"150ml"},{"n":"Puff Pastry","m":"1 sheet"},{"n":"Egg","m":"1"},{"n":"Lettuce","m":"1"}],"time":55,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Chicken_%26_leek_pie_with_mushroom_-_The_Kew_Greenhouse_Cafe_2025-05-14.jpg","artist":"Andy Li","license":"CC0"}},{"id":"qm-mushroom-risotto","name":"Mushroom risotto","cat":"Vegetarian","country":"Italy","instr":"Keep the stock hot in a pan. Fry the sliced mushrooms in half the butter for 6 minutes and set aside.\r\nSoften the chopped onion and garlic in the rest of the butter for 4 minutes. Add the rice and stir for 1 minute.\r\nPour in the wine and let it evaporate, then add the stock a ladle at a time, stirring, for 18 minutes until the rice is creamy and just tender.\r\nStir in the mushrooms, parmesan and parsley. Rest for 2 minutes before serving.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Mushroom_risotto_%283990739885%29.jpg/960px-Mushroom_risotto_%283990739885%29.jpg","tags":["Rice","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Arborio Rice","m":"320g"},{"n":"Mushrooms","m":"400g"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"1 clove"},{"n":"Dry White Wine","m":"100ml"},{"n":"Vegetable Stock","m":"1.2 litres"},{"n":"Butter","m":"40g"},{"n":"Parmesan","m":"60g"},{"n":"Parsley","m":"2 tbs chopped"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Mushroom_risotto_(3990739885).jpg","artist":"Karen and Brad Emerson","license":"CC BY 2.0"}},{"id":"qm-risotto-alla-milanese","name":"Risotto alla milanese","cat":"Vegetarian","country":"Italy","instr":"Soak the saffron in a ladle of hot stock.\r\nSoften the chopped onion in half the butter for 4 minutes, add the rice and stir for 1 minute.\r\nAdd the wine, let it evaporate, then add the hot stock a ladle at a time, stirring, for 18 minutes. Add the saffron halfway.\r\nOff the heat, beat in the rest of the butter and the parmesan.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Risotto_alla_Milanese.JPG/960px-Risotto_alla_Milanese.JPG","tags":["Rice"],"yt":"","src":"","ingr":[{"n":"Arborio Rice","m":"320g"},{"n":"Saffron","m":"1 pinch"},{"n":"Onion","m":"1"},{"n":"Dry White Wine","m":"100ml"},{"n":"Chicken Stock","m":"1.2 litres"},{"n":"Butter","m":"50g"},{"n":"Parmesan","m":"70g"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Risotto_alla_Milanese.JPG","artist":"Number55","license":"CC BY-SA 3.0"}},{"id":"qm-pasta-with-basil-pesto","name":"Pasta with basil pesto","cat":"Vegetarian","country":"Italy","instr":"Cook the pasta following the packet instructions.\r\nBlend the basil, pine nuts, garlic and parmesan, then blend in the olive oil and a pinch of salt.\r\nDrain the pasta, keeping a cup of the cooking water. Toss with the pesto, loosening with a little water.\r\nServe topped with halved cherry tomatoes.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/BasilPesto.JPG/960px-BasilPesto.JPG","tags":["Quick","Pasta","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Farfalle","m":"400g"},{"n":"Basil Leaves","m":"60g"},{"n":"Pine Nuts","m":"40g"},{"n":"Garlic","m":"1 clove"},{"n":"Parmesan","m":"50g"},{"n":"Extra Virgin Olive Oil","m":"120ml"},{"n":"Cherry Tomatoes","m":"200g"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:BasilPesto.JPG","artist":"Ɱ","license":"CC BY-SA 3.0"}},{"id":"qm-pasta-e-fagioli","name":"Pasta e fagioli","cat":"Vegetarian","country":"Italy","instr":"Soften the chopped onion, carrot, celery and garlic in olive oil for 8 minutes.\r\nAdd the tomatoes, half the beans, the rosemary and the stock and simmer for 15 minutes.\r\nMash the remaining beans and add them with the pasta. Cook for 10 minutes until the pasta is tender.\r\nServe with grated parmesan and a drizzle of olive oil.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Pasta_e_fagioli_cannellini.jpg/960px-Pasta_e_fagioli_cannellini.jpg","tags":["Soup","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Macaroni","m":"200g"},{"n":"Borlotti Beans","m":"800g"},{"n":"Onion","m":"1"},{"n":"Carrots","m":"1"},{"n":"Celery","m":"1 stick"},{"n":"Garlic","m":"2 cloves"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Vegetable Stock","m":"1 litre"},{"n":"Rosemary","m":"1 sprig"},{"n":"Parmesan","m":"40g"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pasta_e_fagioli_cannellini.jpg","artist":"Spinoziano","license":"CC BY-SA 4.0"}},{"id":"qm-pasta-alla-norma","name":"Pasta alla Norma","cat":"Vegetarian","country":"Italy","instr":"Cut the aubergines into cubes and fry in the oil for 12 minutes until golden. Drain.\r\nFry the garlic and chilli for 1 minute, add the tomatoes and simmer for 15 minutes.\r\nCook the pasta. Stir the aubergine and torn basil into the sauce.\r\nToss with the pasta and serve topped with crumbled ricotta.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Pasta_alla_Norma_-_Wiki_Loves_Sicilia.jpg/960px-Pasta_alla_Norma_-_Wiki_Loves_Sicilia.jpg","tags":["Pasta","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Penne Rigate","m":"400g"},{"n":"Aubergine","m":"2"},{"n":"Garlic","m":"2 cloves"},{"n":"Chopped Tomatoes","m":"800g"},{"n":"Basil","m":"1 handful"},{"n":"Ricotta","m":"100g"},{"n":"Olive Oil","m":"6 tbs"},{"n":"Chilli Flakes","m":"1 pinch"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pasta_alla_Norma_-_Wiki_Loves_Sicilia.jpg","artist":"8w9d","license":"CC0"}},{"id":"qm-spaghetti-aglio-e-olio","name":"Spaghetti aglio e olio","cat":"Vegan","country":"Italy","instr":"Cook the spaghetti in well-salted water.\r\nMeanwhile warm the oil with the thinly sliced garlic and chilli over low heat for 4 minutes until the garlic is pale golden.\r\nDrain the pasta, keeping some water, and toss in the oil with the parsley, a squeeze of lemon and a splash of the cooking water.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Aglio_e_olio.jpg/960px-Aglio_e_olio.jpg","tags":["Quick","Pasta"],"yt":"","src":"","ingr":[{"n":"Spaghetti","m":"400g"},{"n":"Garlic","m":"6 cloves"},{"n":"Extra Virgin Olive Oil","m":"100ml"},{"n":"Chilli Flakes","m":"1 tsp"},{"n":"Parsley","m":"4 tbs chopped"},{"n":"Lemon","m":"1/2"}],"time":15,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Aglio_e_olio.jpg","artist":"Spaghetti_aglio_olio_e_peperoncino_by_matsuyuki_retouched.jpg derivative work: J","license":"CC BY-SA 2.0"}},{"id":"qm-cacio-e-pepe","name":"Cacio e pepe","cat":"Vegetarian","country":"Italy","instr":"Cook the spaghetti in lightly salted water.\r\nToast the coarsely ground pepper in a large pan for 1 minute, then add the butter and a ladle of pasta water.\r\nMix the finely grated cheeses with a little warm pasta water to make a paste.\r\nAdd the drained pasta to the pan, then the cheese paste, tossing quickly off the heat and adding water until creamy.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Cacio_e_pepe.jpg/960px-Cacio_e_pepe.jpg","tags":["Quick","Pasta"],"yt":"","src":"","ingr":[{"n":"Spaghetti","m":"400g"},{"n":"Pecorino","m":"120g"},{"n":"Parmesan","m":"40g"},{"n":"Black Pepper","m":"2 tsp"},{"n":"Butter","m":"20g"}],"time":15,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Cacio_e_pepe.jpg","artist":"Popo le Chien","license":"CC BY-SA 3.0"}},{"id":"qm-bucatini-all-amatriciana","name":"Bucatini all'amatriciana","cat":"Pasta","country":"Italy","instr":"Cut the bacon into strips and fry for 6 minutes until crisp.\r\nAdd the wine, let it bubble, then the tomatoes and chilli. Simmer for 12 minutes.\r\nCook the pasta, drain and toss with the sauce and half the pecorino. Serve with the rest.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/Bucatini_allamatriciana.jpg/960px-Bucatini_allamatriciana.jpg","tags":["Pasta","Quick"],"yt":"","src":"","ingr":[{"n":"Spaghetti","m":"400g"},{"n":"Bacon","m":"150g"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Pecorino","m":"60g"},{"n":"Chilli Flakes","m":"1 pinch"},{"n":"Dry White Wine","m":"50ml"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Bucatini_allamatriciana.jpg","artist":"Popo le Chien","license":"CC0"}},{"id":"qm-spaghetti-puttanesca","name":"Spaghetti puttanesca","cat":"Pasta","country":"Italy","instr":"Fry the garlic, chilli and anchovies in olive oil for 2 minutes until the anchovies melt.\r\nAdd the tomatoes, olives and capers and simmer for 15 minutes.\r\nToss with the cooked spaghetti and parsley.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Pasta_Puttanesca.jpg/960px-Pasta_Puttanesca.jpg","tags":["Quick","Pasta"],"yt":"","src":"","ingr":[{"n":"Spaghetti","m":"400g"},{"n":"Chopped Tomatoes","m":"800g"},{"n":"Black Olives","m":"100g"},{"n":"Capers","m":"2 tbs"},{"n":"Anchovy Fillet","m":"4"},{"n":"Garlic","m":"3 cloves"},{"n":"Chilli Flakes","m":"1 pinch"},{"n":"Parsley","m":"2 tbs chopped"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pasta_Puttanesca.jpg","artist":"Popo le Chien","license":"CC BY-SA 4.0"}},{"id":"qm-gnocchi-alla-sorrentina","name":"Gnocchi alla sorrentina","cat":"Vegetarian","country":"Italy","instr":"Simmer the passata with the garlic and a pinch of salt for 10 minutes.\r\nBoil the gnocchi until they float, about 2 minutes. Drain.\r\nHeat the oven to 220C. Mix the gnocchi with the sauce and torn basil and put in a dish.\r\nTop with the mozzarella and parmesan and bake for 12 minutes until bubbling.","thumb":"https://upload.wikimedia.org/wikipedia/commons/8/86/Gnocchi_di_ricotta_burro_e_salvia.jpg","tags":["Bake","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Gnocchi","m":"800g"},{"n":"Passata","m":"500ml"},{"n":"Garlic","m":"1 clove"},{"n":"Mozzarella","m":"250g"},{"n":"Basil","m":"1 handful"},{"n":"Parmesan","m":"40g"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Gnocchi_di_ricotta_burro_e_salvia.jpg","artist":"Paoletta S.","license":"CC BY 2.0"}},{"id":"qm-ham-and-mushroom-pizza","name":"Ham and mushroom pizza","cat":"Pork","country":"Italy","instr":"Mix the flour, yeast, a pinch of salt, the water and oil. Knead for 8 minutes and leave to rise for 1 hour.\r\nHeat the oven to 250C. Divide the dough in two and stretch into thin rounds.\r\nSpread with passata, then add the mozzarella, ham strips and sliced mushrooms. Sprinkle with oregano.\r\nBake for 10 to 12 minutes until crisp.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Pizza-3007395.jpg/960px-Pizza-3007395.jpg","tags":["Pizza","Family"],"yt":"","src":"","ingr":[{"n":"Bread Flour","m":"400g"},{"n":"Fast Action Yeast","m":"7g"},{"n":"Water","m":"250ml"},{"n":"Olive Oil","m":"2 tbs"},{"n":"Passata","m":"200ml"},{"n":"Mozzarella","m":"250g"},{"n":"Ham","m":"150g"},{"n":"Mushrooms","m":"150g"},{"n":"Dried Oregano","m":"1 tsp"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pizza-3007395.jpg","artist":"igorovsyannykov","license":"CC0"}},{"id":"qm-minestrone","name":"Minestrone","cat":"Vegan","country":"Italy","instr":"Soften the chopped onion, carrots and celery in olive oil for 8 minutes.\r\nAdd the diced potatoes and courgette, tomatoes and stock. Simmer for 20 minutes.\r\nAdd the beans and pasta and cook for 10 minutes more.\r\nSeason and serve with torn basil.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Minestrone_soup_%285%29.jpg/960px-Minestrone_soup_%285%29.jpg","tags":["Soup"],"yt":"","src":"","ingr":[{"n":"Onion","m":"1"},{"n":"Carrots","m":"2"},{"n":"Celery","m":"2 sticks"},{"n":"Courgettes","m":"1"},{"n":"Potatoes","m":"2"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Cannellini Beans","m":"400g"},{"n":"Macaroni","m":"100g"},{"n":"Vegetable Stock","m":"1.5 litres"},{"n":"Basil","m":"1 handful"}],"time":45,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Minestrone_soup_(5).jpg","artist":"Daniel Ziegener","license":"CC BY-SA 2.0"}},{"id":"qm-chicken-cacciatore","name":"Chicken cacciatore","cat":"Chicken","country":"Italy","instr":"Brown the seasoned chicken in olive oil for 8 minutes. Set aside.\r\nFry the sliced onion, garlic and pepper for 5 minutes. Add the wine and let it bubble.\r\nAdd the tomatoes and rosemary, return the chicken, cover and simmer for 35 minutes.\r\nAdd the olives and serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Flickr_preppybyday_4618397089--Chicken_cacciatore.jpg/960px-Flickr_preppybyday_4618397089--Chicken_cacciatore.jpg","tags":["Stew"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"8"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Red Pepper","m":"1"},{"n":"Chopped Tomatoes","m":"800g"},{"n":"Red Wine","m":"150ml"},{"n":"Rosemary","m":"2 sprigs"},{"n":"Black Olives","m":"80g"},{"n":"Rice","m":"300g"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Flickr_preppybyday_4618397089--Chicken_cacciatore.jpg","artist":"Evan Joshua Swigart (TheCulinaryGeek) from Chicago, Illinois, USA; hometown of A","license":"CC BY 2.0"}},{"id":"qm-chicken-saltimbocca","name":"Chicken saltimbocca","cat":"Chicken","country":"Italy","instr":"Boil the potatoes for 18 minutes and the green beans for 6 minutes.\r\nCut each chicken breast in two thin escalopes and flatten slightly.\r\nLay a sage leaf on each and wrap in a slice of Parma ham.\r\nFry in the butter for 3 minutes on each side. Add the wine and bubble for 1 minute. Serve with the vegetables.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Saltimbocca_01.jpg/960px-Saltimbocca_01.jpg","tags":["Quick"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"4"},{"n":"Parma Ham","m":"8 slices"},{"n":"Sage","m":"8 leaves"},{"n":"Butter","m":"30g"},{"n":"Dry White Wine","m":"100ml"},{"n":"New Potatoes","m":"700g"},{"n":"Green Beans","m":"300g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Saltimbocca_01.jpg","artist":"Arnaud 25","license":"CC BY-SA 4.0"}},{"id":"qm-chicken-piccata","name":"Chicken piccata","cat":"Chicken","country":"Italy","instr":"Cook the spaghetti. Slice the chicken into thin escalopes, season and dust with flour.\r\nFry in half the butter for 3 minutes on each side. Set aside.\r\nAdd the stock, lemon juice and capers to the pan and simmer for 3 minutes. Swirl in the rest of the butter.\r\nReturn the chicken, sprinkle with parsley and serve with the spaghetti.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Chicken_piccata_dinner_cooking_food.jpg/960px-Chicken_piccata_dinner_cooking_food.jpg","tags":["Quick"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"4"},{"n":"Plain Flour","m":"3 tbs"},{"n":"Butter","m":"40g"},{"n":"Lemon","m":"2"},{"n":"Capers","m":"2 tbs"},{"n":"Chicken Stock","m":"150ml"},{"n":"Spaghetti","m":"300g"},{"n":"Parsley","m":"2 tbs chopped"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Chicken_piccata_dinner_cooking_food.jpg","artist":"Jon Sullivan","license":"Public domain"}},{"id":"qm-meatballs-in-tomato-sauce","name":"Meatballs in tomato sauce","cat":"Beef","country":"Italy","instr":"Soak the breadcrumbs in the milk, then mix with the beef, egg, parmesan, 1 crushed garlic clove, salt and pepper.\r\nRoll into 20 balls and brown them in olive oil for 8 minutes.\r\nAdd the remaining garlic and the passata and simmer for 20 minutes.\r\nCook the spaghetti and serve with the meatballs, sauce and basil.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Spaghetti_and_meatballs_1.jpg/960px-Spaghetti_and_meatballs_1.jpg","tags":["Family"],"yt":"","src":"","ingr":[{"n":"Minced Beef","m":"500g"},{"n":"Breadcrumbs","m":"50g"},{"n":"Milk","m":"50ml"},{"n":"Egg","m":"1"},{"n":"Parmesan","m":"40g"},{"n":"Garlic","m":"2 cloves"},{"n":"Passata","m":"700ml"},{"n":"Basil","m":"1 handful"},{"n":"Spaghetti","m":"400g"}],"time":45,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Spaghetti_and_meatballs_1.jpg","artist":"jeffreyw","license":"CC BY 2.0"}},{"id":"qm-pasta-with-tuna-and-tomato","name":"Pasta with tuna and tomato","cat":"Pasta","country":"Italy","instr":"Cook the pasta.\r\nFry the garlic and chilli in olive oil for 1 minute, add the tomatoes and simmer for 10 minutes.\r\nStir in the tuna and capers and warm through.\r\nToss with the pasta and parsley.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/df/Pasta_al_rag%C3%B9_di_tonno_rosso.jpg/960px-Pasta_al_rag%C3%B9_di_tonno_rosso.jpg","tags":["Quick","Pasta"],"yt":"","src":"","ingr":[{"n":"Penne Rigate","m":"400g"},{"n":"Tuna","m":"250g"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Garlic","m":"2 cloves"},{"n":"Capers","m":"1 tbs"},{"n":"Parsley","m":"2 tbs chopped"},{"n":"Chilli Flakes","m":"1 pinch"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pasta_al_rag%C3%B9_di_tonno_rosso.jpg","artist":"Civa61","license":"CC BY-SA 4.0"}},{"id":"qm-orecchiette-with-sausage-and-broccoli","name":"Orecchiette with sausage and broccoli","cat":"Pasta","country":"Italy","instr":"Cook the pasta, adding the broccoli florets for the last 4 minutes.\r\nRemove the sausage skins and fry the meat, broken up, for 8 minutes with the garlic and chilli.\r\nDrain the pasta and broccoli, keeping some water, and toss with the sausage, a splash of water and the parmesan.","thumb":"https://upload.wikimedia.org/wikipedia/commons/8/8d/Orecchiette_carbonara.jpg","tags":["Quick","Pasta"],"yt":"","src":"","ingr":[{"n":"Farfalle","m":"400g"},{"n":"Italian Fennel Sausages","m":"300g"},{"n":"Broccoli","m":"1 head"},{"n":"Garlic","m":"2 cloves"},{"n":"Chilli Flakes","m":"1 pinch"},{"n":"Parmesan","m":"40g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Orecchiette_carbonara.jpg","artist":"Foodista","license":"CC BY 2.0"}},{"id":"qm-linguine-with-clams","name":"Linguine with clams","cat":"Seafood","country":"Italy","instr":"Rinse the clams well. Cook the linguine.\r\nFry the garlic and chilli in the oil for 1 minute, add the clams and wine, cover and cook for 4 minutes until they open.\r\nAdd the drained pasta to the pan with the parsley and toss for 1 minute.","thumb":"https://upload.wikimedia.org/wikipedia/commons/5/59/Spaghetti_vongole_2.jpg","tags":["Quick","Shellfish"],"yt":"","src":"","ingr":[{"n":"Linguine Pasta","m":"400g"},{"n":"Clams","m":"1kg"},{"n":"Garlic","m":"3 cloves"},{"n":"Dry White Wine","m":"150ml"},{"n":"Chilli Flakes","m":"1 pinch"},{"n":"Parsley","m":"4 tbs chopped"},{"n":"Extra Virgin Olive Oil","m":"4 tbs"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Spaghetti_vongole_2.jpg","artist":"Popo le Chien","license":"CC BY-SA 4.0"}},{"id":"qm-aubergine-parmigiana","name":"Aubergine parmigiana","cat":"Vegetarian","country":"Italy","instr":"Slice the aubergines lengthways, brush with oil and grill or fry for 3 minutes on each side.\r\nSimmer the passata with the garlic for 10 minutes.\r\nHeat the oven to 190C. Layer aubergine, sauce, mozzarella, basil and parmesan in a dish, finishing with sauce and parmesan.\r\nBake for 35 minutes. Rest for 10 minutes and serve with bread.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Parmigiana_di_melanzane.jpg/960px-Parmigiana_di_melanzane.jpg","tags":["Bake","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Aubergine","m":"3"},{"n":"Passata","m":"700ml"},{"n":"Garlic","m":"1 clove"},{"n":"Mozzarella","m":"250g"},{"n":"Parmesan","m":"80g"},{"n":"Basil","m":"1 handful"},{"n":"Olive Oil","m":"6 tbs"},{"n":"Crusty Bread","m":"1"}],"time":70,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Parmigiana_di_melanzane.jpg","artist":"Schellenberg","license":"CC BY-SA 4.0"}},{"id":"qm-courgette-frittata","name":"Courgette frittata","cat":"Vegetarian","country":"Italy","instr":"Fry the sliced onion and grated courgettes in the oil for 8 minutes until soft.\r\nBeat the eggs with the parmesan, chopped mint, salt and pepper and pour into the pan.\r\nCook gently for 8 minutes, then finish under a hot grill for 3 minutes until set.\r\nServe in wedges with rocket.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Frittata02.jpg/960px-Frittata02.jpg","tags":["Quick","Eggs","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Eggs","m":"8"},{"n":"Courgettes","m":"2"},{"n":"Onion","m":"1"},{"n":"Parmesan","m":"50g"},{"n":"Mint","m":"1 handful"},{"n":"Olive Oil","m":"2 tbs"},{"n":"Rocket","m":"100g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Frittata02.jpg","artist":"fir0002 flagstaffotos [at] gmail.com Canon 20D + Canon 17-40mm f/4 L","license":"GFDL 1.2"}},{"id":"qm-panzanella","name":"Panzanella","cat":"Vegan","country":"Italy","instr":"Tear the bread into chunks and toast in the oven at 200C for 8 minutes.\r\nChop the tomatoes and cucumber and slice the onion thinly.\r\nMix everything with the beans, basil, oil and vinegar. Season and leave for 10 minutes before serving.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/26/Italian_Panzanella.jpg/960px-Italian_Panzanella.jpg","tags":["Salad","Quick"],"yt":"","src":"","ingr":[{"n":"Stale Bread","m":"300g"},{"n":"Tomatoes","m":"6"},{"n":"Cucumber","m":"1"},{"n":"Red Onions","m":"1"},{"n":"Basil","m":"1 handful"},{"n":"Extra Virgin Olive Oil","m":"6 tbs"},{"n":"Red Wine Vinegar","m":"2 tbs"},{"n":"Cannellini Beans","m":"400g"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Italian_Panzanella.jpg","artist":"Heather Katsoulis","license":"CC BY-SA 2.0"}},{"id":"qm-pea-and-mint-risotto","name":"Pea and mint risotto","cat":"Vegetarian","country":"Italy","instr":"Soften the chopped onion in half the butter for 4 minutes. Add the rice and stir for 1 minute.\r\nAdd the hot stock a ladle at a time, stirring, for 15 minutes.\r\nAdd the peas and cook for 4 minutes more.\r\nStir in the rest of the butter, parmesan, chopped mint and lemon zest.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Risotto_with_speck_and_goat_cheese_%286101067436%29.jpg/960px-Risotto_with_speck_and_goat_cheese_%286101067436%29.jpg","tags":["Rice","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Arborio Rice","m":"320g"},{"n":"Frozen Peas","m":"300g"},{"n":"Onion","m":"1"},{"n":"Vegetable Stock","m":"1.2 litres"},{"n":"Butter","m":"40g"},{"n":"Parmesan","m":"60g"},{"n":"Mint","m":"1 handful"},{"n":"Lemon","m":"1"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Risotto_with_speck_and_goat_cheese_(6101067436).jpg","artist":"Luca Nebuloni from Milan, Italy","license":"CC BY 2.0"}},{"id":"qm-tortellini-in-broth","name":"Tortellini in broth","cat":"Pasta","country":"Italy","instr":"Bring the stock to the boil with the finely diced carrot and simmer for 5 minutes.\r\nAdd the tortellini and cook for the time on the packet.\r\nStir in the spinach for the last minute and serve with parmesan.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Tortellini_Bolognesi.jpg/960px-Tortellini_Bolognesi.jpg","tags":["Quick","Soup"],"yt":"","src":"","ingr":[{"n":"Tortellini","m":"500g"},{"n":"Chicken Stock","m":"1.5 litres"},{"n":"Carrots","m":"1"},{"n":"Spinach","m":"100g"},{"n":"Parmesan","m":"40g"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Tortellini_Bolognesi.jpg","artist":"Angelo.Muratore","license":"CC BY-SA 4.0"}},{"id":"qm-lemon-spaghetti","name":"Lemon spaghetti","cat":"Vegetarian","country":"Italy","instr":"Cook the spaghetti.\r\nMelt the butter with the cream, the zest of both lemons and the juice of one.\r\nToss with the drained pasta, the parmesan and a splash of cooking water. Finish with basil and pepper.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Lemon_Spaghetti_%2814179778117%29.jpg/960px-Lemon_Spaghetti_%2814179778117%29.jpg","tags":["Quick","Pasta"],"yt":"","src":"","ingr":[{"n":"Spaghetti","m":"400g"},{"n":"Lemon","m":"2"},{"n":"Butter","m":"40g"},{"n":"Parmesan","m":"80g"},{"n":"Double Cream","m":"100ml"},{"n":"Basil","m":"1 handful"}],"time":15,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Lemon_Spaghetti_(14179778117).jpg","artist":"Luca Nebuloni from Milan, Italy","license":"CC BY 2.0"}},{"id":"qm-pasta-primavera","name":"Pasta primavera","cat":"Vegetarian","country":"Italy","instr":"Cook the pasta, adding the asparagus in pieces and the peas for the last 4 minutes.\r\nFry the diced courgette and garlic in olive oil for 5 minutes.\r\nDrain the pasta and vegetables and toss with the courgette, crème fraîche, parmesan and lemon zest.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Pasta_primavera.jpg/960px-Pasta_primavera.jpg","tags":["Quick","Pasta","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Farfalle","m":"400g"},{"n":"Asparagus","m":"200g"},{"n":"Frozen Peas","m":"150g"},{"n":"Courgettes","m":"1"},{"n":"Garlic","m":"1 clove"},{"n":"Creme Fraiche","m":"150ml"},{"n":"Parmesan","m":"50g"},{"n":"Lemon","m":"1"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pasta_primavera.jpg","artist":"Jeremy Keith","license":"CC BY 2.0"}},{"id":"qm-sausage-and-bean-casserole","name":"Sausage and bean casserole","cat":"Pork","country":"Italy","instr":"Brown the sausages in a casserole for 8 minutes. Add the chopped onion and garlic and cook for 4 minutes.\r\nAdd the tomatoes, beans and rosemary and simmer for 20 minutes.\r\nSeason and serve with crusty bread.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/-2021-12-03_Sausages%2C_Baked_Beans_and_Bubble_and_squeak%2C_Trimingham%2C_Norfolk.JPG/960px--2021-12-03_Sausages%2C_Baked_Beans_and_Bubble_and_squeak%2C_Trimingham%2C_Norfolk.JPG","tags":["Stew","Family"],"yt":"","src":"","ingr":[{"n":"Italian Fennel Sausages","m":"8"},{"n":"Cannellini Beans","m":"800g"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Rosemary","m":"1 sprig"},{"n":"Crusty Bread","m":"1"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:-2021-12-03_Sausages,_Baked_Beans_and_Bubble_and_squeak,_Trimingham,_Norfolk.JPG","artist":"Kolforn (Kolforn) I'd appreciate if you could mail me (Kolforn@gmail.com) if you","license":"CC BY-SA 4.0"}},{"id":"qm-calzone-with-ham-and-ricotta","name":"Calzone with ham and ricotta","cat":"Pork","country":"Italy","instr":"Mix the flour, yeast, a pinch of salt and the water, knead for 8 minutes and leave to rise for 1 hour.\r\nHeat the oven to 240C. Divide the dough in four and roll out into rounds.\r\nSpread passata on one half of each, add ricotta, mozzarella, ham and basil. Fold over and seal the edges.\r\nBake for 15 minutes until puffed and golden.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Wikimania_2016_Deryck_day_0_-_07_calzone.jpg/960px-Wikimania_2016_Deryck_day_0_-_07_calzone.jpg","tags":["Pizza"],"yt":"","src":"","ingr":[{"n":"Bread Flour","m":"400g"},{"n":"Fast Action Yeast","m":"7g"},{"n":"Water","m":"250ml"},{"n":"Ricotta","m":"250g"},{"n":"Mozzarella","m":"200g"},{"n":"Ham","m":"150g"},{"n":"Passata","m":"150ml"},{"n":"Basil","m":"1 handful"}],"time":45,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Wikimania_2016_Deryck_day_0_-_07_calzone.jpg","artist":"Deryck Chan","license":"CC BY-SA 4.0"}},{"id":"qm-oyakodon","name":"Oyakodon","cat":"Chicken","country":"Japan","instr":"Cook the rice.\r\nSimmer the water, soy sauce, mirin and sugar in a frying pan. Add the sliced onion and cook for 3 minutes.\r\nAdd the chicken cut into bite-size pieces and simmer for 7 minutes.\r\nPour over the lightly beaten eggs, cover and cook for 1 minute until just set.\r\nSlide onto bowls of rice and top with sliced spring onions.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Oyakodon_003.jpg/960px-Oyakodon_003.jpg","tags":["Quick","Rice"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"4"},{"n":"Onion","m":"1"},{"n":"Eggs","m":"6"},{"n":"Soy Sauce","m":"4 tbs"},{"n":"Mirin","m":"3 tbs"},{"n":"Sugar","m":"1 tbs"},{"n":"Water","m":"200ml"},{"n":"Sushi Rice","m":"320g"},{"n":"Spring Onions","m":"2"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Oyakodon_003.jpg","artist":"Ocdp","license":"CC0"}},{"id":"qm-gyudon","name":"Gyudon","cat":"Beef","country":"Japan","instr":"Cook the rice.\r\nBring the water, soy sauce, mirin, sake, sugar and ginger to a simmer. Add the sliced onions and cook for 5 minutes.\r\nAdd the beef and cook for 3 minutes, skimming.\r\nServe the beef and onions over the rice with a little of the sauce.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Gyuu-don_001.jpg/960px-Gyuu-don_001.jpg","tags":["Quick","Rice"],"yt":"","src":"","ingr":[{"n":"Beef","m":"400g"},{"n":"Onion","m":"2"},{"n":"Soy Sauce","m":"4 tbs"},{"n":"Mirin","m":"3 tbs"},{"n":"Sake","m":"2 tbs"},{"n":"Sugar","m":"1 tbs"},{"n":"Water","m":"200ml"},{"n":"Sushi Rice","m":"320g"},{"n":"Ginger","m":"1 tbs grated"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Gyuu-don_001.jpg","artist":"Ocdp","license":"CC0"}},{"id":"qm-japanese-chicken-curry","name":"Japanese chicken curry","cat":"Chicken","country":"Japan","instr":"Brown the chicken pieces in a little oil. Add the onions, carrots and potatoes in chunks and cook for 5 minutes.\r\nAdd the stock and simmer for 20 minutes.\r\nMeanwhile melt the butter, stir in the flour and curry powder and cook for 3 minutes to make a roux.\r\nWhisk a ladle of stock into the roux, then stir it into the pot with the soy sauce and honey. Simmer for 10 minutes until thick.\r\nServe with the rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/Beef_curry_rice_003.jpg/960px-Beef_curry_rice_003.jpg","tags":["Curry","Family"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"600g"},{"n":"Onions","m":"2"},{"n":"Carrots","m":"2"},{"n":"Potatoes","m":"3"},{"n":"Curry Powder","m":"2 tbs"},{"n":"Plain Flour","m":"3 tbs"},{"n":"Butter","m":"40g"},{"n":"Chicken Stock","m":"800ml"},{"n":"Soy Sauce","m":"2 tbs"},{"n":"Honey","m":"1 tbs"},{"n":"Sushi Rice","m":"320g"}],"time":50,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Beef_curry_rice_003.jpg","artist":"Ocdp","license":"CC0"}},{"id":"qm-okonomiyaki","name":"Okonomiyaki","cat":"Pork","country":"Japan","instr":"Whisk the flour, eggs and water into a batter. Fold in the finely shredded cabbage and sliced spring onions.\r\nPour a quarter of the batter into an oiled frying pan, shape into a thick round and lay 2 bacon slices on top.\r\nCook for 5 minutes, flip and cook for 5 minutes more until the bacon is crisp. Repeat.\r\nMix the ketchup and Worcestershire sauce, brush over the pancakes and drizzle with mayonnaise.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Okonomiyaki_001.jpg/960px-Okonomiyaki_001.jpg","tags":["Pancake"],"yt":"","src":"","ingr":[{"n":"Plain Flour","m":"150g"},{"n":"Eggs","m":"4"},{"n":"Water","m":"150ml"},{"n":"White Cabbage","m":"400g"},{"n":"Spring Onions","m":"4"},{"n":"Streaky Bacon","m":"8 slices"},{"n":"Mayonnaise","m":"4 tbs"},{"n":"Tomato Ketchup","m":"3 tbs"},{"n":"Worcestershire Sauce","m":"2 tbs"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Okonomiyaki_001.jpg","artist":"ume-y","license":"CC BY 2.0"}},{"id":"qm-yakisoba","name":"Yakisoba","cat":"Pork","country":"Japan","instr":"Cook the noodles, drain and rinse.\r\nStir-fry the pork in strips for 4 minutes in a hot wok.\r\nAdd the sliced onion, carrot and cabbage and stir-fry for 4 minutes.\r\nAdd the noodles and the mixed sauces and toss for 2 minutes.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Yakisoba_-_01.jpg/960px-Yakisoba_-_01.jpg","tags":["Quick","Noodles"],"yt":"","src":"","ingr":[{"n":"Egg Noodles","m":"400g"},{"n":"Pork Belly Slices","m":"250g"},{"n":"White Cabbage","m":"200g"},{"n":"Carrots","m":"1"},{"n":"Onion","m":"1"},{"n":"Worcestershire Sauce","m":"4 tbs"},{"n":"Soy Sauce","m":"2 tbs"},{"n":"Tomato Ketchup","m":"1 tbs"},{"n":"Sugar","m":"1 tsp"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Yakisoba_-_01.jpg","artist":"Quercus acuta","license":"CC BY-SA 4.0"}},{"id":"qm-chicken-yakitori-skewers","name":"Chicken yakitori skewers","cat":"Chicken","country":"Japan","instr":"Simmer the soy sauce, mirin, sake and sugar for 5 minutes until syrupy.\r\nCook the rice. Thread chunks of chicken and spring onion onto skewers.\r\nGrill or pan-fry for 10 minutes, turning and brushing with the sauce several times.\r\nServe with rice and sliced cucumber.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Cooking_yakitori.jpg/960px-Cooking_yakitori.jpg","tags":["Grill"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"700g"},{"n":"Spring Onions","m":"6"},{"n":"Soy Sauce","m":"5 tbs"},{"n":"Mirin","m":"4 tbs"},{"n":"Sake","m":"2 tbs"},{"n":"Sugar","m":"1 tbs"},{"n":"Sushi Rice","m":"320g"},{"n":"Cucumber","m":"1"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Cooking_yakitori.jpg","artist":"竹麦魚(Searobin)","license":"CC BY-SA 3.0"}},{"id":"qm-salmon-poke-bowl","name":"Salmon poke bowl","cat":"Seafood","country":"United States","instr":"Cook the rice and season it with the rice vinegar and a pinch of sugar and salt. Let it cool.\r\nCut the salmon into cubes and toss with the soy sauce and sesame oil.\r\nDivide the rice between bowls and arrange the salmon, sliced avocado, cucumber and edamame on top.\r\nSprinkle with sesame seeds.","thumb":"https://upload.wikimedia.org/wikipedia/commons/5/5d/Shoyu_and_onion_poke.jpg","tags":["Quick","Bowl","Fish"],"yt":"","src":"","ingr":[{"n":"Salmon","m":"400g"},{"n":"Sushi Rice","m":"300g"},{"n":"Soy Sauce","m":"4 tbs"},{"n":"Sesame Seed Oil","m":"1 tbs"},{"n":"Rice Vinegar","m":"3 tbs"},{"n":"Avocado","m":"2"},{"n":"Cucumber","m":"1"},{"n":"Edamame Beans","m":"150g"},{"n":"Sesame Seed","m":"1 tbs"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Shoyu_and_onion_poke.jpg","artist":"Aquateamhungerforce","license":"CC BY-SA 4.0"}},{"id":"qm-agedashi-tofu-with-rice","name":"Agedashi tofu with rice","cat":"Vegetarian","country":"Japan","instr":"Cook the rice. Drain the tofu, cut into cubes and pat dry.\r\nSimmer the stock, soy sauce and mirin for 2 minutes.\r\nCoat the tofu in potato starch and fry in the hot oil for 4 minutes until crisp.\r\nServe the tofu in bowls, pour over the sauce and top with ginger and spring onions. Serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/f/f3/Agedashi_tofu%2C_fried_tofu_with_broth.jpg","tags":["Quick","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Tofu","m":"500g"},{"n":"Potato Starch","m":"4 tbs"},{"n":"Soy Sauce","m":"3 tbs"},{"n":"Mirin","m":"3 tbs"},{"n":"Vegetable Stock","m":"250ml"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Spring Onions","m":"2"},{"n":"Sushi Rice","m":"300g"},{"n":"Vegetable Oil","m":"For frying"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Agedashi_tofu,_fried_tofu_with_broth.jpg","artist":"HungryHuy","license":"CC BY 2.0"}},{"id":"qm-bibimbap","name":"Bibimbap","cat":"Beef","country":"South Korea","instr":"Cook the rice.\r\nFry the beef with the garlic and soy sauce for 6 minutes.\r\nBlanch the spinach and bean sprouts for 1 minute each and season with a little sesame oil. Cut the carrots into matchsticks and stir-fry for 2 minutes.\r\nFry the eggs sunny side up.\r\nFill bowls with rice, arrange the beef and vegetables on top, add an egg and serve with gochujang mixed with the rest of the sesame oil.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Dolsot-bibimbap.jpg/960px-Dolsot-bibimbap.jpg","tags":["Rice","Bowl"],"yt":"","src":"","ingr":[{"n":"Sushi Rice","m":"320g"},{"n":"Minced Beef","m":"300g"},{"n":"Spinach","m":"200g"},{"n":"Carrots","m":"2"},{"n":"Bean Sprouts","m":"150g"},{"n":"Eggs","m":"4"},{"n":"Gochujang","m":"3 tbs"},{"n":"Soy Sauce","m":"2 tbs"},{"n":"Sesame Seed Oil","m":"2 tbs"},{"n":"Garlic","m":"2 cloves"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Dolsot-bibimbap.jpg","artist":"Sous Chef","license":"CC BY 2.0"}},{"id":"qm-beef-bulgogi","name":"Beef bulgogi","cat":"Beef","country":"South Korea","instr":"Grate the pear and mix with the soy sauce, sugar, sesame oil, garlic and ginger. Marinate the beef for at least 15 minutes.\r\nCook the rice.\r\nStir-fry the beef in a very hot pan in batches for 2 to 3 minutes.\r\nAdd the sliced spring onions and serve with rice and lettuce leaves for wrapping.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Bulgogi_2.jpg/960px-Bulgogi_2.jpg","tags":["Grill"],"yt":"","src":"","ingr":[{"n":"Beef","m":"600g"},{"n":"Soy Sauce","m":"5 tbs"},{"n":"Brown Sugar","m":"2 tbs"},{"n":"Sesame Seed Oil","m":"2 tbs"},{"n":"Garlic","m":"3 cloves"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Pear","m":"1/2"},{"n":"Spring Onions","m":"3"},{"n":"Sushi Rice","m":"320g"},{"n":"Lettuce","m":"1"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Bulgogi_2.jpg","artist":"국립국어원","license":"CC BY-SA 2.0 kr"}},{"id":"qm-kimchi-fried-rice","name":"Kimchi fried rice","cat":"Pork","country":"South Korea","instr":"Fry the bacon in strips for 4 minutes.\r\nAdd the chopped kimchi and cook for 3 minutes.\r\nAdd the rice, gochujang and soy sauce and stir-fry for 5 minutes until hot.\r\nDrizzle with sesame oil and top each bowl with a fried egg and spring onions.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Kimchi_fried_rice.jpg/960px-Kimchi_fried_rice.jpg","tags":["Quick","Rice"],"yt":"","src":"","ingr":[{"n":"Rice","m":"300g"},{"n":"Kimchi","m":"300g"},{"n":"Bacon","m":"150g"},{"n":"Gochujang","m":"1 tbs"},{"n":"Soy Sauce","m":"1 tbs"},{"n":"Sesame Seed Oil","m":"1 tbs"},{"n":"Eggs","m":"4"},{"n":"Spring Onions","m":"2"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Kimchi_fried_rice.jpg","artist":"Sharon Ang","license":"CC0"}},{"id":"qm-japchae","name":"Japchae","cat":"Beef","country":"South Korea","instr":"Soak or cook the noodles following the packet, drain and toss with a little sesame oil.\r\nStir-fry the beef with 1 tbs soy sauce for 3 minutes. Set aside.\r\nStir-fry the onion, carrot and mushrooms for 4 minutes, add the spinach for 1 minute.\r\nAdd the noodles, beef, remaining soy sauce, sugar and sesame oil and toss for 2 minutes. Sprinkle with sesame seeds.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Japchae_2.jpg/960px-Japchae_2.jpg","tags":["Noodles"],"yt":"","src":"","ingr":[{"n":"Rice Vermicelli","m":"250g"},{"n":"Beef","m":"200g"},{"n":"Spinach","m":"150g"},{"n":"Carrots","m":"1"},{"n":"Onion","m":"1"},{"n":"Mushrooms","m":"100g"},{"n":"Soy Sauce","m":"5 tbs"},{"n":"Sugar","m":"1 tbs"},{"n":"Sesame Seed Oil","m":"2 tbs"},{"n":"Sesame Seed","m":"1 tbs"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Japchae_2.jpg","artist":"Jordi Sanchez","license":"CC BY-SA 2.0"}},{"id":"qm-korean-fried-chicken","name":"Korean fried chicken","cat":"Chicken","country":"South Korea","instr":"Season the wings with salt and toss in the potato starch.\r\nFry at 170C for 10 minutes, drain, then fry again at 190C for 5 minutes until very crisp.\r\nHeat the gochujang, honey, soy sauce and garlic in a large pan for 2 minutes.\r\nToss the wings in the sauce, sprinkle with sesame and serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Iksan_City_48_Korean_Style_Fried_chicken.jpg/960px-Iksan_City_48_Korean_Style_Fried_chicken.jpg","tags":["Fried"],"yt":"","src":"","ingr":[{"n":"Chicken Wings","m":"1kg"},{"n":"Potato Starch","m":"80g"},{"n":"Vegetable Oil","m":"For frying"},{"n":"Gochujang","m":"3 tbs"},{"n":"Honey","m":"3 tbs"},{"n":"Soy Sauce","m":"2 tbs"},{"n":"Garlic","m":"3 cloves"},{"n":"Sesame Seed","m":"1 tbs"},{"n":"Rice","m":"300g"}],"time":45,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Iksan_City_48_Korean_Style_Fried_chicken.jpg","artist":"KOREA.NET","license":"CC BY-SA 2.0"}},{"id":"qm-soft-tofu-stew","name":"Soft tofu stew","cat":"Seafood","country":"South Korea","instr":"Cook the rice.\r\nFry the onion, garlic, chilli powder and kimchi in a little oil for 3 minutes.\r\nAdd the stock and soy sauce and simmer for 5 minutes. Add the prawns and spoon in large pieces of tofu.\r\nSimmer for 4 minutes, crack in the eggs and cook for 2 minutes. Serve bubbling with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/0/02/Sundubu-jjigae.jpg","tags":["Soup","Spicy"],"yt":"","src":"","ingr":[{"n":"Silken Tofu","m":"600g"},{"n":"Prawns","m":"200g"},{"n":"Kimchi","m":"150g"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Red Chilli Powder","m":"1 tbs"},{"n":"Soy Sauce","m":"1 tbs"},{"n":"Vegetable Stock","m":"600ml"},{"n":"Eggs","m":"4"},{"n":"Rice","m":"300g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Sundubu-jjigae.jpg","artist":"행복한 초록개구리","license":"CC BY 4.0"}},{"id":"qm-chicken-chow-mein","name":"Chicken chow mein","cat":"Chicken","country":"China","instr":"Cook the noodles, drain and toss with the sesame oil.\r\nStir-fry the sliced chicken in a hot wok for 5 minutes.\r\nAdd the garlic, carrot matchsticks and spring onions and stir-fry for 2 minutes.\r\nAdd the noodles, bean sprouts, soy and oyster sauces and toss for 3 minutes.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Homemade_Chow_mein_with_shrimps_and_meat_with_a_choy_and_Choung.jpg/960px-Homemade_Chow_mein_with_shrimps_and_meat_with_a_choy_and_Choung.jpg","tags":["Quick","Noodles"],"yt":"","src":"","ingr":[{"n":"Egg Noodles","m":"300g"},{"n":"Chicken Breasts","m":"2"},{"n":"Bean Sprouts","m":"150g"},{"n":"Carrots","m":"1"},{"n":"Spring Onions","m":"4"},{"n":"Soy Sauce","m":"3 tbs"},{"n":"Oyster Sauce","m":"2 tbs"},{"n":"Sesame Seed Oil","m":"1 tbs"},{"n":"Garlic","m":"2 cloves"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Homemade_Chow_mein_with_shrimps_and_meat_with_a_choy_and_Choung.jpg","artist":"Peachyeung316","license":"CC BY-SA 4.0"}},{"id":"qm-egg-fried-rice","name":"Egg fried rice","cat":"Vegetarian","country":"China","instr":"Heat the oil in a wok, add the beaten eggs and scramble lightly for 1 minute. Set aside.\r\nStir-fry the peas and sweetcorn for 2 minutes.\r\nAdd the rice and stir-fry for 4 minutes until hot.\r\nReturn the eggs, add the soy sauce, sesame oil and spring onions and toss.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Koh_Mak%2C_Thailand%2C_Fried_rice_with_seafood%2C_Thai_fried_rice.jpg/960px-Koh_Mak%2C_Thailand%2C_Fried_rice_with_seafood%2C_Thai_fried_rice.jpg","tags":["Quick","Rice","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Rice","m":"300g"},{"n":"Eggs","m":"4"},{"n":"Frozen Peas","m":"150g"},{"n":"Sweetcorn","m":"100g"},{"n":"Spring Onions","m":"4"},{"n":"Soy Sauce","m":"3 tbs"},{"n":"Sesame Seed Oil","m":"1 tbs"},{"n":"Vegetable Oil","m":"2 tbs"}],"time":15,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Koh_Mak,_Thailand,_Fried_rice_with_seafood,_Thai_fried_rice.jpg","artist":"Vyacheslav Argenberg","license":"CC BY 4.0"}},{"id":"qm-char-siu-pork-with-rice","name":"Char siu pork with rice","cat":"Pork","country":"China","instr":"Cut the pork into long strips and marinate in the hoisin, 2 tbs honey, soy sauce, five spice and garlic for at least 30 minutes.\r\nHeat the oven to 200C. Roast the pork on a rack for 30 minutes, turning halfway.\r\nBrush with the rest of the honey and roast for 5 minutes more.\r\nCook the rice, steam the pak choi for 4 minutes and serve with the sliced pork.","thumb":"https://upload.wikimedia.org/wikipedia/commons/9/95/Charsiu.jpg","tags":["Roast"],"yt":"","src":"","ingr":[{"n":"Pork Shoulder","m":"800g"},{"n":"Hoisin Sauce","m":"4 tbs"},{"n":"Honey","m":"3 tbs"},{"n":"Soy Sauce","m":"3 tbs"},{"n":"Chinese Five Spice Powder","m":"1 tsp"},{"n":"Garlic","m":"2 cloves"},{"n":"Rice","m":"300g"},{"n":"Pak Choi","m":"4"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Charsiu.jpg","artist":"Simon Shek","license":"CC BY-SA 3.0"}},{"id":"qm-cashew-chicken","name":"Cashew chicken","cat":"Chicken","country":"China","instr":"Cook the rice. Toss the diced chicken with 1 tbs soy sauce and the cornstarch.\r\nToast the cashews in a dry wok for 2 minutes and set aside.\r\nStir-fry the chicken for 5 minutes, add the onion, pepper and garlic and cook for 3 minutes.\r\nAdd the remaining sauces and 3 tbs water, toss, then add the cashews. Serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Cashewchickenphoto.jpg/960px-Cashewchickenphoto.jpg","tags":["Quick","Stir-fry"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"3"},{"n":"Cashew Nuts","m":"100g"},{"n":"Onion","m":"1"},{"n":"Green Pepper","m":"1"},{"n":"Soy Sauce","m":"3 tbs"},{"n":"Oyster Sauce","m":"2 tbs"},{"n":"Cornstarch","m":"1 tbs"},{"n":"Garlic","m":"2 cloves"},{"n":"Rice","m":"300g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Cashewchickenphoto.jpg","artist":"Simon Law from Montréal, QC, Canada","license":"CC BY-SA 2.0"}},{"id":"qm-black-pepper-beef","name":"Black pepper beef","cat":"Beef","country":"China","instr":"Cook the rice. Toss the beef with the cornstarch and soy sauce.\r\nStir-fry the beef in a very hot wok for 2 minutes and set aside.\r\nStir-fry the onion, pepper and garlic for 3 minutes.\r\nReturn the beef with the oyster sauce, the coarsely ground pepper and 3 tbs water and toss for 1 minute.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/Black-Pepper_Beef_%28Sapi_Lada_Hitam%29%2C_One_Two_Restaurant%2C_Yogyakarta.jpg/960px-Black-Pepper_Beef_%28Sapi_Lada_Hitam%29%2C_One_Two_Restaurant%2C_Yogyakarta.jpg","tags":["Quick","Stir-fry"],"yt":"","src":"","ingr":[{"n":"Beef","m":"500g"},{"n":"Onion","m":"1"},{"n":"Green Pepper","m":"1"},{"n":"Black Pepper","m":"2 tsp"},{"n":"Oyster Sauce","m":"3 tbs"},{"n":"Soy Sauce","m":"1 tbs"},{"n":"Cornstarch","m":"1 tsp"},{"n":"Garlic","m":"2 cloves"},{"n":"Rice","m":"300g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Black-Pepper_Beef_(Sapi_Lada_Hitam),_One_Two_Restaurant,_Yogyakarta.jpg","artist":"Crisco 1492","license":"CC BY-SA 3.0"}},{"id":"qm-chinese-lemon-chicken","name":"Chinese lemon chicken","cat":"Chicken","country":"China","instr":"Cook the rice. Cut the chicken into strips, dip in beaten egg then in cornstarch.\r\nFry in the hot oil for 5 minutes until golden. Drain.\r\nSimmer the lemon juice and zest, honey and stock with 1 tsp cornstarch mixed in water for 2 minutes until glossy.\r\nToss the chicken in the sauce and serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/7/7e/Lemonchicken.jpg","tags":["Fried","Family"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"3"},{"n":"Eggs","m":"1"},{"n":"Cornstarch","m":"80g"},{"n":"Vegetable Oil","m":"For frying"},{"n":"Lemon","m":"2"},{"n":"Honey","m":"3 tbs"},{"n":"Chicken Stock","m":"150ml"},{"n":"Rice","m":"300g"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Lemonchicken.jpg","artist":"Frances Ellen","license":"CC BY-SA 2.0"}},{"id":"qm-dan-dan-noodles","name":"Dan dan noodles","cat":"Pork","country":"China","instr":"Fry the pork with the garlic and 1 tbs soy sauce for 6 minutes until crisp.\r\nMix the sesame sauce, remaining soy sauce, chilli oil, ground Sichuan pepper and 4 tbs hot water in the bowls.\r\nCook the noodles, adding the pak choi for the last 2 minutes.\r\nDivide between the bowls, top with the pork and spring onions and mix at the table.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Dan-dan_noodles%2C_Shanghai.jpg/960px-Dan-dan_noodles%2C_Shanghai.jpg","tags":["Spicy","Noodles"],"yt":"","src":"","ingr":[{"n":"Egg Noodles","m":"400g"},{"n":"Minced Pork","m":"300g"},{"n":"Chinese Sesame Sauce","m":"3 tbs"},{"n":"Soy Sauce","m":"3 tbs"},{"n":"Chilli Oil","m":"2 tbs"},{"n":"Sichuan Pepper","m":"1 tsp"},{"n":"Garlic","m":"2 cloves"},{"n":"Pak Choi","m":"4"},{"n":"Spring Onions","m":"2"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Dan-dan_noodles,_Shanghai.jpg","artist":"Steven G. Johnson","license":"CC BY-SA 3.0"}},{"id":"qm-red-braised-pork-belly","name":"Red braised pork belly","cat":"Pork","country":"China","instr":"Cut the pork into cubes, blanch in boiling water for 3 minutes and drain.\r\nMelt the sugar in a wok until amber, add the pork and toss to coat.\r\nAdd the wine, both soy sauces, ginger, star anise, spring onions and water to just cover. Simmer covered for 1 hour.\r\nUncover and boil for 10 minutes until the sauce is sticky. Serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/f/f4/%E7%B4%85%E7%87%92%E8%82%89_Braised_pork_in_brown_sauce.jpg","tags":["Braise"],"yt":"","src":"","ingr":[{"n":"Pork Belly Slices","m":"800g"},{"n":"Brown Sugar","m":"2 tbs"},{"n":"Shaoxing Wine","m":"3 tbs"},{"n":"Soy Sauce","m":"3 tbs"},{"n":"Dark Soy Sauce","m":"1 tbs"},{"n":"Ginger","m":"4 slices"},{"n":"Star Anise","m":"2"},{"n":"Spring Onions","m":"3"},{"n":"Rice","m":"300g"}],"time":90,"photo":{"page":"https://commons.wikimedia.org/wiki/File:%E7%B4%85%E7%87%92%E8%82%89_Braised_pork_in_brown_sauce.jpg","artist":"FotoosVanRobin Photostream","license":"CC BY 2.0"}},{"id":"qm-pork-and-cabbage-dumplings","name":"Pork and cabbage dumplings","cat":"Pork","country":"China","instr":"Chop the cabbage finely, salt it, leave for 10 minutes and squeeze dry.\r\nMix with the pork, ginger, spring onions, 2 tbs soy sauce and the sesame oil.\r\nPut a teaspoon of filling on each wrapper, wet the edges and pinch closed.\r\nBoil in batches for 5 minutes, until they float and the filling is cooked.\r\nServe with the vinegar mixed with the remaining soy sauce.","thumb":"https://upload.wikimedia.org/wikipedia/commons/8/88/%E5%8F%B0%E7%81%A3%E5%8D%97%E6%8A%95%E8%8D%89%E5%B1%AF%E6%B0%B4%E9%A4%83Nantou%2C_Taiwan_Caotun_dumplings.jpg","tags":["Dumplings"],"yt":"","src":"","ingr":[{"n":"Wonton Skin","m":"300g"},{"n":"Minced Pork","m":"400g"},{"n":"Napa Cabbage","m":"300g"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Spring Onions","m":"3"},{"n":"Soy Sauce","m":"3 tbs"},{"n":"Sesame Seed Oil","m":"1 tbs"},{"n":"Rice Vinegar","m":"3 tbs"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:%E5%8F%B0%E7%81%A3%E5%8D%97%E6%8A%95%E8%8D%89%E5%B1%AF%E6%B0%B4%E9%A4%83Nantou,_Taiwan_Caotun_dumplings.jpg","artist":"Yeepunchmen","license":"CC BY-SA 4.0"}},{"id":"qm-cumin-lamb","name":"Cumin lamb","cat":"Lamb","country":"China","instr":"Cook the rice. Toss the lamb with the soy sauce and cornstarch.\r\nToast the lightly crushed cumin in a dry wok for 1 minute.\r\nAdd oil and stir-fry the lamb in a very hot wok for 3 minutes.\r\nAdd the onion, garlic, chilli and cumin and stir-fry for 2 minutes. Finish with coriander.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Cumin_Lamb_%285179533335%29.jpg/960px-Cumin_Lamb_%285179533335%29.jpg","tags":["Quick","Spicy"],"yt":"","src":"","ingr":[{"n":"Lamb Leg","m":"500g"},{"n":"Cumin Seeds","m":"2 tbs"},{"n":"Chilli Flakes","m":"1 tsp"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Soy Sauce","m":"2 tbs"},{"n":"Cornstarch","m":"1 tsp"},{"n":"Coriander","m":"1 handful"},{"n":"Rice","m":"300g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Cumin_Lamb_(5179533335).jpg","artist":"Neil Conway from Oakland, USA","license":"CC BY 2.0"}},{"id":"qm-three-cup-chicken","name":"Three cup chicken","cat":"Chicken","country":"China","instr":"Fry the ginger and whole garlic cloves in the sesame oil for 3 minutes.\r\nAdd the chicken pieces and brown for 6 minutes.\r\nAdd the soy sauce, rice wine and sugar, cover and simmer for 15 minutes, then uncover until the sauce is sticky.\r\nStir in the basil and serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Sanbeiji.jpg/960px-Sanbeiji.jpg","tags":["Braise"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"800g"},{"n":"Sesame Seed Oil","m":"3 tbs"},{"n":"Soy Sauce","m":"4 tbs"},{"n":"Rice Wine","m":"4 tbs"},{"n":"Ginger","m":"8 slices"},{"n":"Garlic","m":"10 cloves"},{"n":"Basil Leaves","m":"1 handful"},{"n":"Brown Sugar","m":"1 tbs"},{"n":"Rice","m":"300g"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Sanbeiji.jpg","artist":"Archon6812","license":"CC BY-SA 3.0"}},{"id":"qm-twice-cooked-pork","name":"Twice-cooked pork","cat":"Pork","country":"China","instr":"Simmer the pork in water for 20 minutes. Cool and slice thinly.\r\nFry the pork slices in a wok for 4 minutes until they curl and release fat.\r\nAdd the bean paste and garlic and fry for 1 minute.\r\nAdd the sliced leek and pepper, sugar and soy sauce and stir-fry for 3 minutes. Serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Twice_cooked_pork%2C_Jia_Yan%2C_5_rue_Humblot%2C_Paris_003.jpg/960px-Twice_cooked_pork%2C_Jia_Yan%2C_5_rue_Humblot%2C_Paris_003.jpg","tags":["Spicy","Stir-fry"],"yt":"","src":"","ingr":[{"n":"Pork Belly Slices","m":"500g"},{"n":"Doubanjiang","m":"2 tbs"},{"n":"Leek","m":"1"},{"n":"Green Pepper","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Sugar","m":"1 tsp"},{"n":"Soy Sauce","m":"1 tbs"},{"n":"Rice","m":"300g"}],"time":45,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Twice_cooked_pork,_Jia_Yan,_5_rue_Humblot,_Paris_003.jpg","artist":"Guilhem Vellut from Paris, France","license":"CC BY 2.0"}},{"id":"qm-tomato-and-egg-noodle-soup","name":"Tomato and egg noodle soup","cat":"Vegetarian","country":"China","instr":"Fry the chopped tomatoes in a little oil for 4 minutes until soft.\r\nAdd the stock and soy sauce and bring to the boil.\r\nDrizzle in the beaten eggs, stirring gently to make ribbons.\r\nCook the noodles, divide into bowls and pour over the soup. Add spring onions and sesame oil.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/Tomato_and_egg_soup.jpg/960px-Tomato_and_egg_soup.jpg","tags":["Quick","Soup","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Egg Noodles","m":"300g"},{"n":"Tomatoes","m":"4"},{"n":"Eggs","m":"4"},{"n":"Vegetable Stock","m":"1.2 litres"},{"n":"Soy Sauce","m":"2 tbs"},{"n":"Spring Onions","m":"3"},{"n":"Sesame Seed Oil","m":"1 tsp"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Tomato_and_egg_soup.jpg","artist":"NNU-10-HanRongrong","license":"CC BY 3.0"}},{"id":"qm-chicken-and-sweetcorn-soup","name":"Chicken and sweetcorn soup","cat":"Chicken","country":"China","instr":"Poach the chicken in the stock with the ginger for 12 minutes. Lift out and shred.\r\nAdd the creamed corn and soy sauce to the stock and bring to a simmer.\r\nStir in the cornstarch mixed with a little water and cook for 1 minute.\r\nDrizzle in the beaten eggs, return the chicken and finish with spring onions.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Corn_soup.jpg/960px-Corn_soup.jpg","tags":["Quick","Soup"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"2"},{"n":"Creamed Corn","m":"400g"},{"n":"Chicken Stock","m":"1.2 litres"},{"n":"Eggs","m":"2"},{"n":"Cornstarch","m":"2 tbs"},{"n":"Ginger","m":"1 tsp grated"},{"n":"Spring Onions","m":"3"},{"n":"Soy Sauce","m":"1 tbs"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Corn_soup.jpg","artist":"Laurier","license":"CC BY-SA 3.0"}},{"id":"qm-steamed-salmon-with-ginger-and-soy","name":"Steamed salmon with ginger and soy","cat":"Seafood","country":"China","instr":"Cook the rice.\r\nPut the salmon on a plate in a steamer with half the ginger and steam for 8 minutes, adding the pak choi for the last 4 minutes.\r\nTop the fish with the remaining ginger and sliced spring onions and pour over the soy sauce.\r\nHeat the oils until smoking and pour over the fish to sizzle. Serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Ginger_Scallion_Red_Perch_%2850-366%29_%2825058329532%29.jpg/960px-Ginger_Scallion_Red_Perch_%2850-366%29_%2825058329532%29.jpg","tags":["Quick","Fish"],"yt":"","src":"","ingr":[{"n":"Salmon","m":"4 fillets"},{"n":"Ginger","m":"3 tbs"},{"n":"Spring Onions","m":"4"},{"n":"Soy Sauce","m":"3 tbs"},{"n":"Sesame Seed Oil","m":"1 tbs"},{"n":"Vegetable Oil","m":"2 tbs"},{"n":"Rice","m":"300g"},{"n":"Pak Choi","m":"4"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Ginger_Scallion_Red_Perch_(50-366)_(25058329532).jpg","artist":"Tim Sackton from Somerville, MA","license":"CC BY-SA 2.0"}},{"id":"qm-mapo-tofu-with-vegetables","name":"Mapo tofu with vegetables","cat":"Vegan","country":"China","instr":"Cook the rice. Cut the tofu into cubes and the mushrooms finely.\r\nFry the mushrooms for 4 minutes, then add the bean paste, garlic and ginger for 1 minute.\r\nAdd 250ml water and the soy sauce, slide in the tofu and simmer for 5 minutes.\r\nThicken with the cornstarch mixed with water, sprinkle with ground Sichuan pepper and spring onions.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Chen_Mapo_Tofu.jpg/960px-Chen_Mapo_Tofu.jpg","tags":["Quick","Spicy"],"yt":"","src":"","ingr":[{"n":"Tofu","m":"500g"},{"n":"Mushrooms","m":"200g"},{"n":"Doubanjiang","m":"2 tbs"},{"n":"Garlic","m":"2 cloves"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Sichuan Pepper","m":"1 tsp"},{"n":"Soy Sauce","m":"1 tbs"},{"n":"Cornstarch","m":"1 tbs"},{"n":"Spring Onions","m":"3"},{"n":"Rice","m":"300g"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Chen_Mapo_Tofu.jpg","artist":"ZhengZhou","license":"CC BY-SA 4.0"}},{"id":"qm-thai-red-chicken-curry","name":"Thai red chicken curry","cat":"Chicken","country":"Thailand","instr":"Cook the rice.\r\nFry the curry paste in a few spoons of the thick coconut cream for 2 minutes until fragrant.\r\nAdd the sliced chicken and cook for 3 minutes, then the rest of the coconut milk, the lime leaves, fish sauce and sugar.\r\nSimmer for 12 minutes, adding the green beans for the last 5 minutes. Stir in the basil and serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Kaeng_phet_mu.jpg/960px-Kaeng_phet_mu.jpg","tags":["Curry","Spicy"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"600g"},{"n":"Thai Red Curry Paste","m":"3 tbs"},{"n":"Coconut Milk","m":"400ml"},{"n":"Green Beans","m":"200g"},{"n":"Fish Sauce","m":"2 tbs"},{"n":"Brown Sugar","m":"1 tbs"},{"n":"Kaffir Lime Leaves","m":"4"},{"n":"Basil Leaves","m":"1 handful"},{"n":"Jasmine Rice","m":"300g"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Kaeng_phet_mu.jpg","artist":"Takeaway","license":"CC BY-SA 3.0"}},{"id":"qm-thai-yellow-curry-with-chicken-and-potatoes","name":"Thai yellow curry with chicken and potatoes","cat":"Chicken","country":"Thailand","instr":"Cook the rice. Fry the curry paste and curry powder in a little oil for 1 minute.\r\nAdd the chicken pieces and onion and cook for 4 minutes.\r\nAdd the coconut milk, potatoes in cubes, fish sauce, sugar and 150ml water. Simmer for 20 minutes until the potatoes are tender.\r\nServe with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Kaeng_kari_kai.JPG/960px-Kaeng_kari_kai.JPG","tags":["Curry","Family"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"600g"},{"n":"Curry Powder","m":"2 tbs"},{"n":"Thai Red Curry Paste","m":"1 tbs"},{"n":"Coconut Milk","m":"400ml"},{"n":"Potatoes","m":"400g"},{"n":"Onion","m":"1"},{"n":"Fish Sauce","m":"2 tbs"},{"n":"Brown Sugar","m":"1 tbs"},{"n":"Jasmine Rice","m":"300g"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Kaeng_kari_kai.JPG","artist":"Takeaway","license":"CC BY-SA 3.0"}},{"id":"qm-larb-gai","name":"Larb gai","cat":"Chicken","country":"Thailand","instr":"Toast the 2 tbs of rice in a dry pan until golden, then grind to a powder.\r\nCook the minced chicken with 3 tbs water for 5 minutes, breaking it up.\r\nOff the heat, add the lime juice, fish sauce, chilli, sliced onion, herbs and toasted rice powder.\r\nServe in lettuce cups.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/LaoFood_LarbNeua.JPG/960px-LaoFood_LarbNeua.JPG","tags":["Quick","Salad","Spicy"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"500g"},{"n":"Lime","m":"2"},{"n":"Fish Sauce","m":"3 tbs"},{"n":"Red Onions","m":"1"},{"n":"Mint","m":"1 handful"},{"n":"Coriander","m":"1 handful"},{"n":"Chilli Flakes","m":"1 tsp"},{"n":"Rice","m":"2 tbs"},{"n":"Little Gem Lettuce","m":"2"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:LaoFood_LarbNeua.JPG","artist":"Jpatokal","license":"CC BY-SA 4.0"}},{"id":"qm-thai-basil-tofu-stir-fry","name":"Thai basil tofu stir-fry","cat":"Vegan","country":"Thailand","instr":"Cook the rice. Crumble or dice the tofu and pat dry.\r\nFry the tofu in a hot wok for 6 minutes until golden.\r\nAdd the crushed garlic, chilli and green beans in pieces and stir-fry for 3 minutes.\r\nAdd the soy sauce, sugar and basil and toss until wilted.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Basil_fried_crispy_pork_with_rice_-_Chiang_Mai_-_2017-07-11_%28002%29.jpg/960px-Basil_fried_crispy_pork_with_rice_-_Chiang_Mai_-_2017-07-11_%28002%29.jpg","tags":["Quick","Spicy"],"yt":"","src":"","ingr":[{"n":"Tofu","m":"400g"},{"n":"Green Beans","m":"150g"},{"n":"Garlic","m":"4 cloves"},{"n":"Red Chilli","m":"2"},{"n":"Soy Sauce","m":"3 tbs"},{"n":"Brown Sugar","m":"1 tsp"},{"n":"Basil Leaves","m":"2 handfuls"},{"n":"Jasmine Rice","m":"300g"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Basil_fried_crispy_pork_with_rice_-_Chiang_Mai_-_2017-07-11_(002).jpg","artist":"Iudexvivorum","license":"CC0"}},{"id":"qm-khao-man-gai","name":"Khao man gai","cat":"Chicken","country":"Thailand","instr":"Poach the chicken in water with the ginger and 2 garlic cloves for 25 minutes. Keep the broth.\r\nFry the rice with the remaining chopped garlic for 2 minutes, then cook it in 500ml of the chicken broth for 15 minutes.\r\nMix the soy sauce, vinegar, a little ginger and chopped chilli for the sauce.\r\nSlice the chicken and serve on the rice with cucumber, coriander, the sauce and a bowl of broth.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Hainanese_Chicken_Rice.jpg/960px-Hainanese_Chicken_Rice.jpg","tags":["Rice"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"8"},{"n":"Jasmine Rice","m":"320g"},{"n":"Ginger","m":"5 slices"},{"n":"Garlic","m":"4 cloves"},{"n":"Cucumber","m":"1"},{"n":"Soy Sauce","m":"3 tbs"},{"n":"Rice Vinegar","m":"2 tbs"},{"n":"Red Chilli","m":"1"},{"n":"Coriander","m":"1 handful"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Hainanese_Chicken_Rice.jpg","artist":"No machine-readable author provided. Terence assumed (based on copyright claims)","license":"CC BY 2.5"}},{"id":"qm-shaking-beef","name":"Shaking beef","cat":"Beef","country":"Vietnam","instr":"Cut the steak into 2cm cubes and marinate with the soy sauce, oyster sauce and garlic for 10 minutes.\r\nCook the rice.\r\nSear the beef in a very hot pan in one layer for 1 minute, then shake the pan for 2 minutes more. Add the onion wedges for the last minute.\r\nServe on rocket and tomatoes with lime and pepper.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Product_Shots_of_Food-Bo_Luc_Lac.jpg/960px-Product_Shots_of_Food-Bo_Luc_Lac.jpg","tags":["Quick"],"yt":"","src":"","ingr":[{"n":"Sirloin Steak","m":"600g"},{"n":"Soy Sauce","m":"2 tbs"},{"n":"Oyster Sauce","m":"2 tbs"},{"n":"Garlic","m":"3 cloves"},{"n":"Red Onions","m":"1"},{"n":"Rocket","m":"100g"},{"n":"Cherry Tomatoes","m":"200g"},{"n":"Lime","m":"1"},{"n":"Rice","m":"300g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Product_Shots_of_Food-Bo_Luc_Lac.jpg","artist":"Nick Nguyen","license":"CC BY-SA 2.0"}},{"id":"qm-vietnamese-lemongrass-chicken","name":"Vietnamese lemongrass chicken","cat":"Chicken","country":"Vietnam","instr":"Finely chop the lemongrass and mix with the garlic, fish sauce and sugar. Marinate the chicken pieces for 10 minutes.\r\nCook the rice.\r\nFry the chicken in a hot pan for 10 minutes until caramelised. Add the onion wedges and chilli for the last 3 minutes.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d8/Lemongrass_Chicken_%287491346796%29.jpg/960px-Lemongrass_Chicken_%287491346796%29.jpg","tags":["Quick"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"700g"},{"n":"Lemongrass","m":"3 stalks"},{"n":"Garlic","m":"3 cloves"},{"n":"Fish Sauce","m":"3 tbs"},{"n":"Brown Sugar","m":"2 tbs"},{"n":"Red Chilli","m":"1"},{"n":"Onion","m":"1"},{"n":"Rice","m":"300g"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Lemongrass_Chicken_(7491346796).jpg","artist":"Jen Arrr","license":"CC BY-SA 2.0"}},{"id":"qm-bun-bo-noodle-salad","name":"Bun bo noodle salad","cat":"Beef","country":"Vietnam","instr":"Cook the vermicelli, rinse in cold water and drain.\r\nMix the fish sauce, lime juice, sugar and 6 tbs water for the dressing.\r\nStir-fry the beef with the chopped lemongrass for 3 minutes.\r\nFill bowls with lettuce, noodles, grated carrot and cucumber, top with the beef, mint and crushed peanuts and pour over the dressing.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Bun_Bo_Nam_Bo.jpg/960px-Bun_Bo_Nam_Bo.jpg","tags":["Salad","Noodles"],"yt":"","src":"","ingr":[{"n":"Rice Vermicelli","m":"300g"},{"n":"Beef","m":"400g"},{"n":"Lemongrass","m":"2 stalks"},{"n":"Fish Sauce","m":"4 tbs"},{"n":"Lime","m":"2"},{"n":"Sugar","m":"2 tbs"},{"n":"Carrots","m":"2"},{"n":"Cucumber","m":"1"},{"n":"Lettuce","m":"1"},{"n":"Mint","m":"1 handful"},{"n":"Roasted Peanut","m":"50g"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Bun_Bo_Nam_Bo.jpg","artist":"fabulousfabs","license":"CC BY 2.0"}},{"id":"qm-nasi-goreng","name":"Nasi goreng","cat":"Chicken","country":"Indonesia","instr":"Stir-fry the diced chicken for 5 minutes. Add the chopped shallots, garlic, chilli and shrimp paste and cook for 2 minutes.\r\nAdd the rice and soy sauce and stir-fry for 5 minutes.\r\nFry the eggs and serve on top of the rice with sliced cucumber.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Nasi_Goreng_Kampung_%2811967588375%29.jpg/960px-Nasi_Goreng_Kampung_%2811967588375%29.jpg","tags":["Quick","Rice"],"yt":"","src":"","ingr":[{"n":"Rice","m":"300g"},{"n":"Chicken Breasts","m":"2"},{"n":"Shallots","m":"3"},{"n":"Garlic","m":"2 cloves"},{"n":"Red Chilli","m":"1"},{"n":"Dark Soy Sauce","m":"3 tbs"},{"n":"Shrimp Paste","m":"1 tsp"},{"n":"Eggs","m":"4"},{"n":"Cucumber","m":"1"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Nasi_Goreng_Kampung_(11967588375).jpg","artist":"shankar s. from Dubai, united arab emirates","license":"CC BY 2.0"}},{"id":"qm-gado-gado","name":"Gado-gado","cat":"Vegetarian","country":"Indonesia","instr":"Boil the potatoes for 15 minutes, the eggs for 9 minutes and the beans for 5 minutes.\r\nFry the tofu cubes until golden.\r\nWarm the peanut butter, coconut milk, soy sauce, lime juice and chilli sauce, whisking until smooth.\r\nArrange the vegetables, tofu and halved eggs on plates and pour over the peanut sauce.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/26/Gado_gado_jakarta.jpg/960px-Gado_gado_jakarta.jpg","tags":["Salad","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Potatoes","m":"400g"},{"n":"Green Beans","m":"200g"},{"n":"Bean Sprouts","m":"150g"},{"n":"Eggs","m":"4"},{"n":"Tofu","m":"250g"},{"n":"Cucumber","m":"1"},{"n":"Peanut Butter","m":"5 tbs"},{"n":"Coconut Milk","m":"150ml"},{"n":"Soy Sauce","m":"2 tbs"},{"n":"Lime","m":"1"},{"n":"Sweet Chilli Sauce","m":"2 tbs"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Gado_gado_jakarta.jpg","artist":"Piknikdong","license":"CC BY-SA 4.0"}},{"id":"qm-chicken-adobo","name":"Chicken adobo","cat":"Chicken","country":"Philippines","instr":"Put the chicken, soy sauce, vinegar, crushed garlic, bay leaves and peppercorns in a pan with 150ml water.\r\nBring to the boil without stirring, then cover and simmer for 30 minutes.\r\nLift out the chicken and brown it in a hot pan. Boil the sauce with the sugar for 5 minutes.\r\nReturn the chicken to the sauce and serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Adobo_DSCF4391.jpg/960px-Adobo_DSCF4391.jpg","tags":["Braise"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"8"},{"n":"Soy Sauce","m":"100ml"},{"n":"White Wine Vinegar","m":"100ml"},{"n":"Garlic","m":"8 cloves"},{"n":"Bay Leaves","m":"3"},{"n":"Peppercorns","m":"1 tsp"},{"n":"Brown Sugar","m":"1 tbs"},{"n":"Rice","m":"300g"}],"time":50,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Adobo_DSCF4391.jpg","artist":"Joy D. Ganaden","license":"CC BY-SA 4.0"}},{"id":"qm-pancit","name":"Pancit","cat":"Chicken","country":"Philippines","instr":"Soak the noodles following the packet.\r\nStir-fry the sliced chicken with the onion and garlic for 5 minutes.\r\nAdd the carrot and cabbage and stir-fry for 3 minutes.\r\nAdd the stock, soy sauce and noodles and toss until the liquid is absorbed. Serve with lemon wedges.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Pancit_Ilonggo_Style_-_12110747826.jpg/960px-Pancit_Ilonggo_Style_-_12110747826.jpg","tags":["Noodles"],"yt":"","src":"","ingr":[{"n":"Rice Vermicelli","m":"250g"},{"n":"Chicken Breasts","m":"2"},{"n":"Carrots","m":"1"},{"n":"White Cabbage","m":"200g"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Soy Sauce","m":"4 tbs"},{"n":"Chicken Stock","m":"250ml"},{"n":"Lemon","m":"1"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pancit_Ilonggo_Style_-_12110747826.jpg","artist":"pulaw","license":"CC BY 2.0"}},{"id":"qm-butter-chicken","name":"Butter chicken","cat":"Chicken","country":"India","instr":"Marinate the chicken pieces in the yogurt, half the garam masala and half the ginger garlic paste for 20 minutes.\r\nGrill or pan-fry the chicken for 10 minutes until charred.\r\nMelt the butter, fry the onion for 6 minutes, add the rest of the paste, spices and the passata and simmer for 10 minutes. Blend smooth.\r\nAdd the chicken and cream and simmer for 5 minutes. Serve with rice and naan.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Butter_Chicken_%26_Butter_Naan_-_Home_-_Chandigarh_-_India_-_0006.jpg/960px-Butter_Chicken_%26_Butter_Naan_-_Home_-_Chandigarh_-_India_-_0006.jpg","tags":["Curry","Family"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"700g"},{"n":"Greek Yogurt","m":"150g"},{"n":"Garam Masala","m":"2 tsp"},{"n":"Ginger Garlic Paste","m":"2 tbs"},{"n":"Butter","m":"50g"},{"n":"Onion","m":"1"},{"n":"Passata","m":"400ml"},{"n":"Double Cream","m":"150ml"},{"n":"Chilli Powder","m":"1 tsp"},{"n":"Basmati Rice","m":"300g"},{"n":"Naan Bread","m":"4"}],"time":45,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Butter_Chicken_%26_Butter_Naan_-_Home_-_Chandigarh_-_India_-_0006.jpg","artist":"Yuvraj Singh 97","license":"CC BY-SA 4.0"}},{"id":"qm-chicken-tikka-masala","name":"Chicken tikka masala","cat":"Chicken","country":"India","instr":"Marinate the chicken pieces in the yogurt with half the spices for 20 minutes, then grill for 10 minutes.\r\nFry the chopped onions for 8 minutes, add the garlic, ginger and remaining spices and cook for 1 minute.\r\nAdd the tomatoes and simmer for 10 minutes, then the cream and chicken for 5 minutes.\r\nServe with basmati rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Chicken_tikka_masala_%28cropped%29.jpg/960px-Chicken_tikka_masala_%28cropped%29.jpg","tags":["Curry"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"4"},{"n":"Natural Yoghurt","m":"150g"},{"n":"Garam Masala","m":"2 tsp"},{"n":"Ground Cumin","m":"1 tsp"},{"n":"Turmeric","m":"1 tsp"},{"n":"Onions","m":"2"},{"n":"Garlic","m":"3 cloves"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Single Cream","m":"150ml"},{"n":"Basmati Rice","m":"300g"}],"time":45,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Chicken_tikka_masala_(cropped).jpg","artist":"Michael Hays","license":"CC BY 2.0"}},{"id":"qm-chana-masala","name":"Chana masala","cat":"Vegan","country":"India","instr":"Fry the chopped onions in oil for 8 minutes until golden.\r\nAdd the garlic, ginger and spices and cook for 1 minute.\r\nAdd the tomatoes and chickpeas with 150ml water and simmer for 15 minutes.\r\nFinish with lemon juice and coriander and serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Chana_masala.jpg/960px-Chana_masala.jpg","tags":["Curry","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Chickpeas","m":"800g"},{"n":"Onions","m":"2"},{"n":"Garlic","m":"3 cloves"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Garam Masala","m":"2 tsp"},{"n":"Ground Cumin","m":"1 tsp"},{"n":"Turmeric","m":"1/2 tsp"},{"n":"Lemon","m":"1/2"},{"n":"Coriander","m":"1 handful"},{"n":"Basmati Rice","m":"300g"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Chana_masala.jpg","artist":"Simon Law (sfllaw) from Montréal, QC, Canada","license":"CC BY-SA 2.0"}},{"id":"qm-palak-paneer","name":"Palak paneer","cat":"Vegetarian","country":"India","instr":"Wilt the spinach in a pan for 3 minutes, then blend to a purée.\r\nFry the paneer cubes until golden and set aside.\r\nFry the onion for 6 minutes, add the garlic, ginger, spices and chopped tomatoes and cook for 5 minutes.\r\nAdd the spinach and cream, simmer for 5 minutes and stir in the paneer. Serve with naan.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b7/Palakpaneer_Rayagada_Odisha_0009.jpg/960px-Palakpaneer_Rayagada_Odisha_0009.jpg","tags":["Curry","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Paneer","m":"300g"},{"n":"Spinach","m":"500g"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"3 cloves"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Tomatoes","m":"2"},{"n":"Garam Masala","m":"1 tsp"},{"n":"Ground Cumin","m":"1 tsp"},{"n":"Single Cream","m":"100ml"},{"n":"Naan Bread","m":"4"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Palakpaneer_Rayagada_Odisha_0009.jpg","artist":"Lopanayak","license":"CC BY-SA 4.0"}},{"id":"qm-aloo-gobi","name":"Aloo gobi","cat":"Vegan","country":"India","instr":"Fry the cumin seeds in oil for 30 seconds, then the onion for 5 minutes.\r\nAdd the garlic, ginger, turmeric and chopped tomatoes and cook for 3 minutes.\r\nAdd the potatoes and cauliflower in pieces with 100ml water, cover and cook for 20 minutes, stirring now and then.\r\nSprinkle with garam masala and coriander. Serve with naan.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/Aloo_Ghobi.jpg/960px-Aloo_Ghobi.jpg","tags":["Curry","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Potatoes","m":"500g"},{"n":"Cauliflower","m":"1"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Cumin Seeds","m":"1 tsp"},{"n":"Turmeric","m":"1 tsp"},{"n":"Garam Masala","m":"1 tsp"},{"n":"Tomatoes","m":"2"},{"n":"Coriander","m":"1 handful"},{"n":"Naan Bread","m":"4"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Aloo_Ghobi.jpg","artist":"Sapanabehl","license":"CC BY-SA 4.0"}},{"id":"qm-dal-makhani","name":"Dal makhani","cat":"Vegetarian","country":"India","instr":"Cook the lentils in water for 30 minutes until soft.\r\nFry the onion in the butter for 6 minutes, add the garlic, ginger and garam masala for 1 minute.\r\nAdd the passata, the lentils with a little of their water and the beans. Simmer for 20 minutes, stirring often.\r\nStir in the cream and serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Punjabi_style_Dal_Makhani.jpg/960px-Punjabi_style_Dal_Makhani.jpg","tags":["Curry","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Brown Lentils","m":"250g"},{"n":"Kidney Beans","m":"400g"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"3 cloves"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Passata","m":"300ml"},{"n":"Butter","m":"50g"},{"n":"Double Cream","m":"100ml"},{"n":"Garam Masala","m":"2 tsp"},{"n":"Basmati Rice","m":"300g"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Punjabi_style_Dal_Makhani.jpg","artist":"Radhikamprabhu82","license":"CC BY-SA 4.0"}},{"id":"qm-chicken-korma","name":"Chicken korma","cat":"Chicken","country":"India","instr":"Fry the chopped onions for 8 minutes until soft, add the garlic, ginger and spices for 1 minute.\r\nAdd the chicken pieces and cook for 5 minutes.\r\nAdd the coconut milk and ground almonds and simmer for 15 minutes.\r\nOff the heat, stir in the yogurt. Serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/Chicken_Korma.JPG/960px-Chicken_Korma.JPG","tags":["Curry","Family"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"4"},{"n":"Onions","m":"2"},{"n":"Garlic","m":"2 cloves"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Ground Coriander","m":"1 tsp"},{"n":"Garam Masala","m":"1 tsp"},{"n":"Turmeric","m":"1/2 tsp"},{"n":"Almonds","m":"50g"},{"n":"Coconut Milk","m":"200ml"},{"n":"Natural Yoghurt","m":"100g"},{"n":"Basmati Rice","m":"300g"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Chicken_Korma.JPG","artist":"Miansari66","license":"CC0"}},{"id":"qm-lamb-keema-with-peas","name":"Lamb keema with peas","cat":"Lamb","country":"India","instr":"Fry the onion for 6 minutes, add the mince and brown for 6 minutes.\r\nAdd the garlic, ginger and spices and cook for 1 minute.\r\nAdd the tomatoes and simmer for 15 minutes, adding the peas for the last 5 minutes. Serve with naan.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Keema_Matar_%28a_dish_from_India%29.jpg/960px-Keema_Matar_%28a_dish_from_India%29.jpg","tags":["Curry","Quick"],"yt":"","src":"","ingr":[{"n":"Lamb Mince","m":"500g"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"3 cloves"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Garam Masala","m":"2 tsp"},{"n":"Ground Cumin","m":"1 tsp"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Frozen Peas","m":"200g"},{"n":"Naan Bread","m":"4"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Keema_Matar_(a_dish_from_India).jpg","artist":"Cabeza2000","license":"CC BY-SA 4.0"}},{"id":"qm-vegetable-biryani","name":"Vegetable biryani","cat":"Vegetarian","country":"India","instr":"Fry the sliced onions in the ghee for 12 minutes until deep golden. Set half aside.\r\nAdd the vegetables and spice mix and cook for 5 minutes, then stir in the yogurt.\r\nParboil the rice for 5 minutes and drain. Spread over the vegetables and sprinkle with the saffron soaked in 3 tbs hot water.\r\nCover tightly and cook on very low heat for 20 minutes. Serve topped with the crispy onions and cashews.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/%22Hyderabadi_Dum_Biryani%22.jpg/960px-%22Hyderabadi_Dum_Biryani%22.jpg","tags":["Rice","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Basmati Rice","m":"320g"},{"n":"Onions","m":"2"},{"n":"Carrots","m":"2"},{"n":"Cauliflower","m":"1/2"},{"n":"Frozen Peas","m":"150g"},{"n":"Biryani Masala","m":"2 tbs"},{"n":"Natural Yoghurt","m":"150g"},{"n":"Saffron","m":"1 pinch"},{"n":"Cashew Nuts","m":"50g"},{"n":"Ghee","m":"3 tbs"}],"time":50,"photo":{"page":"https://commons.wikimedia.org/wiki/File:%22Hyderabadi_Dum_Biryani%22.jpg","artist":"Mahi Tatavarty","license":"CC BY-SA 4.0"}},{"id":"qm-goan-prawn-curry","name":"Goan prawn curry","cat":"Seafood","country":"India","instr":"Fry the onion for 6 minutes, add the garlic, ginger and spices and cook for 1 minute.\r\nAdd the coconut milk and tamarind and simmer for 8 minutes.\r\nAdd the prawns and cook for 4 minutes until pink. Serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/Goan_prawn_curry.jpg/960px-Goan_prawn_curry.jpg","tags":["Curry","Spicy"],"yt":"","src":"","ingr":[{"n":"King Prawns","m":"500g"},{"n":"Coconut Milk","m":"400ml"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"3 cloves"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Chilli Powder","m":"1 tsp"},{"n":"Turmeric","m":"1 tsp"},{"n":"Ground Coriander","m":"1 tsp"},{"n":"Tamarind Paste","m":"1 tbs"},{"n":"Basmati Rice","m":"300g"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Goan_prawn_curry.jpg","artist":"Schellack at English Wikipedia","license":"CC BY 3.0"}},{"id":"qm-egg-curry","name":"Egg curry","cat":"Vegetarian","country":"India","instr":"Boil the eggs for 9 minutes, peel them and score lightly.\r\nFry the onions for 8 minutes, add the garlic, ginger and spices for 1 minute.\r\nAdd the tomatoes and coconut milk and simmer for 10 minutes.\r\nAdd the eggs and simmer for 5 minutes. Serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/Egg_curry_pic.jpg/960px-Egg_curry_pic.jpg","tags":["Curry","Quick","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Eggs","m":"8"},{"n":"Onions","m":"2"},{"n":"Garlic","m":"2 cloves"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Garam Masala","m":"2 tsp"},{"n":"Turmeric","m":"1/2 tsp"},{"n":"Coconut Milk","m":"200ml"},{"n":"Basmati Rice","m":"300g"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Egg_curry_pic.jpg","artist":"Ekabhishek","license":"CC BY-SA 4.0"}},{"id":"qm-chicken-jalfrezi","name":"Chicken jalfrezi","cat":"Chicken","country":"India","instr":"Brown the chicken pieces in oil for 5 minutes. Set aside.\r\nStir-fry the onions and peppers in chunks with the chillies and garlic for 5 minutes.\r\nAdd the curry powder, then the tomatoes and chicken and simmer for 12 minutes. Serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Chicken_Jalfrezi_%282103956162%29.jpg/960px-Chicken_Jalfrezi_%282103956162%29.jpg","tags":["Curry","Spicy"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"4"},{"n":"Onions","m":"2"},{"n":"Red Pepper","m":"1"},{"n":"Green Pepper","m":"1"},{"n":"Green Chilli","m":"2"},{"n":"Garlic","m":"3 cloves"},{"n":"Curry Powder","m":"2 tbs"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Basmati Rice","m":"300g"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Chicken_Jalfrezi_(2103956162).jpg","artist":"David Pursehouse from Kawasaki, Japan","license":"CC BY 2.0"}},{"id":"qm-saag-aloo","name":"Saag aloo","cat":"Vegan","country":"India","instr":"Boil the potatoes in cubes for 10 minutes and drain.\r\nFry the cumin seeds for 30 seconds, then the onion for 5 minutes, then the garlic, ginger and turmeric.\r\nAdd the potatoes and fry for 5 minutes, then the spinach until wilted. Sprinkle with garam masala and serve with naan.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Punjabi_Sarsoon_Ka_Saag.JPG/960px-Punjabi_Sarsoon_Ka_Saag.JPG","tags":["Curry","Quick","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Potatoes","m":"700g"},{"n":"Spinach","m":"300g"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Ginger","m":"1 tbs grated"},{"n":"Cumin Seeds","m":"1 tsp"},{"n":"Turmeric","m":"1 tsp"},{"n":"Garam Masala","m":"1 tsp"},{"n":"Naan Bread","m":"4"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Punjabi_Sarsoon_Ka_Saag.JPG","artist":"Miansari66","license":"Public domain"}},{"id":"qm-malaysian-chicken-satay-with-peanut-sauce","name":"Malaysian chicken satay with peanut sauce","cat":"Chicken","country":"Malaysia","instr":"Marinate the chicken strips with the turmeric, cumin, 1 tbs sugar and 2 tbs soy sauce for 20 minutes. Thread onto skewers.\r\nCook the rice.\r\nWarm the peanut butter, coconut milk, remaining sugar and soy sauce and the lime juice, stirring until smooth.\r\nGrill the skewers for 8 minutes, turning. Serve with the sauce, rice and cucumber.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Sate_Udang.JPG/960px-Sate_Udang.JPG","tags":["Grill"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"700g"},{"n":"Turmeric","m":"1 tsp"},{"n":"Ground Cumin","m":"1 tsp"},{"n":"Brown Sugar","m":"2 tbs"},{"n":"Soy Sauce","m":"3 tbs"},{"n":"Peanut Butter","m":"5 tbs"},{"n":"Coconut Milk","m":"200ml"},{"n":"Lime","m":"1"},{"n":"Jasmine Rice","m":"300g"},{"n":"Cucumber","m":"1"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Sate_Udang.JPG","artist":"Gunawan Kartapranata","license":"CC BY-SA 4.0"}},{"id":"qm-garlic-chicken","name":"Garlic chicken","cat":"Chicken","country":"Spain","instr":"Cut the potatoes into cubes and roast them with a little oil at 210C for 30 minutes.\r\nBrown the seasoned chicken in the oil for 10 minutes. Add the halved garlic cloves and bay leaves and cook for 3 minutes.\r\nPour in the wine, cover and simmer for 20 minutes.\r\nSprinkle with parsley and serve with the potatoes.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Pollo_al_ajillo.jpg/960px-Pollo_al_ajillo.jpg","tags":["Classic"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"8"},{"n":"Garlic","m":"12 cloves"},{"n":"Dry White Wine","m":"150ml"},{"n":"Bay Leaves","m":"2"},{"n":"Olive Oil","m":"4 tbs"},{"n":"Parsley","m":"3 tbs chopped"},{"n":"Potatoes","m":"700g"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pollo_al_ajillo.jpg","artist":"Juan Emilio Prades Bel","license":"CC BY-SA 4.0"}},{"id":"qm-fabada-asturiana","name":"Fabada asturiana","cat":"Pork","country":"Spain","instr":"Put the bacon, whole chorizo and onion in a pot with 1 litre of water and simmer for 30 minutes.\r\nAdd the beans, garlic, paprika and saffron and simmer for 20 minutes.\r\nAdd the morcilla for the last 10 minutes. Slice the meats and serve with the beans and bread.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Fabada_en_cazuela_de_barro.jpg/960px-Fabada_en_cazuela_de_barro.jpg","tags":["Stew"],"yt":"","src":"","ingr":[{"n":"Butter Beans","m":"800g"},{"n":"Chorizo","m":"200g"},{"n":"Morcilla","m":"150g"},{"n":"Bacon","m":"150g"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Smoked Paprika","m":"1 tsp"},{"n":"Saffron","m":"1 pinch"},{"n":"Crusty Bread","m":"1"}],"time":70,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Fabada_en_cazuela_de_barro.jpg","artist":"Juan J. Martínez from Valencia, España","license":"CC BY-SA 2.0"}},{"id":"qm-spanish-lentil-stew-with-chorizo","name":"Spanish lentil stew with chorizo","cat":"Pork","country":"Spain","instr":"Fry the sliced chorizo for 3 minutes, add the onion, carrots and garlic and cook for 5 minutes.\r\nStir in the paprika, then add the lentils, diced potatoes, tomatoes, bay leaf and 1.2 litres of water.\r\nSimmer for 30 minutes until the lentils are tender. Season and serve.","thumb":"https://upload.wikimedia.org/wikipedia/commons/6/61/EgFoodLentilSoup.jpg","tags":["Stew"],"yt":"","src":"","ingr":[{"n":"Brown Lentils","m":"300g"},{"n":"Chorizo","m":"150g"},{"n":"Onion","m":"1"},{"n":"Carrots","m":"2"},{"n":"Potatoes","m":"2"},{"n":"Garlic","m":"2 cloves"},{"n":"Smoked Paprika","m":"1 tsp"},{"n":"Bay Leaf","m":"1"},{"n":"Chopped Tomatoes","m":"200g"}],"time":45,"photo":{"page":"https://commons.wikimedia.org/wiki/File:EgFoodLentilSoup.jpg","artist":"Roland Unger","license":"CC BY-SA 3.0"}},{"id":"qm-riojan-potatoes-with-chorizo","name":"Riojan potatoes with chorizo","cat":"Pork","country":"Spain","instr":"Fry the sliced chorizo for 3 minutes, then the onion, pepper and garlic for 5 minutes.\r\nAdd the paprika and the potatoes broken into chunks with a knife, stir for 1 minute.\r\nCover with water, add the bay leaf and simmer for 25 minutes. Serve with bread.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Patatas_a_la_riojana.jpg/960px-Patatas_a_la_riojana.jpg","tags":["Stew"],"yt":"","src":"","ingr":[{"n":"Potatoes","m":"1kg"},{"n":"Chorizo","m":"250g"},{"n":"Onion","m":"1"},{"n":"Green Pepper","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Smoked Paprika","m":"2 tsp"},{"n":"Bay Leaf","m":"1"},{"n":"Crusty Bread","m":"1"}],"time":45,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Patatas_a_la_riojana.jpg","artist":"Lorena Suárez","license":"CC BY-SA 2.0"}},{"id":"qm-spanakopita","name":"Spanakopita","cat":"Vegetarian","country":"Greece","instr":"Wilt the spinach, squeeze it very dry and chop.\r\nMix with the crumbled feta, eggs, sliced spring onions and dill.\r\nHeat the oven to 190C. Layer half the filo sheets in an oiled dish, brushing each with oil, add the filling and cover with the remaining sheets, oiling each.\r\nScore the top and bake for 40 minutes until golden. Serve with salad.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/Spanakopita.jpg/960px-Spanakopita.jpg","tags":["Pie","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Spinach","m":"800g"},{"n":"Feta","m":"250g"},{"n":"Eggs","m":"2"},{"n":"Spring Onions","m":"6"},{"n":"Dill","m":"1 bunch"},{"n":"Filo Pastry","m":"250g"},{"n":"Olive Oil","m":"6 tbs"},{"n":"Lettuce","m":"1"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Spanakopita.jpg","artist":"Alpha","license":"CC BY-SA 2.0"}},{"id":"qm-pastitsio","name":"Pastitsio","cat":"Beef","country":"Greece","instr":"Fry the onion and beef for 8 minutes, add the tomatoes and cinnamon and simmer for 20 minutes.\r\nCook the pasta for 2 minutes less than the packet says.\r\nMake a béchamel with the butter, flour and milk, simmer for 5 minutes, then off the heat beat in the eggs and half the cheese.\r\nHeat the oven to 180C. Layer half the pasta, the meat, the rest of the pasta and the béchamel, sprinkle with the cheese and bake for 40 minutes.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/Pastitsio_homemade.jpg/960px-Pastitsio_homemade.jpg","tags":["Bake","Family"],"yt":"","src":"","ingr":[{"n":"Macaroni","m":"400g"},{"n":"Minced Beef","m":"500g"},{"n":"Onion","m":"1"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Ground Cinnamon","m":"1/2 tsp"},{"n":"Milk","m":"700ml"},{"n":"Butter","m":"60g"},{"n":"Plain Flour","m":"60g"},{"n":"Eggs","m":"2"},{"n":"Parmesan","m":"80g"}],"time":75,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pastitsio_homemade.jpg","artist":"Sam Bailey","license":"CC BY-SA 4.0"}},{"id":"qm-greek-salad-with-chickpeas","name":"Greek salad with chickpeas","cat":"Vegetarian","country":"Greece","instr":"Cut the tomatoes and cucumber into chunks and slice the onion thinly.\r\nMix with the drained chickpeas and olives and season.\r\nTop with the feta in a slab, sprinkle with oregano and drizzle with olive oil. Serve with warm pita.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/Greece_Food_Horiatiki.JPG/960px-Greece_Food_Horiatiki.JPG","tags":["Quick","Salad","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Tomatoes","m":"4"},{"n":"Cucumber","m":"1"},{"n":"Red Onions","m":"1"},{"n":"Feta","m":"200g"},{"n":"Black Olives","m":"80g"},{"n":"Chickpeas","m":"400g"},{"n":"Dried Oregano","m":"1 tsp"},{"n":"Extra Virgin Olive Oil","m":"5 tbs"},{"n":"Pita Bread","m":"4"}],"time":15,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Greece_Food_Horiatiki.JPG","artist":"User:Jpatokal","license":"CC BY-SA 4.0"}},{"id":"qm-pork-gyros-with-tzatziki","name":"Pork gyros with tzatziki","cat":"Pork","country":"Greece","instr":"Slice the pork thinly and marinate with the oregano, paprika, 2 garlic cloves, lemon juice and olive oil for 15 minutes.\r\nGrate the cucumber, squeeze it and mix with the yogurt and remaining garlic.\r\nCook the fries in the oven following the packet. Fry the pork in a hot pan for 6 minutes until charred.\r\nFill the warm pitas with pork, tzatziki, tomato, onion and a few fries.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Pita_giros.JPG/960px-Pita_giros.JPG","tags":["Wrap"],"yt":"","src":"","ingr":[{"n":"Pork Shoulder Steaks","m":"600g"},{"n":"Dried Oregano","m":"2 tsp"},{"n":"Smoked Paprika","m":"1 tsp"},{"n":"Garlic","m":"3 cloves"},{"n":"Lemon","m":"1"},{"n":"Greek Yogurt","m":"250g"},{"n":"Cucumber","m":"1"},{"n":"Pita Bread","m":"4"},{"n":"Tomatoes","m":"2"},{"n":"Red Onions","m":"1"},{"n":"Fries","m":"400g"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pita_giros.JPG","artist":"Antonio Fajardo i López","license":"CC BY-SA 3.0"}},{"id":"qm-lamb-kleftiko","name":"Lamb kleftiko","cat":"Lamb","country":"Greece","instr":"Rub the lamb with garlic, lemon juice, oregano, oil, salt and pepper.\r\nPut it in a large dish with the potatoes, onions and tomatoes in chunks, cover tightly with foil.\r\nBake at 160C for 2 hours 30 minutes until the meat falls apart.\r\nCrumble the feta on top and serve.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Kleftiko.JPG/960px-Kleftiko.JPG","tags":["Roast"],"yt":"","src":"","ingr":[{"n":"Lamb Shoulder","m":"1.2kg"},{"n":"Potatoes","m":"800g"},{"n":"Garlic","m":"6 cloves"},{"n":"Lemon","m":"2"},{"n":"Dried Oregano","m":"2 tsp"},{"n":"Tomatoes","m":"2"},{"n":"Red Onions","m":"2"},{"n":"Olive Oil","m":"4 tbs"},{"n":"Feta","m":"100g"}],"time":180,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Kleftiko.JPG","artist":"Lord Mountbatten","license":"CC BY-SA 3.0"}},{"id":"qm-chicken-lemon-rice-soup","name":"Chicken lemon rice soup","cat":"Chicken","country":"Greece","instr":"Poach the chicken in the stock for 15 minutes, lift out and shred.\r\nCook the rice in the stock for 15 minutes.\r\nWhisk the eggs with the lemon juice, then whisk in two ladles of hot stock.\r\nOff the heat, stir the egg mixture into the soup, add the chicken and dill and warm gently without boiling.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/Avgolemono_soup.jpg/960px-Avgolemono_soup.jpg","tags":["Soup"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"2"},{"n":"Chicken Stock","m":"1.5 litres"},{"n":"Rice","m":"100g"},{"n":"Eggs","m":"3"},{"n":"Lemon","m":"2"},{"n":"Dill","m":"2 tbs chopped"},{"n":"Crusty Bread","m":"1"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Avgolemono_soup.jpg","artist":"robin.norwood","license":"CC BY-SA 2.0"}},{"id":"qm-menemen","name":"Menemen","cat":"Vegetarian","country":"Turkey","instr":"Soften the chopped onion and peppers in the butter for 6 minutes.\r\nAdd the chopped tomatoes and pul biber and cook for 6 minutes.\r\nAdd the beaten eggs and stir gently until just set. Crumble over the feta and serve with bread.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Menemen_in_a_sahan.jpg/960px-Menemen_in_a_sahan.jpg","tags":["Quick","Eggs","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Eggs","m":"8"},{"n":"Tomatoes","m":"4"},{"n":"Green Pepper","m":"2"},{"n":"Onion","m":"1"},{"n":"Butter","m":"20g"},{"n":"Pul Biber","m":"1 tsp"},{"n":"Feta","m":"80g"},{"n":"Crusty Bread","m":"1"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Menemen_in_a_sahan.jpg","artist":"E4024","license":"CC BY-SA 4.0"}},{"id":"qm-red-lentil-soup","name":"Red lentil soup","cat":"Vegan","country":"Turkey","instr":"Soften the chopped onion and carrot in oil for 5 minutes.\r\nAdd the tomato purée and spices, then the rinsed lentils, diced potato and stock.\r\nSimmer for 25 minutes and blend until smooth.\r\nServe with lemon wedges and bread.","thumb":"https://upload.wikimedia.org/wikipedia/commons/6/61/EgFoodLentilSoup.jpg","tags":["Soup","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Green Red Lentils","m":"250g"},{"n":"Onion","m":"1"},{"n":"Carrots","m":"1"},{"n":"Potatoes","m":"1"},{"n":"Tomato Puree","m":"1 tbs"},{"n":"Ground Cumin","m":"1 tsp"},{"n":"Paprika","m":"1 tsp"},{"n":"Vegetable Stock","m":"1.5 litres"},{"n":"Lemon","m":"1"},{"n":"Crusty Bread","m":"1"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:EgFoodLentilSoup.jpg","artist":"Roland Unger","license":"CC BY-SA 3.0"}},{"id":"qm-turkish-kofte-with-bulgur-pilaf","name":"Turkish kofte with bulgur pilaf","cat":"Lamb","country":"Turkey","instr":"Mix the lamb with the grated onion, parsley, spices and salt. Shape into 16 small oval kofte.\r\nFry the bulgur with the tomato purée in a little oil for 2 minutes, add the stock, cover and cook for 15 minutes.\r\nGrill or pan-fry the kofte for 8 minutes, turning.\r\nServe with the pilaf, yogurt and sliced tomatoes.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Turkish_kofte%2C_bulgur_and_fries.jpg/960px-Turkish_kofte%2C_bulgur_and_fries.jpg","tags":["Grill"],"yt":"","src":"","ingr":[{"n":"Lamb Mince","m":"500g"},{"n":"Onion","m":"1"},{"n":"Parsley","m":"3 tbs chopped"},{"n":"Ground Cumin","m":"1 tsp"},{"n":"Paprika","m":"1 tsp"},{"n":"Bulgur Wheat","m":"250g"},{"n":"Tomato Puree","m":"1 tbs"},{"n":"Vegetable Stock","m":"500ml"},{"n":"Greek Yogurt","m":"150g"},{"n":"Tomatoes","m":"2"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Turkish_kofte,_bulgur_and_fries.jpg","artist":"E4024","license":"CC BY-SA 4.0"}},{"id":"qm-chicken-tagine-with-preserved-lemon-and-olives","name":"Chicken tagine with preserved lemon and olives","cat":"Chicken","country":"Morocco","instr":"Brown the chicken in oil, add the sliced onions, garlic and spices and cook for 5 minutes.\r\nAdd 300ml water, cover and simmer for 35 minutes.\r\nAdd the lemon in thin wedges and the olives and cook uncovered for 10 minutes.\r\nPrepare the couscous with boiling water and serve with the tagine and coriander.","thumb":"https://upload.wikimedia.org/wikipedia/commons/3/3a/Tajine-marocain-un-plat-varie-et-sain_%28cropped%29.jpg","tags":["Stew"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"8"},{"n":"Onions","m":"2"},{"n":"Garlic","m":"3 cloves"},{"n":"Ground Ginger","m":"1 tsp"},{"n":"Turmeric","m":"1 tsp"},{"n":"Saffron","m":"1 pinch"},{"n":"Lemon","m":"1"},{"n":"Green Olives","m":"120g"},{"n":"Coriander","m":"1 handful"},{"n":"Couscous","m":"300g"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Tajine-marocain-un-plat-varie-et-sain_(cropped).jpg","artist":"BBouchra00","license":"CC BY-SA 4.0"}},{"id":"qm-harira","name":"Harira","cat":"Lamb","country":"Morocco","instr":"Brown the lamb with the onion and celery for 6 minutes. Add the spices.\r\nAdd the tomatoes and 1.5 litres of water and simmer for 30 minutes.\r\nAdd the lentils and chickpeas and simmer for 25 minutes more.\r\nStir in the chopped coriander and serve with lemon.","thumb":"https://upload.wikimedia.org/wikipedia/commons/c/ce/Harira.png","tags":["Soup"],"yt":"","src":"","ingr":[{"n":"Lamb","m":"300g"},{"n":"Chickpeas","m":"400g"},{"n":"Green Red Lentils","m":"100g"},{"n":"Onion","m":"1"},{"n":"Celery","m":"2 sticks"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Ground Ginger","m":"1 tsp"},{"n":"Ground Cinnamon","m":"1/2 tsp"},{"n":"Turmeric","m":"1 tsp"},{"n":"Coriander","m":"1 handful"},{"n":"Lemon","m":"1"}],"time":70,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Harira.png","artist":"Kattusa24","license":"Public domain"}},{"id":"qm-couscous-royal","name":"Couscous royal","cat":"Lamb","country":"Morocco","instr":"Brown the lamb and chicken in a large pot with the onion and ras el hanout.\r\nCover with 2 litres of water and simmer for 45 minutes.\r\nAdd the carrots and turnips and cook for 15 minutes, then the courgettes and chickpeas for 15 minutes.\r\nGrill the merguez. Prepare the couscous with some of the broth.\r\nServe the couscous with the meats, vegetables, broth and harissa.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Moroccan_cuscus%2C_from_Casablanca%2C_September_2018.jpg/960px-Moroccan_cuscus%2C_from_Casablanca%2C_September_2018.jpg","tags":["Stew","Classic"],"yt":"","src":"","ingr":[{"n":"Lamb Shoulder","m":"600g"},{"n":"Chicken Drumsticks","m":"4"},{"n":"Merguez","m":"4"},{"n":"Carrots","m":"3"},{"n":"Turnips","m":"2"},{"n":"Courgettes","m":"2"},{"n":"Chickpeas","m":"400g"},{"n":"Ras El Hanout","m":"2 tbs"},{"n":"Onion","m":"1"},{"n":"Couscous","m":"400g"},{"n":"Harissa Spice","m":"1 tsp"}],"time":90,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Moroccan_cuscus,_from_Casablanca,_September_2018.jpg","artist":"Lmmima","license":"CC BY-SA 4.0"}},{"id":"qm-kefta-tagine-with-eggs","name":"Kefta tagine with eggs","cat":"Beef","country":"Morocco","instr":"Mix the beef with the grated onion, half the spices and the parsley. Roll into small balls.\r\nSimmer the tomatoes with the garlic and remaining spices for 10 minutes.\r\nAdd the meatballs, cover and cook for 15 minutes.\r\nCrack the eggs into the sauce, cover and cook for 5 minutes. Serve with bread.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Tajine_kefta_%288348397161%29.jpg/960px-Tajine_kefta_%288348397161%29.jpg","tags":["Stew"],"yt":"","src":"","ingr":[{"n":"Minced Beef","m":"500g"},{"n":"Onion","m":"1"},{"n":"Ground Cumin","m":"2 tsp"},{"n":"Paprika","m":"2 tsp"},{"n":"Parsley","m":"3 tbs chopped"},{"n":"Chopped Tomatoes","m":"800g"},{"n":"Garlic","m":"2 cloves"},{"n":"Eggs","m":"4"},{"n":"Crusty Bread","m":"1"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Tajine_kefta_(8348397161).jpg","artist":"Mzximvs VdB from Brussels, belgium","license":"CC BY-SA 2.0"}},{"id":"qm-mujaddara","name":"Mujaddara","cat":"Vegan","country":"Syria","instr":"Cook the lentils in water for 15 minutes and drain.\r\nFry the sliced onions in the oil for 20 minutes until deep brown and crisp. Set half aside.\r\nAdd the rice and cumin to the pan, then the lentils and 500ml water. Cover and cook for 15 minutes.\r\nServe topped with the crispy onions, with yogurt and cucumber.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Mujaddara.jpg/960px-Mujaddara.jpg","tags":["Rice","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Brown Lentils","m":"200g"},{"n":"Basmati Rice","m":"200g"},{"n":"Onions","m":"4"},{"n":"Olive Oil","m":"6 tbs"},{"n":"Ground Cumin","m":"2 tsp"},{"n":"Greek Yogurt","m":"200g"},{"n":"Cucumber","m":"1"}],"time":50,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Mujaddara.jpg","artist":"Bazel","license":"CC BY-SA 3.0"}},{"id":"qm-fattoush-with-chicken","name":"Fattoush with chicken","cat":"Chicken","country":"Syria","instr":"Season the chicken with half the sumac and pan-fry for 6 minutes on each side. Slice.\r\nTear the pita into pieces and toast in the oven at 200C for 8 minutes.\r\nChop the vegetables and mix with the mint, lemon juice, oil and remaining sumac.\r\nToss with the pita and top with the chicken.","thumb":"https://upload.wikimedia.org/wikipedia/commons/9/93/Fattoush_mixed-salad.jpg","tags":["Salad"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"3"},{"n":"Pita Bread","m":"3"},{"n":"Tomatoes","m":"4"},{"n":"Cucumber","m":"1"},{"n":"Radish","m":"8"},{"n":"Little Gem Lettuce","m":"2"},{"n":"Mint","m":"1 handful"},{"n":"Sumac","m":"2 tsp"},{"n":"Lemon","m":"1"},{"n":"Extra Virgin Olive Oil","m":"5 tbs"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Fattoush_mixed-salad.jpg","artist":"Arousing Appetites","license":"CC BY-SA 3.0"}},{"id":"qm-tabbouleh-with-grilled-halloumi","name":"Tabbouleh with grilled halloumi","cat":"Vegetarian","country":"Syria","instr":"Soak the bulgur in boiling water for 15 minutes and drain.\r\nChop the parsley, mint, tomatoes and spring onions finely and mix with the bulgur, lemon juice and oil.\r\nSlice the halloumi and fry in a dry pan for 2 minutes on each side. Serve on the tabbouleh.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Tabouleh_1.JPG/960px-Tabouleh_1.JPG","tags":["Salad","Quick","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Bulgur Wheat","m":"150g"},{"n":"Parsley","m":"2 bunches"},{"n":"Mint","m":"1 handful"},{"n":"Tomatoes","m":"4"},{"n":"Spring Onions","m":"4"},{"n":"Lemon","m":"2"},{"n":"Extra Virgin Olive Oil","m":"6 tbs"},{"n":"Halloumi","m":"250g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Tabouleh_1.JPG","artist":"Miansari66","license":"CC0"}},{"id":"qm-shish-tawook","name":"Shish tawook","cat":"Chicken","country":"Syria","instr":"Marinate the chicken cubes with the yogurt, garlic, lemon juice, paprika and tomato purée for at least 20 minutes.\r\nThread onto skewers and grill for 10 minutes, turning.\r\nServe in pita with garlic sauce, lettuce and tomatoes.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/40/Tavuk_%C5%9Ei%C5%9F.jpg/960px-Tavuk_%C5%9Ei%C5%9F.jpg","tags":["Grill"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"4"},{"n":"Natural Yoghurt","m":"150g"},{"n":"Garlic","m":"3 cloves"},{"n":"Lemon","m":"1"},{"n":"Paprika","m":"1 tsp"},{"n":"Tomato Puree","m":"1 tbs"},{"n":"Pita Bread","m":"4"},{"n":"Garlic Sauce","m":"4 tbs"},{"n":"Lettuce","m":"1"},{"n":"Tomatoes","m":"2"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Tavuk_%C5%9Ei%C5%9F.jpg","artist":"Garrett Ziegler","license":"CC BY-SA 4.0"}},{"id":"qm-musakhan","name":"Musakhan","cat":"Chicken","country":"Syria","instr":"Rub the chicken with half the sumac, the allspice, oil and salt. Roast at 200C for 45 minutes.\r\nCook the sliced onions slowly in the remaining oil for 25 minutes until soft and sweet. Stir in the remaining sumac.\r\nToast the pine nuts.\r\nSpread the onions on the warmed flatbreads, top with the chicken and pine nuts and serve with yogurt.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Mushakhan_Dish.jpg/960px-Mushakhan_Dish.jpg","tags":["Roast"],"yt":"","src":"","ingr":[{"n":"Chicken Legs","m":"4"},{"n":"Onions","m":"4"},{"n":"Sumac","m":"3 tbs"},{"n":"Ground Allspice","m":"1 tsp"},{"n":"Olive Oil","m":"6 tbs"},{"n":"Pine Nuts","m":"40g"},{"n":"Naan Bread","m":"4"},{"n":"Greek Yogurt","m":"150g"}],"time":70,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Mushakhan_Dish.jpg","artist":"Kokaly","license":"CC BY-SA 3.0"}},{"id":"qm-falafel-bowl-with-hummus","name":"Falafel bowl with hummus","cat":"Vegan","country":"Egypt","instr":"Heat the falafel in the oven following the packet.\r\nPrepare the couscous with boiling water and fluff with lemon juice and olive oil.\r\nChop the cucumber, tomatoes, onion and parsley.\r\nFill bowls with couscous, vegetables, falafel and hummus, and drizzle with tahini loosened with water.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Falafels_2.jpg/960px-Falafels_2.jpg","tags":["Quick","Bowl"],"yt":"","src":"","ingr":[{"n":"Falafel","m":"400g"},{"n":"Hummus","m":"200g"},{"n":"Couscous","m":"200g"},{"n":"Cucumber","m":"1"},{"n":"Cherry Tomatoes","m":"200g"},{"n":"Red Onions","m":"1"},{"n":"Parsley","m":"1 handful"},{"n":"Lemon","m":"1"},{"n":"Tahini","m":"2 tbs"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Falafels_2.jpg","artist":"Popo le Chien","license":"CC BY-SA 3.0"}},{"id":"qm-chicken-shawarma-traybake","name":"Chicken shawarma traybake","cat":"Chicken","country":"Syria","instr":"Mix the chicken with the spices, garlic, lemon juice and olive oil.\r\nSpread on a tray with the onion wedges and roast at 220C for 30 minutes until charred.\r\nSlice and serve in warm pita with yogurt.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Shawarma_2.jpg/960px-Shawarma_2.jpg","tags":["Roast"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"800g"},{"n":"Ground Cumin","m":"2 tsp"},{"n":"Paprika","m":"2 tsp"},{"n":"Turmeric","m":"1 tsp"},{"n":"Ground Cinnamon","m":"1/2 tsp"},{"n":"Garlic","m":"3 cloves"},{"n":"Lemon","m":"1"},{"n":"Red Onions","m":"2"},{"n":"Pita Bread","m":"4"},{"n":"Greek Yogurt","m":"150g"}],"time":45,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Shawarma_2.jpg","artist":"Vis M","license":"CC BY-SA 4.0"}},{"id":"qm-spanish-garlic-prawns-with-rice","name":"Spanish garlic prawns with rice","cat":"Seafood","country":"Spain","instr":"Cook the rice.\r\nWarm the oil with the sliced garlic and chilli for 2 minutes.\r\nAdd the prawns and paprika and cook for 3 minutes until pink.\r\nSprinkle with parsley and serve over the rice with lemon.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Gambas_al_ajillo.jpg/960px-Gambas_al_ajillo.jpg","tags":["Quick","Shellfish"],"yt":"","src":"","ingr":[{"n":"King Prawns","m":"500g"},{"n":"Garlic","m":"6 cloves"},{"n":"Chilli Flakes","m":"1 pinch"},{"n":"Olive Oil","m":"6 tbs"},{"n":"Smoked Paprika","m":"1 tsp"},{"n":"Parsley","m":"3 tbs chopped"},{"n":"Rice","m":"300g"},{"n":"Lemon","m":"1"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Gambas_al_ajillo.jpg","artist":"Javier Lastras from España/Spain","license":"CC BY 2.0"}},{"id":"qm-portuguese-chicken-with-rice","name":"Portuguese chicken with rice","cat":"Chicken","country":"Portugal","instr":"Brown the chicken in a casserole for 8 minutes. Add the onion, garlic and sliced chorizo and cook for 4 minutes.\r\nAdd the paprika, tomatoes and stock, cover and simmer for 15 minutes.\r\nAdd the rice and cook for 18 minutes until tender. Sprinkle with parsley.","thumb":"https://upload.wikimedia.org/wikipedia/commons/7/7d/Galinhada.jpg","tags":["Rice","Family"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"8"},{"n":"Rice","m":"320g"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Chorizo","m":"100g"},{"n":"Chopped Tomatoes","m":"200g"},{"n":"Chicken Stock","m":"800ml"},{"n":"Smoked Paprika","m":"1 tsp"},{"n":"Parsley","m":"2 tbs chopped"}],"time":50,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Galinhada.jpg","artist":"Sérgio Savaman Savarese","license":"CC BY 2.0"}},{"id":"qm-grilled-halloumi-and-vegetable-couscous","name":"Grilled halloumi and vegetable couscous","cat":"Vegetarian","country":"Greece","instr":"Roast the onion wedges, courgettes in chunks, tomatoes and chickpeas with the spice and oil at 220C for 25 minutes.\r\nPrepare the couscous with boiling water and season with lemon and oil.\r\nFry the sliced halloumi for 2 minutes on each side.\r\nMix the vegetables with the couscous and mint and top with the halloumi.","thumb":"https://upload.wikimedia.org/wikipedia/commons/5/57/Halloumislice_zoom.jpg","tags":["Vegetarian"],"yt":"","src":"","ingr":[{"n":"Halloumi","m":"250g"},{"n":"Couscous","m":"300g"},{"n":"Red Onions","m":"2"},{"n":"Courgettes","m":"2"},{"n":"Cherry Tomatoes","m":"250g"},{"n":"Chickpeas","m":"400g"},{"n":"Ras El Hanout","m":"2 tsp"},{"n":"Lemon","m":"1"},{"n":"Mint","m":"1 handful"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Halloumislice_zoom.jpg","artist":"Halloumislicefresh.jpg: J.P.Lon derivative work: Zlerman (talk)","license":"Public domain"}},{"id":"qm-chili-con-carne","name":"Chili con carne","cat":"Beef","country":"Mexico","instr":"Fry the onion, garlic and diced pepper for 5 minutes. Add the beef and brown for 6 minutes.\r\nStir in the spices and tomato purée, then the tomatoes and 150ml water. Simmer for 30 minutes.\r\nAdd the beans and cook for 10 minutes more.\r\nServe with rice and sour cream.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Bowl_of_chili.jpg/960px-Bowl_of_chili.jpg","tags":["Stew","Spicy","Family"],"yt":"","src":"","ingr":[{"n":"Minced Beef","m":"500g"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Red Pepper","m":"1"},{"n":"Chilli Powder","m":"2 tsp"},{"n":"Ground Cumin","m":"2 tsp"},{"n":"Chopped Tomatoes","m":"800g"},{"n":"Kidney Beans","m":"400g"},{"n":"Tomato Puree","m":"2 tbs"},{"n":"Rice","m":"300g"},{"n":"Sour Cream","m":"100ml"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Bowl_of_chili.jpg","artist":"Carstor","license":"CC BY-SA 2.5"}},{"id":"qm-pork-carnitas-tacos","name":"Pork carnitas tacos","cat":"Pork","country":"Mexico","instr":"Cut the pork into large chunks and put in a casserole with the orange juice, juice of 1 lime, garlic, spices, salt and water to half cover.\r\nCover and cook at 160C for 2 hours 30 minutes until very tender.\r\nShred the meat and fry it in a hot pan with some of its fat for 5 minutes until crisp.\r\nServe in warm tortillas with onion, coriander, salsa and lime.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Carnitas.jpg/960px-Carnitas.jpg","tags":["Tacos"],"yt":"","src":"","ingr":[{"n":"Pork Shoulder","m":"1.2kg"},{"n":"Orange","m":"1"},{"n":"Lime","m":"2"},{"n":"Garlic","m":"4 cloves"},{"n":"Ground Cumin","m":"2 tsp"},{"n":"Dried Oregano","m":"1 tsp"},{"n":"Corn Tortillas","m":"12"},{"n":"Red Onions","m":"1"},{"n":"Coriander","m":"1 handful"},{"n":"Salsa","m":"200g"}],"time":180,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Carnitas.jpg","artist":"Mike McCune","license":"CC BY 2.0"}},{"id":"qm-chicken-quesadillas","name":"Chicken quesadillas","cat":"Chicken","country":"Mexico","instr":"Slice the chicken, toss with the seasoning and fry for 7 minutes.\r\nLay 4 tortillas flat and cover with cheese, chicken, corn and beans. Top with the other tortillas.\r\nCook each quesadilla in a dry pan for 3 minutes on each side until the cheese melts.\r\nCut into wedges and serve with sour cream and salsa.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7e/Chicken_quesadilla_-_Massachusetts.jpg/960px-Chicken_quesadilla_-_Massachusetts.jpg","tags":["Quick","Family"],"yt":"","src":"","ingr":[{"n":"Flour Tortilla","m":"8"},{"n":"Chicken Breasts","m":"2"},{"n":"Shredded Mexican Cheese","m":"250g"},{"n":"Sweetcorn","m":"150g"},{"n":"Black Beans","m":"200g"},{"n":"Fajita Seasoning","m":"2 tsp"},{"n":"Sour Cream","m":"100ml"},{"n":"Salsa","m":"150g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Chicken_quesadilla_-_Massachusetts.jpg","artist":"Daderot","license":"CC0"}},{"id":"qm-beef-burritos","name":"Beef burritos","cat":"Beef","country":"Mexico","instr":"Cook the rice.\r\nFry the onion and beef for 8 minutes, add the spices and the beans and cook for 5 minutes.\r\nWarm the tortillas and fill with rice, beef, cheese, salsa and lettuce.\r\nFold in the sides, roll up tightly and toast briefly in a dry pan.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Burrito.JPG/960px-Burrito.JPG","tags":["Wrap"],"yt":"","src":"","ingr":[{"n":"Flour Tortilla","m":"4"},{"n":"Minced Beef","m":"400g"},{"n":"Rice","m":"200g"},{"n":"Black Beans","m":"400g"},{"n":"Onion","m":"1"},{"n":"Ground Cumin","m":"1 tsp"},{"n":"Chilli Powder","m":"1 tsp"},{"n":"Cheddar Cheese","m":"120g"},{"n":"Salsa","m":"150g"},{"n":"Lettuce","m":"1/2"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Burrito.JPG","artist":"samuelfernandezrivera","license":"CC0"}},{"id":"qm-chicken-fajitas","name":"Chicken fajitas","cat":"Chicken","country":"Mexico","instr":"Slice the chicken, peppers and onion and toss with the seasoning and a little oil.\r\nCook in a very hot pan for 8 minutes until charred.\r\nMash the avocados with lime juice and salt.\r\nServe with the warm tortillas, avocado and sour cream.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Chicken_fajita_platter%2C_Lone_Star_Texas_Grill%2C_Windsor%2C_Ontario%2C_2025-06-14_03.jpg/960px-Chicken_fajita_platter%2C_Lone_Star_Texas_Grill%2C_Windsor%2C_Ontario%2C_2025-06-14_03.jpg","tags":["Quick","Wrap"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"3"},{"n":"Red Pepper","m":"1"},{"n":"Green Pepper","m":"1"},{"n":"Red Onions","m":"1"},{"n":"Fajita Seasoning","m":"2 tbs"},{"n":"Flour Tortilla","m":"8"},{"n":"Avocado","m":"2"},{"n":"Sour Cream","m":"100ml"},{"n":"Lime","m":"1"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Chicken_fajita_platter,_Lone_Star_Texas_Grill,_Windsor,_Ontario,_2025-06-14_03.jpg","artist":"Crisco 1492","license":"CC BY-SA 4.0"}},{"id":"qm-arroz-con-pollo","name":"Arroz con pollo","cat":"Chicken","country":"Colombia","instr":"Brown the chicken in a casserole for 8 minutes. Add the onion, pepper and garlic and cook for 4 minutes.\r\nAdd the spices and rice and stir for 1 minute, then add the stock.\r\nCover and simmer for 20 minutes, adding the peas for the last 5 minutes. Sprinkle with coriander.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Arroz-con-Pollo.jpg/960px-Arroz-con-Pollo.jpg","tags":["Rice","Family"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"8"},{"n":"Rice","m":"320g"},{"n":"Onion","m":"1"},{"n":"Red Pepper","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Ground Cumin","m":"1 tsp"},{"n":"Turmeric","m":"1 tsp"},{"n":"Chicken Stock","m":"750ml"},{"n":"Frozen Peas","m":"150g"},{"n":"Coriander","m":"1 handful"}],"time":50,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Arroz-con-Pollo.jpg","artist":"Kobako","license":"CC BY-SA 2.5"}},{"id":"qm-peruvian-ceviche","name":"Peruvian ceviche","cat":"Seafood","country":"Peru","instr":"Boil the sweet potatoes in slices for 12 minutes and let them cool.\r\nCut the fish into small cubes, season with salt and cover with the lime juice. Leave for 10 minutes.\r\nAdd the very thinly sliced onion, chopped chilli and coriander.\r\nServe with the sweet potato and corn.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Cebiche_de_corvina.JPG/960px-Cebiche_de_corvina.JPG","tags":["Fish","Fresh"],"yt":"","src":"","ingr":[{"n":"Sea Bass Fillets","m":"500g"},{"n":"Lime","m":"8"},{"n":"Red Onions","m":"1"},{"n":"Red Chilli","m":"1"},{"n":"Coriander","m":"1 handful"},{"n":"Sweet Potatoes","m":"2"},{"n":"Sweetcorn","m":"150g"},{"n":"Salt","m":"to taste"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Cebiche_de_corvina.JPG","artist":"Picanteria karol","license":"CC BY-SA 4.0"}},{"id":"qm-lomo-saltado","name":"Lomo saltado","cat":"Beef","country":"Peru","instr":"Cook the rice and the fries following the packet.\r\nStir-fry the beef strips in a very hot wok for 2 minutes and set aside.\r\nStir-fry the onion wedges and garlic for 2 minutes, add the tomato wedges, soy sauce and vinegar.\r\nReturn the beef, toss in the fries and coriander and serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Lomo_Saltado_-_Lima%2C_Peru_Miraflores_%28Tiendecita_Blanca%29.jpg/960px-Lomo_Saltado_-_Lima%2C_Peru_Miraflores_%28Tiendecita_Blanca%29.jpg","tags":["Stir-fry"],"yt":"","src":"","ingr":[{"n":"Sirloin Steak","m":"500g"},{"n":"Red Onions","m":"1"},{"n":"Tomatoes","m":"3"},{"n":"Soy Sauce","m":"3 tbs"},{"n":"Red Wine Vinegar","m":"1 tbs"},{"n":"Garlic","m":"2 cloves"},{"n":"Fries","m":"500g"},{"n":"Rice","m":"300g"},{"n":"Coriander","m":"1 handful"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Lomo_Saltado_-_Lima,_Peru_Miraflores_(Tiendecita_Blanca).jpg","artist":"Chasqui (Luis Tamayo)","license":"CC BY-SA 2.0"}},{"id":"qm-cuban-picadillo","name":"Cuban picadillo","cat":"Beef","country":"Cuba","instr":"Fry the onion, pepper and garlic for 5 minutes, add the beef and brown for 6 minutes.\r\nAdd the cumin, passata, sliced olives and raisins and simmer for 15 minutes.\r\nServe with rice and warm black beans.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Picadillo_and_rice.jpg/960px-Picadillo_and_rice.jpg","tags":["Family"],"yt":"","src":"","ingr":[{"n":"Minced Beef","m":"500g"},{"n":"Onion","m":"1"},{"n":"Green Pepper","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Passata","m":"300ml"},{"n":"Ground Cumin","m":"1 tsp"},{"n":"Pimento Stuffed Olives","m":"60g"},{"n":"Raisins","m":"40g"},{"n":"Rice","m":"300g"},{"n":"Black Beans","m":"400g"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Picadillo_and_rice.jpg","artist":"Cary Bass","license":"CC BY-SA 3.0"}},{"id":"qm-black-bean-tacos","name":"Black bean tacos","cat":"Vegetarian","country":"Mexico","instr":"Fry half the onion for 4 minutes, add the drained beans and spices and cook for 5 minutes, crushing some of the beans.\r\nMash the avocado with lime juice and salt.\r\nWarm the tortillas and fill with beans, avocado, crumbled feta, the rest of the onion and coriander.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/001_Tacos_de_carnitas%2C_carne_asada_y_al_pastor.jpg/960px-001_Tacos_de_carnitas%2C_carne_asada_y_al_pastor.jpg","tags":["Quick","Tacos","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Black Beans","m":"800g"},{"n":"Corn Tortillas","m":"12"},{"n":"Red Onions","m":"1"},{"n":"Ground Cumin","m":"1 tsp"},{"n":"Smoked Paprika","m":"1 tsp"},{"n":"Avocado","m":"2"},{"n":"Feta","m":"100g"},{"n":"Lime","m":"2"},{"n":"Coriander","m":"1 handful"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:001_Tacos_de_carnitas,_carne_asada_y_al_pastor.jpg","artist":"Larry Miller","license":"CC BY-SA 2.0"}},{"id":"qm-huevos-rancheros","name":"Huevos rancheros","cat":"Vegetarian","country":"Mexico","instr":"Simmer the onion, garlic, jalapeño and tomatoes for 10 minutes to make a salsa.\r\nWarm the refried beans and toast the tortillas in a dry pan.\r\nFry the eggs.\r\nSpread beans on the tortillas, add the eggs and spoon over the salsa. Top with avocado and coriander.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Mmm...huevos_rancheros.jpg/960px-Mmm...huevos_rancheros.jpg","tags":["Eggs","Quick","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Eggs","m":"8"},{"n":"Corn Tortillas","m":"8"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"1 clove"},{"n":"Jalapeno","m":"1"},{"n":"Refried Beans","m":"400g"},{"n":"Avocado","m":"1"},{"n":"Coriander","m":"1 handful"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Mmm...huevos_rancheros.jpg","artist":"jeffreyw","license":"CC BY 2.0"}},{"id":"qm-classic-cheeseburger","name":"Classic cheeseburger","cat":"Beef","country":"United States","instr":"Cook the fries in the oven following the packet.\r\nShape the beef into 4 patties slightly wider than the buns. Season well.\r\nCook in a very hot pan for 3 minutes, flip, add the cheese and cook for 2 minutes more.\r\nToast the buns and build the burgers with ketchup, mustard, lettuce, tomato, onion and pickles.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Cheeseburger.jpg/960px-Cheeseburger.jpg","tags":["Burger","Family"],"yt":"","src":"","ingr":[{"n":"Minced Beef","m":"600g"},{"n":"Sesame Seed Burger Buns","m":"4"},{"n":"Cheddar Cheese","m":"4 slices"},{"n":"Lettuce","m":"4 leaves"},{"n":"Tomatoes","m":"1"},{"n":"Red Onions","m":"1"},{"n":"Dill Pickles","m":"2"},{"n":"Tomato Ketchup","m":"4 tbs"},{"n":"Mustard","m":"2 tbs"},{"n":"Fries","m":"600g"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Cheeseburger.jpg","artist":"Renee Comet (photographer)","license":"Public domain"}},{"id":"qm-baked-mac-and-cheese","name":"Baked mac and cheese","cat":"Vegetarian","country":"United States","instr":"Cook the pasta for 2 minutes less than the packet says.\r\nMake a sauce with the butter, flour and milk, simmer for 5 minutes, then stir in the mustard and most of the cheese.\r\nHeat the oven to 200C. Mix the pasta with the sauce, tip into a dish and top with the remaining cheese and breadcrumbs.\r\nBake for 20 minutes. Serve with rocket.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Original_Mac_n_Cheese_.jpg/960px-Original_Mac_n_Cheese_.jpg","tags":["Bake","Family","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Macaroni","m":"400g"},{"n":"Butter","m":"50g"},{"n":"Plain Flour","m":"40g"},{"n":"Milk","m":"700ml"},{"n":"Mature Cheddar","m":"250g"},{"n":"Mustard Powder","m":"1 tsp"},{"n":"Breadcrumbs","m":"40g"},{"n":"Rocket","m":"100g"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Original_Mac_n_Cheese_.jpg","artist":"Texasfoodgawker","license":"CC BY-SA 4.0"}},{"id":"qm-pulled-pork-buns-with-slaw","name":"Pulled pork buns with slaw","cat":"Pork","country":"United States","instr":"Rub the pork with the paprika, sugar, garlic powder and salt.\r\nPut in a covered casserole with 200ml water and the vinegar and cook at 150C for 3 hours 30 minutes.\r\nShred the meat and mix with the barbecue sauce and some of the juices.\r\nMix the shredded cabbage and grated carrots with the mayonnaise. Fill the rolls with pork and slaw.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/Pulled_pork_while_pulling.JPG/960px-Pulled_pork_while_pulling.JPG","tags":["Burger","Barbecue"],"yt":"","src":"","ingr":[{"n":"Pork Shoulder","m":"1.5kg"},{"n":"Smoked Paprika","m":"2 tbs"},{"n":"Brown Sugar","m":"2 tbs"},{"n":"Garlic Powder","m":"1 tsp"},{"n":"Barbeque Sauce","m":"200ml"},{"n":"Apple Cider Vinegar","m":"3 tbs"},{"n":"Bread Rolls","m":"6"},{"n":"White Cabbage","m":"1/4"},{"n":"Carrots","m":"2"},{"n":"Mayonnaise","m":"4 tbs"}],"time":240,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pulled_pork_while_pulling.JPG","artist":"Thogru","license":"CC BY-SA 3.0"}},{"id":"qm-chicken-pot-pie","name":"Chicken pot pie","cat":"Chicken","country":"United States","instr":"Cook the diced chicken, carrots, celery and onion in the butter for 10 minutes.\r\nStir in the flour, then the stock and milk and simmer for 5 minutes. Add the peas and season.\r\nHeat the oven to 200C. Pour into a pie dish, cover with the pastry and brush with egg.\r\nBake for 25 minutes until golden.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/ChickenpotpieswholeFeb09.jpg/960px-ChickenpotpieswholeFeb09.jpg","tags":["Pie","Family"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"3"},{"n":"Carrots","m":"2"},{"n":"Celery","m":"2 sticks"},{"n":"Onion","m":"1"},{"n":"Frozen Peas","m":"150g"},{"n":"Butter","m":"40g"},{"n":"Plain Flour","m":"40g"},{"n":"Chicken Stock","m":"400ml"},{"n":"Milk","m":"150ml"},{"n":"Puff Pastry","m":"1 sheet"},{"n":"Egg","m":"1"}],"time":60,"photo":{"page":"https://commons.wikimedia.org/wiki/File:ChickenpotpieswholeFeb09.jpg","artist":"avlxyz at https://www.flickr.com/photos/avlxyz/","license":"CC BY-SA 2.0"}},{"id":"qm-jambalaya","name":"Jambalaya","cat":"Chicken","country":"United States","instr":"Brown the diced chicken and sliced chorizo for 6 minutes.\r\nAdd the onion, pepper and celery and cook for 5 minutes, then the Cajun spice.\r\nAdd the rice, tomatoes and stock, cover and simmer for 20 minutes.\r\nAdd the prawns, cover and cook for 5 minutes more.","thumb":"https://upload.wikimedia.org/wikipedia/commons/e/e0/Homemade_Jambalaya.JPG","tags":["Rice","Spicy"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"4"},{"n":"Chorizo","m":"150g"},{"n":"King Prawns","m":"200g"},{"n":"Onion","m":"1"},{"n":"Green Pepper","m":"1"},{"n":"Celery","m":"2 sticks"},{"n":"Cajun","m":"2 tsp"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Rice","m":"300g"},{"n":"Chicken Stock","m":"700ml"}],"time":50,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Homemade_Jambalaya.JPG","artist":"Amadscientist","license":"CC BY-SA 3.0"}},{"id":"qm-chicken-caesar-salad","name":"Chicken Caesar salad","cat":"Chicken","country":"United States","instr":"Pan-fry the seasoned chicken for 6 minutes on each side and slice.\r\nCut the bread into cubes and toast in a pan with olive oil until golden.\r\nBlend the mayonnaise, lemon juice, garlic, anchovies, Worcestershire sauce and half the parmesan.\r\nToss the lettuce with the dressing and top with chicken, croutons and parmesan shavings.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/Caesar_salad_%282%29.jpg/960px-Caesar_salad_%282%29.jpg","tags":["Salad","Quick"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"3"},{"n":"Little Gem Lettuce","m":"3"},{"n":"Parmesan","m":"60g"},{"n":"Bread","m":"3 slices"},{"n":"Mayonnaise","m":"4 tbs"},{"n":"Lemon","m":"1"},{"n":"Garlic","m":"1 clove"},{"n":"Anchovy Fillet","m":"2"},{"n":"Worcestershire Sauce","m":"1 tsp"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Caesar_salad_(2).jpg","artist":"Geoff Peters from Vancouver, BC, Canada","license":"CC BY 2.0"}},{"id":"qm-philly-cheesesteak","name":"Philly cheesesteak","cat":"Beef","country":"United States","instr":"Freeze the steak for 20 minutes, then slice it very thinly.\r\nCook the sliced onions and pepper in the butter for 10 minutes.\r\nFry the steak in a very hot pan for 2 minutes, mix with the onions and cover with the cheese until melted.\r\nPile into the toasted rolls.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/PatsCheesesteak.jpg/960px-PatsCheesesteak.jpg","tags":["Sandwich","Quick"],"yt":"","src":"","ingr":[{"n":"Sirloin Steak","m":"500g"},{"n":"Onions","m":"2"},{"n":"Green Pepper","m":"1"},{"n":"Swiss Cheese","m":"8 slices"},{"n":"Bread Rolls","m":"4"},{"n":"Butter","m":"20g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:PatsCheesesteak.jpg","artist":"","license":"CC BY-SA 3.0"}},{"id":"qm-cajun-chicken-pasta","name":"Cajun chicken pasta","cat":"Chicken","country":"United States","instr":"Cook the pasta.\r\nToss the sliced chicken in the Cajun spice and fry for 7 minutes.\r\nAdd the pepper and garlic and cook for 3 minutes, then the cream and parmesan for 2 minutes.\r\nToss with the pasta and spring onions.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Gfp-chicken-mushroom-pasta.jpg/960px-Gfp-chicken-mushroom-pasta.jpg","tags":["Quick","Pasta"],"yt":"","src":"","ingr":[{"n":"Penne Rigate","m":"400g"},{"n":"Chicken Breasts","m":"3"},{"n":"Cajun","m":"2 tbs"},{"n":"Red Pepper","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Double Cream","m":"200ml"},{"n":"Parmesan","m":"50g"},{"n":"Spring Onions","m":"2"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Gfp-chicken-mushroom-pasta.jpg","artist":"Yinan Chen","license":"Public Domain"}},{"id":"qm-chicken-noodle-soup","name":"Chicken noodle soup","cat":"Chicken","country":"United States","instr":"Simmer the chicken in the stock with the thyme for 20 minutes. Lift out and shred.\r\nAdd the diced carrots, celery and onion and simmer for 10 minutes.\r\nAdd the noodles and cook for 5 minutes, then return the chicken and add the parsley.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Chicken_Noodle_Soup.jpg/960px-Chicken_Noodle_Soup.jpg","tags":["Soup","Family"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"4"},{"n":"Carrots","m":"2"},{"n":"Celery","m":"2 sticks"},{"n":"Onion","m":"1"},{"n":"Chicken Stock","m":"1.5 litres"},{"n":"Egg Noodles","m":"200g"},{"n":"Thyme","m":"2 sprigs"},{"n":"Parsley","m":"2 tbs chopped"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Chicken_Noodle_Soup.jpg","artist":"Hoyabird8","license":"CC BY-SA 3.0"}},{"id":"qm-fish-and-chips","name":"Fish and chips","cat":"Seafood","country":"United Kingdom","instr":"Cut the potatoes into thick chips and fry at 160C for 7 minutes. Drain.\r\nWhisk the flour, baking powder, a pinch of salt and the cold beer into a batter.\r\nDust the fish with flour, dip in the batter and fry at 180C for 6 minutes until golden.\r\nFry the chips again at 180C for 3 minutes. Cook the peas.\r\nServe with lemon and mayonnaise.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Fish_and_chips_blackpool.jpg/960px-Fish_and_chips_blackpool.jpg","tags":["Fried","Classic"],"yt":"","src":"","ingr":[{"n":"Cod","m":"4 fillets"},{"n":"Plain Flour","m":"200g"},{"n":"Beer","m":"300ml"},{"n":"Baking Powder","m":"1 tsp"},{"n":"Floury Potatoes","m":"1kg"},{"n":"Sunflower Oil","m":"For frying"},{"n":"Frozen Peas","m":"300g"},{"n":"Lemon","m":"1"},{"n":"Mayonnaise","m":"4 tbs"}],"time":45,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Fish_and_chips_blackpool.jpg","artist":"Matthias Meckel","license":"CC BY-SA 4.0"}},{"id":"qm-cottage-pie","name":"Cottage pie","cat":"Beef","country":"United Kingdom","instr":"Fry the onion and carrots for 5 minutes, add the beef and brown for 6 minutes.\r\nStir in the flour, tomato purée and Worcestershire sauce, then the stock. Simmer for 20 minutes.\r\nBoil the potatoes for 20 minutes and mash with the butter and milk.\r\nHeat the oven to 200C. Top the meat with the mash and cheese and bake for 25 minutes.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Homerton_College_-_Shepherd%27s_pie_%28cropped%29.jpg/960px-Homerton_College_-_Shepherd%27s_pie_%28cropped%29.jpg","tags":["Bake","Family"],"yt":"","src":"","ingr":[{"n":"Minced Beef","m":"500g"},{"n":"Onion","m":"1"},{"n":"Carrots","m":"2"},{"n":"Tomato Puree","m":"1 tbs"},{"n":"Worcestershire Sauce","m":"2 tbs"},{"n":"Beef Stock","m":"300ml"},{"n":"Plain Flour","m":"1 tbs"},{"n":"Floury Potatoes","m":"1kg"},{"n":"Butter","m":"40g"},{"n":"Milk","m":"150ml"},{"n":"Cheddar Cheese","m":"60g"}],"time":70,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Homerton_College_-_Shepherd%27s_pie_(cropped).jpg","artist":"Oxfordian Kissuth","license":"CC BY-SA 3.0"}},{"id":"qm-smoked-haddock-kedgeree-style-rice","name":"Smoked haddock kedgeree-style rice","cat":"Seafood","country":"United Kingdom","instr":"Poach the haddock in water for 8 minutes, then flake it. Boil the eggs for 8 minutes and quarter them.\r\nSoften the onion in the butter for 5 minutes, add the curry powder, then the rice and 600ml of the poaching water. Cover and cook for 12 minutes.\r\nAdd the peas for the last 3 minutes. Fold in the fish, eggs and parsley and serve with lemon.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Kedgeree.jpg/960px-Kedgeree.jpg","tags":["Rice","Fish"],"yt":"","src":"","ingr":[{"n":"Smoked Haddock","m":"400g"},{"n":"Basmati Rice","m":"300g"},{"n":"Eggs","m":"4"},{"n":"Onion","m":"1"},{"n":"Curry Powder","m":"2 tsp"},{"n":"Butter","m":"30g"},{"n":"Frozen Peas","m":"150g"},{"n":"Parsley","m":"3 tbs chopped"},{"n":"Lemon","m":"1"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Kedgeree.jpg","artist":"User:Justinc","license":"CC BY-SA 2.0"}},{"id":"qm-toad-in-the-hole-with-onion-gravy","name":"Toad in the hole with onion gravy","cat":"Pork","country":"United Kingdom","instr":"Heat the oven to 220C. Put the sausages and oil in a roasting tin and cook for 10 minutes.\r\nWhisk the flour, eggs and milk into a smooth batter.\r\nPour the batter around the sausages and bake for 25 minutes without opening the oven.\r\nMeanwhile soften the onions for 10 minutes, add the stock and simmer for 10 minutes. Serve with the peas.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Toad_in_the_hole.jpg/960px-Toad_in_the_hole.jpg","tags":["Bake","Family"],"yt":"","src":"","ingr":[{"n":"Sausages","m":"8"},{"n":"Plain Flour","m":"140g"},{"n":"Eggs","m":"3"},{"n":"Milk","m":"200ml"},{"n":"Sunflower Oil","m":"3 tbs"},{"n":"Onions","m":"2"},{"n":"Beef Stock","m":"300ml"},{"n":"Frozen Peas","m":"300g"}],"time":50,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Toad_in_the_hole.jpg","artist":"Robert Gibert","license":"Public domain"}},{"id":"qm-lamb-shepherd-s-pie","name":"Lamb shepherd's pie","cat":"Lamb","country":"United Kingdom","instr":"Brown the lamb with the onion and carrots for 8 minutes.\r\nAdd the thyme, tomato purée and stock and simmer for 20 minutes.\r\nBoil the potatoes for 20 minutes and mash with the butter and milk.\r\nHeat the oven to 200C. Spread the lamb in a dish, cover with the mash and bake for 25 minutes. Serve with peas.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Homerton_College_-_Shepherd%27s_pie_%28cropped%29.jpg/960px-Homerton_College_-_Shepherd%27s_pie_%28cropped%29.jpg","tags":["Bake"],"yt":"","src":"","ingr":[{"n":"Lamb Mince","m":"500g"},{"n":"Onion","m":"1"},{"n":"Carrots","m":"2"},{"n":"Thyme","m":"1 tsp"},{"n":"Tomato Puree","m":"1 tbs"},{"n":"Lamb Stock","m":"300ml"},{"n":"Floury Potatoes","m":"1kg"},{"n":"Butter","m":"40g"},{"n":"Milk","m":"150ml"},{"n":"Frozen Peas","m":"200g"}],"time":70,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Homerton_College_-_Shepherd%27s_pie_(cropped).jpg","artist":"Oxfordian Kissuth","license":"CC BY-SA 3.0"}},{"id":"qm-tuna-melt","name":"Tuna melt","cat":"Seafood","country":"United States","instr":"Mix the tuna with the mayonnaise, finely chopped onion and celery.\r\nButter the bread on the outside, fill with the tuna, tomato slices and cheese.\r\nCook in a frying pan over medium heat for 3 minutes on each side until golden and the cheese melts.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Tuna_melt_sandwich_with_fries.jpg/960px-Tuna_melt_sandwich_with_fries.jpg","tags":["Quick","Sandwich"],"yt":"","src":"","ingr":[{"n":"Tuna","m":"300g"},{"n":"Mayonnaise","m":"4 tbs"},{"n":"Red Onions","m":"1/2"},{"n":"Celery","m":"1 stick"},{"n":"Wholegrain Bread","m":"8 slices"},{"n":"Cheddar Cheese","m":"150g"},{"n":"Butter","m":"30g"},{"n":"Tomatoes","m":"2"}],"time":15,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Tuna_melt_sandwich_with_fries.jpg","artist":"kweez mcG from London, UK","license":"CC BY 2.0"}},{"id":"qm-black-bean-burgers","name":"Black bean burgers","cat":"Vegetarian","country":"United States","instr":"Mash the drained beans roughly, then mix with the breadcrumbs, egg, half the onion chopped and the spices. Shape into 4 patties.\r\nFry in a little oil for 4 minutes on each side, adding the cheese at the end.\r\nBuild the burgers with lettuce, tomato and the rest of the onion.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/%D7%94%D7%9E%D7%91%D7%95%D7%A8%D7%92%D7%A8_%D7%98%D7%91%D7%A2%D7%95%D7%A0%D7%99.jpg/960px-%D7%94%D7%9E%D7%91%D7%95%D7%A8%D7%92%D7%A8_%D7%98%D7%91%D7%A2%D7%95%D7%A0%D7%99.jpg","tags":["Burger","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Black Beans","m":"800g"},{"n":"Breadcrumbs","m":"80g"},{"n":"Egg","m":"1"},{"n":"Red Onions","m":"1"},{"n":"Ground Cumin","m":"1 tsp"},{"n":"Smoked Paprika","m":"1 tsp"},{"n":"Sesame Seed Burger Buns","m":"4"},{"n":"Cheddar Cheese","m":"4 slices"},{"n":"Lettuce","m":"4 leaves"},{"n":"Tomatoes","m":"1"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:%D7%94%D7%9E%D7%91%D7%95%D7%A8%D7%92%D7%A8_%D7%98%D7%91%D7%A2%D7%95%D7%A0%D7%99.jpg","artist":"Roee Shpernik","license":"CC BY-SA 4.0"}},{"id":"qm-sweet-potato-and-black-bean-chilli","name":"Sweet potato and black bean chilli","cat":"Vegan","country":"Mexico","instr":"Fry the onion, pepper and garlic for 5 minutes, add the spices.\r\nAdd the sweet potato in cubes, the tomatoes and 200ml water and simmer for 20 minutes.\r\nAdd the beans and cook for 10 minutes. Serve with rice and lime.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Bowl_of_chili.jpg/960px-Bowl_of_chili.jpg","tags":["Stew","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Sweet Potatoes","m":"2"},{"n":"Black Beans","m":"800g"},{"n":"Onion","m":"1"},{"n":"Red Pepper","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Chilli Powder","m":"2 tsp"},{"n":"Ground Cumin","m":"2 tsp"},{"n":"Chopped Tomatoes","m":"800g"},{"n":"Rice","m":"300g"},{"n":"Lime","m":"1"}],"time":45,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Bowl_of_chili.jpg","artist":"Carstor","license":"CC BY-SA 2.5"}},{"id":"qm-brazilian-black-bean-and-sausage-stew","name":"Brazilian black bean and sausage stew","cat":"Pork","country":"Brazil","instr":"Fry the bacon and sliced sausages for 6 minutes. Add the onion and garlic for 4 minutes.\r\nAdd the beans with their liquid, the bay leaves and 300ml water and simmer for 25 minutes.\r\nCook the rice. Stir-fry the shredded kale with a little garlic for 3 minutes.\r\nServe the beans with rice, kale and orange slices.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Fabada_en_cazuela_de_barro.jpg/960px-Fabada_en_cazuela_de_barro.jpg","tags":["Stew"],"yt":"","src":"","ingr":[{"n":"Black Beans","m":"800g"},{"n":"Sausages","m":"4"},{"n":"Bacon","m":"150g"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"3 cloves"},{"n":"Bay Leaves","m":"2"},{"n":"Rice","m":"300g"},{"n":"Orange","m":"1"},{"n":"Kale","m":"200g"}],"time":50,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Fabada_en_cazuela_de_barro.jpg","artist":"Juan J. Martínez from Valencia, España","license":"CC BY-SA 2.0"}},{"id":"qm-cheese-and-ham-omelette-with-salad","name":"Cheese and ham omelette with salad","cat":"Pork","country":"France","instr":"Beat the eggs with salt and pepper.\r\nMelt a little butter in a frying pan, pour in a quarter of the eggs and stir gently for 1 minute.\r\nAdd some diced ham and cheese, fold and slide onto a plate. Repeat.\r\nServe with the dressed salad and bread.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Gorgonzola_%2B_Bacon_Omelette_%40_Omelegg_%40_Amsterdam_%2816600947041%29.jpg/960px-Gorgonzola_%2B_Bacon_Omelette_%40_Omelegg_%40_Amsterdam_%2816600947041%29.jpg","tags":["Quick","Eggs"],"yt":"","src":"","ingr":[{"n":"Eggs","m":"10"},{"n":"Ham","m":"150g"},{"n":"Gruyère","m":"80g"},{"n":"Butter","m":"20g"},{"n":"Lettuce","m":"1"},{"n":"Vinaigrette Dressing","m":"3 tbs"},{"n":"Crusty Bread","m":"1"}],"time":15,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Gorgonzola_%2B_Bacon_Omelette_@_Omelegg_@_Amsterdam_(16600947041).jpg","artist":"Guilhem Vellut from Annecy, France","license":"CC BY 2.0"}},{"id":"qm-pasta-with-creamy-mushrooms","name":"Pasta with creamy mushrooms","cat":"Vegetarian","country":"Italy","instr":"Cook the pasta.\r\nFry the sliced mushrooms in the butter over high heat for 6 minutes, add the garlic for 1 minute.\r\nStir in the crème fraîche and parmesan and simmer for 2 minutes.\r\nToss with the pasta and parsley.","thumb":"https://upload.wikimedia.org/wikipedia/commons/e/e4/Creamy_Mushroom_Pasta.jpg","tags":["Quick","Pasta","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Tagliatelle","m":"400g"},{"n":"Mushrooms","m":"400g"},{"n":"Garlic","m":"2 cloves"},{"n":"Creme Fraiche","m":"200ml"},{"n":"Parmesan","m":"50g"},{"n":"Parsley","m":"2 tbs chopped"},{"n":"Butter","m":"20g"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Creamy_Mushroom_Pasta.jpg","artist":"Sharon Chen","license":"CC BY 3.0"}},{"id":"qm-halloumi-fajitas","name":"Halloumi fajitas","cat":"Vegetarian","country":"Mexico","instr":"Slice the halloumi, peppers and onion and toss with the seasoning and a little oil.\r\nCook in a hot pan for 8 minutes until charred.\r\nServe in warm tortillas with yogurt, sliced avocado and lime.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/55/Vegetable_Fajitas_%284188499456%29.jpg/960px-Vegetable_Fajitas_%284188499456%29.jpg","tags":["Quick","Wrap","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Halloumi","m":"250g"},{"n":"Red Pepper","m":"1"},{"n":"Yellow Pepper","m":"1"},{"n":"Red Onions","m":"1"},{"n":"Fajita Seasoning","m":"2 tsp"},{"n":"Flour Tortilla","m":"8"},{"n":"Greek Yogurt","m":"150g"},{"n":"Lime","m":"1"},{"n":"Avocado","m":"1"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Vegetable_Fajitas_(4188499456).jpg","artist":"Jennifer from Vancouver, Canada","license":"CC BY 2.0"}},{"id":"qm-chickpea-and-spinach-curry","name":"Chickpea and spinach curry","cat":"Vegan","country":"India","instr":"Fry the onion and garlic for 5 minutes, add the curry powder for 1 minute.\r\nAdd the tomatoes, coconut milk and chickpeas and simmer for 12 minutes.\r\nStir in the spinach until wilted. Serve with rice.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Chickpea_Curry.jpg/960px-Chickpea_Curry.jpg","tags":["Quick","Curry","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Chickpeas","m":"800g"},{"n":"Coconut Milk","m":"400ml"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Curry Powder","m":"2 tbs"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Spinach","m":"200g"},{"n":"Basmati Rice","m":"300g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Chickpea_Curry.jpg","artist":"Gaurav Dhwaj Khadka","license":"CC BY-SA 4.0"}},{"id":"qm-lentil-bolognese","name":"Lentil bolognese","cat":"Vegan","country":"Italy","instr":"Soften the chopped onion, carrot, celery and garlic in olive oil for 8 minutes.\r\nAdd the lentils, tomatoes, tomato purée, oregano and 400ml water. Simmer for 30 minutes until thick.\r\nServe with the spaghetti.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Tagliatelle_al_rag%C3%B9_%28image_modified%29.jpg/960px-Tagliatelle_al_rag%C3%B9_%28image_modified%29.jpg","tags":["Pasta","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Brown Lentils","m":"250g"},{"n":"Onion","m":"1"},{"n":"Carrots","m":"2"},{"n":"Celery","m":"1 stick"},{"n":"Garlic","m":"2 cloves"},{"n":"Chopped Tomatoes","m":"800g"},{"n":"Tomato Puree","m":"2 tbs"},{"n":"Dried Oregano","m":"1 tsp"},{"n":"Spaghetti","m":"400g"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Tagliatelle_al_rag%C3%B9_(image_modified).jpg","artist":"Ivan Vighetto","license":"CC BY-SA 3.0"}},{"id":"qm-mushroom-stroganoff","name":"Mushroom stroganoff","cat":"Vegetarian","country":"Russia","instr":"Cook the rice.\r\nFry the onion for 5 minutes, add the thickly sliced mushrooms and cook over high heat for 8 minutes.\r\nAdd the garlic and paprika, then the sour cream and mustard and warm through.\r\nServe with rice and parsley.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Beef_Stroganoff_z_boczniaka_%28Poznan%29.jpg/960px-Beef_Stroganoff_z_boczniaka_%28Poznan%29.jpg","tags":["Quick","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Mushrooms","m":"600g"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"2 cloves"},{"n":"Paprika","m":"2 tsp"},{"n":"Sour Cream","m":"200ml"},{"n":"Dijon Mustard","m":"1 tsp"},{"n":"Rice","m":"300g"},{"n":"Parsley","m":"2 tbs chopped"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Beef_Stroganoff_z_boczniaka_(Poznan).jpg","artist":"MOs810","license":"CC BY-SA 4.0"}},{"id":"qm-vegetable-fried-rice-with-tofu","name":"Vegetable fried rice with tofu","cat":"Vegan","country":"China","instr":"Fry the tofu cubes in a hot wok for 6 minutes. Set aside.\r\nStir-fry the diced carrots, garlic and peas for 3 minutes.\r\nAdd the rice and stir-fry for 4 minutes, then the tofu, soy sauce, sesame oil and spring onions.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Koh_Mak%2C_Thailand%2C_Fried_rice_with_seafood%2C_Thai_fried_rice.jpg/960px-Koh_Mak%2C_Thailand%2C_Fried_rice_with_seafood%2C_Thai_fried_rice.jpg","tags":["Quick","Rice"],"yt":"","src":"","ingr":[{"n":"Rice","m":"300g"},{"n":"Tofu","m":"300g"},{"n":"Carrots","m":"2"},{"n":"Frozen Peas","m":"150g"},{"n":"Spring Onions","m":"4"},{"n":"Soy Sauce","m":"4 tbs"},{"n":"Sesame Seed Oil","m":"1 tbs"},{"n":"Garlic","m":"2 cloves"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Koh_Mak,_Thailand,_Fried_rice_with_seafood,_Thai_fried_rice.jpg","artist":"Vyacheslav Argenberg","license":"CC BY 4.0"}},{"id":"qm-spinach-and-feta-omelette","name":"Spinach and feta omelette","cat":"Vegetarian","country":"Greece","instr":"Wilt the spinach in a pan for 2 minutes and squeeze dry.\r\nBeat the eggs and cook a quarter at a time in a little butter, stirring gently.\r\nAdd some spinach and feta, fold and serve with tomatoes and bread.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Gorgonzola_%2B_Bacon_Omelette_%40_Omelegg_%40_Amsterdam_%2816600947041%29.jpg/960px-Gorgonzola_%2B_Bacon_Omelette_%40_Omelegg_%40_Amsterdam_%2816600947041%29.jpg","tags":["Quick","Eggs","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Eggs","m":"10"},{"n":"Spinach","m":"150g"},{"n":"Feta","m":"120g"},{"n":"Butter","m":"20g"},{"n":"Cherry Tomatoes","m":"200g"},{"n":"Crusty Bread","m":"1"}],"time":15,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Gorgonzola_%2B_Bacon_Omelette_@_Omelegg_@_Amsterdam_(16600947041).jpg","artist":"Guilhem Vellut from Annecy, France","license":"CC BY 2.0"}},{"id":"qm-bean-and-cheese-quesadillas","name":"Bean and cheese quesadillas","cat":"Vegetarian","country":"Mexico","instr":"Spread the beans on 4 tortillas, top with cheese, corn and spring onions and cover with the other tortillas.\r\nCook in a dry pan for 3 minutes on each side.\r\nCut into wedges and serve with salsa and sour cream.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Quesadilla_plate%2C_New_Orleans_November_2016.jpg/960px-Quesadilla_plate%2C_New_Orleans_November_2016.jpg","tags":["Quick","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Flour Tortilla","m":"8"},{"n":"Refried Beans","m":"400g"},{"n":"Cheddar Cheese","m":"200g"},{"n":"Sweetcorn","m":"150g"},{"n":"Spring Onions","m":"3"},{"n":"Salsa","m":"150g"},{"n":"Sour Cream","m":"100ml"}],"time":15,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Quesadilla_plate,_New_Orleans_November_2016.jpg","artist":"pelican from Tokyo, Japan","license":"CC BY-SA 2.0"}},{"id":"qm-quinoa-bowl-with-roasted-sweet-potato","name":"Quinoa bowl with roasted sweet potato","cat":"Vegan","country":"United States","instr":"Roast the sweet potatoes in cubes and the chickpeas with oil and paprika at 220C for 25 minutes.\r\nCook the quinoa in boiling water for 12 minutes and drain.\r\nMix the tahini with lemon juice and water to a pouring sauce.\r\nFill bowls with quinoa, rocket, sweet potato, chickpeas and sliced avocado and drizzle with the sauce.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/Vegan_Quinoa_Bowl_%2844040185371%29.jpg/960px-Vegan_Quinoa_Bowl_%2844040185371%29.jpg","tags":["Bowl","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Quinoa","m":"250g"},{"n":"Sweet Potatoes","m":"2"},{"n":"Chickpeas","m":"400g"},{"n":"Smoked Paprika","m":"1 tsp"},{"n":"Avocado","m":"2"},{"n":"Rocket","m":"100g"},{"n":"Tahini","m":"3 tbs"},{"n":"Lemon","m":"1"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Vegan_Quinoa_Bowl_(44040185371).jpg","artist":"Ella Olsson from Stockholm, Sweden","license":"CC BY 2.0"}},{"id":"qm-tomato-and-mozzarella-gnocchi-bake","name":"Tomato and mozzarella gnocchi bake","cat":"Vegetarian","country":"Italy","instr":"Heat the grill. Fry the gnocchi in a little oil for 5 minutes until golden.\r\nAdd the garlic and tomatoes and simmer for 5 minutes. Stir in the basil.\r\nTop with torn mozzarella and grill for 5 minutes. Serve with rocket.","thumb":"https://upload.wikimedia.org/wikipedia/commons/8/86/Gnocchi_di_ricotta_burro_e_salvia.jpg","tags":["Quick","Bake","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Gnocchi","m":"800g"},{"n":"Chopped Tomatoes","m":"400g"},{"n":"Garlic","m":"1 clove"},{"n":"Mozzarella","m":"250g"},{"n":"Basil","m":"1 handful"},{"n":"Rocket","m":"100g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Gnocchi_di_ricotta_burro_e_salvia.jpg","artist":"Paoletta S.","license":"CC BY 2.0"}},{"id":"qm-chicken-and-rice-soup-with-lemon","name":"Chicken and rice soup with lemon","cat":"Chicken","country":"France","instr":"Simmer the chicken in the stock for 15 minutes, lift out and shred.\r\nAdd the rice, diced carrots and sliced leek and simmer for 15 minutes.\r\nReturn the chicken, add lemon juice and parsley and season.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Chicken_Noodle_Soup.jpg/960px-Chicken_Noodle_Soup.jpg","tags":["Soup","Family"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"2"},{"n":"Chicken Stock","m":"1.5 litres"},{"n":"Rice","m":"120g"},{"n":"Carrots","m":"2"},{"n":"Leek","m":"1"},{"n":"Lemon","m":"1"},{"n":"Parsley","m":"2 tbs chopped"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Chicken_Noodle_Soup.jpg","artist":"Hoyabird8","license":"CC BY-SA 3.0"}},{"id":"qm-pan-fried-salmon-with-rice-and-green-beans","name":"Pan-fried salmon with rice and green beans","cat":"Seafood","country":"France","instr":"Cook the rice. Steam the green beans for 7 minutes.\r\nFry the salmon skin side down for 5 minutes, turn and cook for 2 minutes.\r\nAdd the butter, soy sauce, honey and lemon juice to the pan and spoon over the fish.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/Pan_fried_Salmon_spread.JPG/960px-Pan_fried_Salmon_spread.JPG","tags":["Quick","Fish"],"yt":"","src":"","ingr":[{"n":"Salmon","m":"4 fillets"},{"n":"Rice","m":"300g"},{"n":"Green Beans","m":"400g"},{"n":"Butter","m":"20g"},{"n":"Lemon","m":"1"},{"n":"Soy Sauce","m":"2 tbs"},{"n":"Honey","m":"1 tbs"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pan_fried_Salmon_spread.JPG","artist":"Debojyoti Saha","license":"CC BY-SA 4.0"}},{"id":"qm-chicken-and-potato-traybake","name":"Chicken and potato traybake","cat":"Chicken","country":"France","instr":"Heat the oven to 210C. Cut the potatoes into wedges and onions into quarters.\r\nToss everything with the oil, rosemary, unpeeled garlic, salt and pepper on a large tray, chicken skin side up.\r\nRoast for 45 minutes until the skin is crisp. Squeeze over the lemon and serve with salad.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Max%27s_Roasted_Chicken_-_Evan_Swigart.jpg/960px-Max%27s_Roasted_Chicken_-_Evan_Swigart.jpg","tags":["Roast","Family"],"yt":"","src":"","ingr":[{"n":"Chicken Thighs","m":"8"},{"n":"Potatoes","m":"1kg"},{"n":"Red Onions","m":"2"},{"n":"Garlic","m":"6 cloves"},{"n":"Rosemary","m":"3 sprigs"},{"n":"Olive Oil","m":"4 tbs"},{"n":"Lemon","m":"1"},{"n":"Lettuce","m":"1"}],"time":50,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Max%27s_Roasted_Chicken_-_Evan_Swigart.jpg","artist":"Evan Swigart from Chicago, USA","license":"CC BY 2.0"}},{"id":"qm-pork-chops-with-apples-and-mash","name":"Pork chops with apples and mash","cat":"Pork","country":"France","instr":"Boil the potatoes for 20 minutes and mash with half the butter and the milk.\r\nSeason the chops and fry in the rest of the butter for 5 minutes on each side. Set aside.\r\nFry the apple wedges and thyme in the pan for 4 minutes, add the cider and let it bubble for 2 minutes.\r\nReturn the chops to warm through and serve with the mash.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/Pork_chops_167541218.jpg/960px-Pork_chops_167541218.jpg","tags":["Family"],"yt":"","src":"","ingr":[{"n":"Pork Chops","m":"4"},{"n":"Apples","m":"2"},{"n":"Butter","m":"40g"},{"n":"Cider","m":"150ml"},{"n":"Floury Potatoes","m":"900g"},{"n":"Milk","m":"150ml"},{"n":"Thyme","m":"2 sprigs"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pork_chops_167541218.jpg","artist":"penny from Oakland, California, USA","license":"CC BY 2.0"}},{"id":"qm-breaded-chicken-with-rice-and-peas","name":"Breaded chicken with rice and peas","cat":"Chicken","country":"France","instr":"Cook the rice and the peas.\r\nFlatten the chicken breasts, coat in flour, beaten egg and breadcrumbs.\r\nFry in the oil for 4 minutes on each side until golden and cooked through.\r\nServe with rice, peas and lemon wedges.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Breitenlesau_Krug_Br%C3%A4u_Schnitzel.JPG/960px-Breitenlesau_Krug_Br%C3%A4u_Schnitzel.JPG","tags":["Family","Quick"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"4"},{"n":"Plain Flour","m":"50g"},{"n":"Eggs","m":"2"},{"n":"Breadcrumbs","m":"120g"},{"n":"Sunflower Oil","m":"5 tbs"},{"n":"Rice","m":"300g"},{"n":"Frozen Peas","m":"300g"},{"n":"Lemon","m":"1"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Breitenlesau_Krug_Br%C3%A4u_Schnitzel.JPG","artist":"Benreis","license":"CC BY-SA 3.0"}},{"id":"qm-beef-stir-fry-with-noodles","name":"Beef stir-fry with noodles","cat":"Beef","country":"China","instr":"Cook the noodles and drain.\r\nStir-fry the beef in a very hot wok for 2 minutes. Set aside.\r\nStir-fry the garlic, ginger, carrot and pak choi for 3 minutes.\r\nReturn the beef with the noodles and sauces and toss for 2 minutes.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Making_Stir-Fry_%283286445383%29.jpg/960px-Making_Stir-Fry_%283286445383%29.jpg","tags":["Quick","Noodles"],"yt":"","src":"","ingr":[{"n":"Egg Noodles","m":"300g"},{"n":"Beef","m":"400g"},{"n":"Carrots","m":"1"},{"n":"Pak Choi","m":"2"},{"n":"Soy Sauce","m":"3 tbs"},{"n":"Oyster Sauce","m":"2 tbs"},{"n":"Garlic","m":"2 cloves"},{"n":"Ginger","m":"1 tbs grated"}],"time":20,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Making_Stir-Fry_(3286445383).jpg","artist":"Mack Male from Edmonton, AB, Canada","license":"CC BY-SA 2.0"}},{"id":"qm-prawn-and-pea-risotto","name":"Prawn and pea risotto","cat":"Seafood","country":"Italy","instr":"Soften the onion in the butter for 4 minutes, add the rice and stir for 1 minute.\r\nAdd the wine, then the hot stock a ladle at a time, stirring, for 15 minutes.\r\nAdd the peas and prawns and cook for 4 minutes more. Finish with lemon zest.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Risotto_with_speck_and_goat_cheese_%286101067436%29.jpg/960px-Risotto_with_speck_and_goat_cheese_%286101067436%29.jpg","tags":["Rice"],"yt":"","src":"","ingr":[{"n":"Arborio Rice","m":"320g"},{"n":"King Prawns","m":"300g"},{"n":"Frozen Peas","m":"200g"},{"n":"Onion","m":"1"},{"n":"Fish Stock","m":"1.2 litres"},{"n":"Dry White Wine","m":"100ml"},{"n":"Butter","m":"30g"},{"n":"Lemon","m":"1"}],"time":35,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Risotto_with_speck_and_goat_cheese_(6101067436).jpg","artist":"Luca Nebuloni from Milan, Italy","license":"CC BY 2.0"}},{"id":"qm-baked-potatoes-with-tuna-and-sweetcorn","name":"Baked potatoes with tuna and sweetcorn","cat":"Seafood","country":"United Kingdom","instr":"Heat the oven to 200C. Prick the potatoes and bake for 1 hour until soft inside.\r\nMix the tuna with the sweetcorn and mayonnaise.\r\nSplit the potatoes, fill with the tuna mixture and top with grated cheese. Serve with salad.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/BakedPotatoWithButter.jpg/960px-BakedPotatoWithButter.jpg","tags":["Family"],"yt":"","src":"","ingr":[{"n":"Russet Potato","m":"4"},{"n":"Tuna","m":"300g"},{"n":"Sweetcorn","m":"200g"},{"n":"Mayonnaise","m":"4 tbs"},{"n":"Cheddar Cheese","m":"100g"},{"n":"Lettuce","m":"1"}],"time":70,"photo":{"page":"https://commons.wikimedia.org/wiki/File:BakedPotatoWithButter.jpg","artist":"Renee Comet (photographer)","license":"Public domain"}},{"id":"qm-pea-and-ham-soup","name":"Pea and ham soup","cat":"Pork","country":"United Kingdom","instr":"Soften the onion in the butter for 5 minutes.\r\nAdd the peas and stock and simmer for 8 minutes.\r\nBlend with the mint until smooth, then add the shredded ham.\r\nServe with a spoon of crème fraîche and bread.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Hernekeitto.jpg/960px-Hernekeitto.jpg","tags":["Quick","Soup"],"yt":"","src":"","ingr":[{"n":"Frozen Peas","m":"750g"},{"n":"Onion","m":"1"},{"n":"Butter","m":"20g"},{"n":"Vegetable Stock","m":"1 litre"},{"n":"Ham","m":"150g"},{"n":"Creme Fraiche","m":"4 tbs"},{"n":"Mint","m":"1 handful"},{"n":"Crusty Bread","m":"1"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Hernekeitto.jpg","artist":"User:Opalaisen","license":"CC BY-SA 4.0"}},{"id":"qm-creamy-pumpkin-soup","name":"Creamy pumpkin soup","cat":"Vegetarian","country":"France","instr":"Soften the onion in a little butter for 5 minutes.\r\nAdd the pumpkin and potatoes in cubes and the stock. Simmer for 25 minutes.\r\nBlend with the crème fraîche and nutmeg.\r\nServe with bread and grated cheese.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Pumpkin_Cream_Soup.jpg/960px-Pumpkin_Cream_Soup.jpg","tags":["Soup","Vegetarian"],"yt":"","src":"","ingr":[{"n":"Pumpkin","m":"1kg"},{"n":"Potatoes","m":"2"},{"n":"Onion","m":"1"},{"n":"Vegetable Stock","m":"1 litre"},{"n":"Creme Fraiche","m":"100ml"},{"n":"Nutmeg","m":"1 pinch"},{"n":"Crusty Bread","m":"1"},{"n":"Gruyère","m":"80g"}],"time":40,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Pumpkin_Cream_Soup.jpg","artist":"SoHome Jacaranda Lilau, So Home Recreation Club (蘇戶康樂會) / PropLuxurians Health S","license":"CC BY-SA 3.0"}},{"id":"qm-crispy-chicken-wraps","name":"Crispy chicken wraps","cat":"Chicken","country":"United States","instr":"Cut the chicken into strips, dip in beaten egg then in breadcrumbs mixed with paprika.\r\nBake at 220C for 15 minutes, turning once, or fry until golden.\r\nFill the warm tortillas with lettuce, tomato, cheese, mayonnaise and chicken and roll up.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f8/Smoked_chicken_and_avocado_wrap.jpg/960px-Smoked_chicken_and_avocado_wrap.jpg","tags":["Quick","Wrap"],"yt":"","src":"","ingr":[{"n":"Chicken Breasts","m":"3"},{"n":"Breadcrumbs","m":"100g"},{"n":"Eggs","m":"1"},{"n":"Paprika","m":"1 tsp"},{"n":"Flour Tortilla","m":"4"},{"n":"Lettuce","m":"1/2"},{"n":"Tomatoes","m":"2"},{"n":"Mayonnaise","m":"4 tbs"},{"n":"Cheddar Cheese","m":"80g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Smoked_chicken_and_avocado_wrap.jpg","artist":"Takeaway","license":"CC BY-SA 3.0"}},{"id":"qm-teriyaki-salmon-rice-bowl","name":"Teriyaki salmon rice bowl","cat":"Seafood","country":"Japan","instr":"Cook the rice and steam the broccoli florets for 5 minutes.\r\nFry the salmon for 4 minutes on each side.\r\nAdd the soy sauce, mirin and honey and let it bubble for 1 minute, spooning over the fish.\r\nServe on the rice with the broccoli, sesame seeds and spring onions.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Teriyaki_salmon.jpg/960px-Teriyaki_salmon.jpg","tags":["Quick","Bowl","Fish"],"yt":"","src":"","ingr":[{"n":"Salmon","m":"4 fillets"},{"n":"Soy Sauce","m":"4 tbs"},{"n":"Mirin","m":"3 tbs"},{"n":"Honey","m":"1 tbs"},{"n":"Sushi Rice","m":"300g"},{"n":"Broccoli","m":"1 head"},{"n":"Sesame Seed","m":"1 tbs"},{"n":"Spring Onions","m":"2"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Teriyaki_salmon.jpg","artist":"JIP","license":"CC BY-SA 4.0"}},{"id":"qm-egg-and-potato-hash","name":"Egg and potato hash","cat":"Pork","country":"France","instr":"Boil the potatoes in cubes for 8 minutes and drain.\r\nFry the lardons and onion for 5 minutes, add the potatoes and fry for 12 minutes until crisp.\r\nMake four hollows, crack in the eggs, cover and cook for 4 minutes. Sprinkle with parsley and serve with salad.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Corned_beef_hash_at_the_Creamery_%28Nina%27s_breakfast%29.jpg/960px-Corned_beef_hash_at_the_Creamery_%28Nina%27s_breakfast%29.jpg","tags":["Quick","Eggs"],"yt":"","src":"","ingr":[{"n":"Potatoes","m":"800g"},{"n":"Bacon Lardon","m":"150g"},{"n":"Onion","m":"1"},{"n":"Eggs","m":"4"},{"n":"Parsley","m":"2 tbs chopped"},{"n":"Lettuce","m":"1"}],"time":30,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Corned_beef_hash_at_the_Creamery_(Nina%27s_breakfast).jpg","artist":"Ginny and John Woods","license":"CC BY-SA 2.0"}},{"id":"qm-pasta-with-sausage-and-tomato","name":"Pasta with sausage and tomato","cat":"Pork","country":"Italy","instr":"Cook the pasta.\r\nSqueeze the sausage meat out of the skins and fry with the onion for 8 minutes, breaking it up.\r\nAdd the garlic and passata and simmer for 10 minutes, then stir in the crème fraîche.\r\nToss with the pasta and serve with parmesan.","thumb":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/Penne_with_sausage_and_pumpkin_rag%C3%B9_%288462238749%29.jpg/960px-Penne_with_sausage_and_pumpkin_rag%C3%B9_%288462238749%29.jpg","tags":["Quick","Pasta","Family"],"yt":"","src":"","ingr":[{"n":"Penne Rigate","m":"400g"},{"n":"Sausages","m":"4"},{"n":"Onion","m":"1"},{"n":"Garlic","m":"1 clove"},{"n":"Passata","m":"500ml"},{"n":"Creme Fraiche","m":"3 tbs"},{"n":"Parmesan","m":"40g"}],"time":25,"photo":{"page":"https://commons.wikimedia.org/wiki/File:Penne_with_sausage_and_pumpkin_rag%C3%B9_(8462238749).jpg","artist":"Luca Nebuloni from Milan, Italy","license":"CC BY 2.0"}}];
